insert into public.course_modules (id, course_id, title, description, position) values
  ('ca0a03bc-9a5c-558f-11b7-093682de43c3', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'Ingénierie sociale et hameçonnage', 'Tu apprends ici à voir les attaques qui passent par l’humain avant de passer par la technique : appels, SMS, courriels, QR codes et faux prétextes. Critères de réussite : repérer un levier de manipulation dans un message ou un appel ; vérifier un expéditeur, un lien ou une demande d’argent par un second canal ; choisir une réaction sûre sans cliquer ni divulguer de secret.', 3),
  ('465bec1c-2dfb-9ae1-24ff-c2889f98b52b', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'Mots de passe et authentification', 'Ce module transforme la sécurité des comptes en méthode concrète : choisir de meilleurs secrets, ajouter le bon second facteur et réagir proprement après une fuite. Critères de réussite : expliquer pourquoi la réutilisation est dangereuse ; comparer SMS, TOTP et clés d’accès selon le risque ; appliquer un plan d’action priorisé après une alerte de fuite.', 4),
  ('1c08c887-9d58-d609-e1b6-4cb0e3b85b54', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'Appareils, sauvegardes et réseaux du quotidien', 'Ce module t’apprend à protéger les appareils que tu utilises vraiment : ordinateurs, téléphones, box et copies de secours. Critères de réussite : repérer un poste mal entretenu, vérifier qu’une stratégie de sauvegarde est crédible, et choisir des protections adaptées contre le vol, la perte et les réseaux non fiables.', 5),
  ('ecda4f3a-81bc-0e79-a332-df988e534741', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'Cryptographie pour débutants', 'Tu y distingues les notions cryptographiques utiles sans formules inutiles, puis tu apprends à lire les signes de confiance affichés par les outils du quotidien. Critères de réussite : reconnaître un encodage, une empreinte et une signature, expliquer le rôle des clés publiques et privées, et juger correctement ce que garantit HTTPS sur le web.', 6),
  ('c671b9d4-c599-d9f7-05ac-73248624d87d', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'Risques, données personnelles et conformité', 'Tu relies ici l’analyse de risques aux obligations de protection des données et à l’organisation quotidienne de la sécurité. Critères de réussite : construire un registre de risques lisible ; distinguer les principes, droits et obligations liés aux données personnelles ; proposer des règles et indicateurs réalistes pour une petite structure.', 7),
  ('637ef880-3754-45f8-323a-eb7a8f6f7361', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'Réagir à un incident', 'Ce module t’apprend à passer du signal au plan d’action, puis du constat à la restitution utile sans casser les preuves ni improviser le droit. Critères de réussite : conduire une réponse à incident en six étapes ; reconstruire une chronologie fiable et préserver les preuves ; produire un audit d’hygiène factuel avec score et recommandations.', 8)
insert into public.lessons (id, course_id, module_id, title, summary, content, duration_minutes, xp_reward, position) values
  ('1cfe5e31-d5de-9945-c10a-1239974a969c', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', '9eb524ae-1b27-a325-539d-bda421c0627e', 'Les principes de la sécurité : confidentialité, intégrité, disponibilité, moindre privilège', 'Maîtrise les propriétés et principes de base qui structurent toute bonne défense : C, I, D, authenticité, traçabilité, séparation des tâches et défense en profondeur.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer confidentialité, intégrité, disponibilité, authenticité, traçabilité et non-répudiation, distinguer identification, authentification et autorisation, appliquer le moindre privilège, et lire des couches de défense en profondeur."},{"type":"callout","content":"Prérequis : avoir suivi « Qu’est-ce que la cybersécurité ? » et « Les types de menaces informatiques »."},{"type":"callout","content":"Mise en situation : L’association Teranga tient sa comptabilité et ses dossiers de bénévoles dans un espace partagé. Au début, tout le monde a accès à tout. Puis une facture est modifiée par erreur, un ancien bénévole garde encore son compte et personne ne sait qui a téléchargé un dossier sensible. L’équipe doit donc organiser les accès au lieu de compter sur la confiance seule."},{"type":"callout","content":"Vidéo à venir : Les grands principes de sécurité que tu retrouveras partout"},{"type":"text","content":"La triade confidentialité, intégrité, disponibilité reste la base, mais elle ne suffit pas toujours. L’authenticité répond à la question « est-ce bien la bonne personne ou machine ? ». La traçabilité permet de retrouver qui a fait quoi et quand. La non-répudiation rend plus difficile le fait de nier une action, par exemple avec une signature numérique et des journaux bien protégés."},{"type":"schema","content":"Question à poser        Principe associé\nQui es-tu ?             identification\nPeux-tu le prouver ?    authentification\nÀ quoi as-tu droit ?    autorisation\nQui l’a fait ?          imputabilité\nPeut-on le retracer ?   traçabilité"},{"type":"text","content":"Le moindre privilège signifie qu’un compte ne reçoit que les droits strictement nécessaires à sa mission. Le besoin d’en connaître va dans le même sens : on n’ouvre l’information qu’aux personnes qui en ont besoin. La séparation des tâches évite qu’une seule personne puisse initier, valider et payer une opération sensible."},{"type":"schema","content":"Défense en profondeur\n[Humain]\n   [Données]\n      [Application]\n         [Appareil]\n            [Réseau]\n               [Physique]\n\nIdée : plusieurs couches, pas une seule barrière"},{"type":"text","content":"La défense en profondeur empile des couches : physique, réseau, appareil, application, données et humain. Si l’une échoue, une autre peut encore limiter l’impact. La sécurité par défaut démarre avec des options sûres, par exemple un compte standard. La sécurité par conception pense aux risques dès le départ. La « confiance zéro » se résume ainsi : ne fais confiance à personne par défaut, vérifie chaque accès."},{"type":"text","content":"Démonstration guidée : regarde quels droits ton compte possède réellement. Sous Windows, « whoami /groups » liste les groupes de sécurité. Sous Linux, « id » montre l’identifiant utilisateur et les groupes. Un compte standard sert au quotidien ; un compte administrateur ne doit intervenir que lorsque c’est nécessaire. Sur téléphone, vérifie surtout les autorisations accordées aux applications."},{"type":"code","content":"Windows\nwhoami /groups\n\nLinux\nid\n\nExemple de lecture\nuid=1000(awa) gid=1000(awa) groups=1000(awa),27(sudo)\n\nSi ton compte appartient à un groupe d’administration,\ntu dois l’utiliser avec encore plus de prudence.","language":"text"},{"type":"example","content":"Exemple corrigé : l’association Teranga place sa comptabilité dans un espace où seule Nadia peut modifier, où le président peut lire sans écrire, et où les autres bénévoles n’ont aucun accès. La validation d’un paiement est séparée de sa préparation. Ici, confidentialité, intégrité, traçabilité et moindre privilège travaillent ensemble."},{"type":"callout","content":"Erreurs fréquentes : donner les droits administrateur à tout le monde pour éviter les demandes d’assistance ; partager un même mot de passe entre collègues, ce qui détruit l’imputabilité ; croire qu’un bon antivirus remplace la séparation des tâches ; n’avoir qu’une seule couche de protection et tout perdre quand elle échoue."},{"type":"callout","content":"Sécurité : les commandes de vérification de compte doivent être lancées sur ton propre poste ou avec l’accord de la structure. Lire les droits d’un système tiers sans autorisation reste une action de reconnaissance non légitime."},{"type":"callout","content":"À retenir : les principes de sécurité servent à décider qui peut faire quoi, comment on le vérifie et comment on limite les dégâts. Le moindre privilège, la séparation des tâches et la défense en profondeur réduisent fortement le risque sans exiger une grande infrastructure."},{"type":"callout","content":"Pour pratiquer : ouvre « TP 5 : construire un registre de risques ». Pour chaque scénario, note quelle propriété C, I ou D est touchée, puis propose un contrôle de moindre privilège ou une couche de défense en plus. Termine par le quiz de la leçon."},{"type":"resource","content":"ANSSI : guide d’hygiène informatique","url":"https://cyber.gouv.fr/publications/guide-dhygiene-informatique"},{"type":"resource","content":"CNIL : sécurité, authentifier les utilisateurs","url":"https://www.cnil.fr/fr/securite-authentifier-les-utilisateurs"},{"type":"resource","content":"NIST : cadre de cybersécurité (CSF) (en anglais)","url":"https://www.nist.gov/cyberframework"}]}'::jsonb, 22, 30, 3),
  ('c0fc8876-2b34-1b63-1e31-e84b80f92dc4', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', '31387ec3-76c8-0172-1b3a-e2409798e572', 'Les métiers et les parcours de la cybersécurité', 'Explore les grandes familles de métiers de la cybersécurité, les compétences à développer, les parcours accessibles avec peu de moyens et la manière de construire un portfolio crédible.', '{"blocks":[{"type":"callout","content":"Objectifs : citer les grandes familles de métiers, distinguer compétences techniques et non techniques, relier un métier à une mission quotidienne, construire un parcours de départ réaliste, et choisir une prochaine étape d’apprentissage."},{"type":"callout","content":"Prérequis : avoir suivi « Les acteurs de la cybersécurité » ou déjà savoir ce qu’est une blue team."},{"type":"callout","content":"Mise en situation : Binta veut entrer en cybersécurité, mais elle dispose surtout d’un téléphone, d’un ordinateur modeste et de peu de budget. Les annonces demandent parfois cloud, réseau, Linux, audit et code à la fois. Si elle tente de tout apprendre en même temps, elle se décourage. Il lui faut donc une carte simple des métiers et un chemin de progression réaliste."},{"type":"callout","content":"Vidéo à venir : Trouver ta voie dans les métiers de la cybersécurité"},{"type":"text","content":"La cybersécurité regroupe plusieurs familles de métiers. L’analyste SOC surveille et qualifie les alertes. La réponse à incident cherche à comprendre puis contenir. Le test d’intrusion évalue les défenses dans un cadre autorisé. La gouvernance, les risques et la conformité traduisent les exigences en politiques et preuves. D’autres rôles se concentrent sur la sécurité des applications, du cloud, l’architecture, la protection des données ou la sensibilisation."},{"type":"schema","content":"Métier                  Mission du quotidien         Parcours CyberPingo conseillé\nAnalyste SOC            lire journaux et alertes      fondamentaux, réseaux\nRéponse à incident      contenir, documenter          fondamentaux, réseaux\nPentest                 tester avec autorisation      réseaux, web, Linux\nGRC / conformité        cartographier contrôles       fondamentaux\nAppSec                  sécuriser le code             web, fondamentaux\nCloud security          sécuriser services cloud      réseaux, fondamentaux"},{"type":"text","content":"Les compétences techniques ne suffisent pas. Il faut aussi savoir rédiger, expliquer, écouter, documenter ses choix et respecter l’éthique. Pour un débutant avec peu de moyens, l’ordre utile est souvent : bases générales, réseaux, systèmes, lecture de journaux, web, puis spécialisation progressive. Les laboratoires gratuits et les mini comptes rendus écrits comptent beaucoup."},{"type":"schema","content":"Compétences à cultiver\nTechnique : réseaux, Linux, journaux, web, scripts\nMéthode   : observation, priorisation, preuve\nHumain    : rédaction, pédagogie, éthique, calme\nPortfolio : compte rendu, capture d’écran, conclusion"},{"type":"text","content":"Un portfolio crédible ne demande pas un grand laboratoire maison. Il peut contenir des comptes rendus de TP, une analyse d’incident fictif ou une explication claire d’une capture réseau. Les certifications existent, mais elles ne promettent pas un emploi à elles seules. Choisis-les selon ton objectif, leur coût réel et leur reconnaissance locale. Le référentiel NICE du NIST aide à explorer les rôles."},{"type":"text","content":"Démonstration guidée : pars de ce que tu aimes déjà faire. Si tu aimes comprendre pourquoi un service ne répond plus, commence par réseaux, journaux et réponse à incident. Si tu préfères expliquer et cadrer, regarde aussi la gouvernance. Sur téléphone, rédige ce plan en trois colonnes : « j’aime », « je dois apprendre », « prochaine action »."},{"type":"code","content":"Plan de départ de Binta\n\nJ’aime : enquêter, lire des journaux, expliquer\nÀ apprendre : bases réseaux, Linux, authentification\nProchaine action : finir les fondamentaux, puis faire\nun TP réseau et rédiger un court compte rendu\nObjectif 90 jours : 3 comptes rendus publiés","language":"text"},{"type":"example","content":"Exemple corrigé : Binta aime comprendre les incidents et rédiger clairement. Le parcours le plus cohérent pour elle est : fondamentaux, puis réseaux, puis pratique des journaux et de la réponse à incident. Elle complète chaque étape par un compte rendu court. Ce choix est meilleur qu’un départ direct en pentest, parce qu’il construit d’abord la méthode."},{"type":"callout","content":"Erreurs fréquentes : chercher le « métier parfait » avant les bases ; croire qu’il faut choisir entre technique et communication ; accumuler des certifications sans preuves concrètes ; copier un portfolio sans expliquer ce qui a été compris."},{"type":"callout","content":"Sécurité : si tu pratiques sur des plateformes ou des laboratoires, reste dans le périmètre prévu et respecte les règles du service. Un portfolio crédible montre ce que tu sais faire légalement et proprement, pas ce que tu as forcé sans autorisation."},{"type":"callout","content":"À retenir : la cybersécurité est un ensemble de métiers complémentaires. Commence par des bases solides, documente ce que tu apprends, puis spécialise-toi progressivement. Un bon portfolio prouve ta méthode."},{"type":"callout","content":"Pour pratiquer : ouvre « Incident : un compte de messagerie compromis ». Observe les rôles nécessaires dans la chronologie, puis écris un mini compte rendu sur le métier qui t’attire le plus. Termine par le quiz de la leçon."},{"type":"resource","content":"NIST : référentiel NICE des compétences en cybersécurité (en anglais)","url":"https://www.nist.gov/itl/applied-cybersecurity/nice/nice-framework-resource-center"},{"type":"resource","content":"Cybermalveillance.gouv.fr : prévention et assistance aux victimes","url":"https://www.cybermalveillance.gouv.fr/"}]}'::jsonb, 20, 25, 2),
  ('5d0743db-5594-311d-590f-66ba8acf117c', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', '31387ec3-76c8-0172-1b3a-e2409798e572', 'Normes, référentiels et lois : le cadre de la sécurité', 'Comprends à quoi servent les normes, cadres, lois et bonnes pratiques, comment les distinguer, et pourquoi être conforme n’assure pas automatiquement d’être vraiment en sécurité.', '{"blocks":[{"type":"callout","content":"Objectifs : distinguer loi, norme, cadre et bonne pratique, citer les grands référentiels utiles en cybersécurité, expliquer l’intérêt d’un système de management de la sécurité, et choisir un cadre adapté à une petite structure."},{"type":"callout","content":"Prérequis : avoir suivi « Les principes de la sécurité » et « Les acteurs de la cybersécurité »."},{"type":"callout","content":"Mise en situation : Le Cabinet Moussa doit rassurer un partenaire et formaliser ses pratiques. La direction entend parler d’ISO 27001, de NIST, du RGPD, de l’ANSSI, d’EBIOS et de clauses contractuelles, mais tout semble mélangé. Si l’équipe ne distingue pas loi, norme et bonne pratique, elle risque de faire beaucoup de papier sans gagner en sécurité réelle."},{"type":"callout","content":"Vidéo à venir : Le cadre de la sécurité : lois, normes et référentiels"},{"type":"text","content":"Un cadre de sécurité sert à éviter l’improvisation. Une loi crée des obligations juridiques. Une norme décrit des exigences ou des méthodes partagées, parfois certifiables. Un cadre organise les activités sans forcément viser une certification. Une bonne pratique est un conseil concret. La loi oblige, la norme structure, le cadre guide, la bonne pratique aide à agir."},{"type":"schema","content":"Nom                    Type          Pour qui ?          Usage courant\nRGPD                   loi           organismes traitant  protéger les données\nConvention de Malabo   convention    États et structures  repère africain général\nISO/IEC 27001          norme         organisations        SMSI certifiable\nISO/IEC 27002          norme         organisations        catalogue de mesures\nNIST CSF 2.0           cadre         tout type d’orga     piloter la cybersécurité"},{"type":"text","content":"ISO/IEC 27001 décrit un système de management de la sécurité de l’information, souvent abrégé SMSI : gouvernance, objectifs, responsabilités, amélioration continue. ISO/IEC 27002 complète ce cadre avec des mesures de sécurité. Le NIST Cybersecurity Framework 2.0 organise la démarche en fonctions : gouverner, identifier, protéger, détecter, répondre, rétablir. Le guide d’hygiène de l’ANSSI rassemble une quarantaine de mesures concrètes. EBIOS Risk Manager aide à analyser les risques. Tu verras aussi MITRE ATT&CK pour décrire des techniques d’attaque, l’OWASP Top 10 pour les risques web fréquents, et PCI DSS pour encadrer la sécurité des données de carte de paiement."},{"type":"schema","content":"Conformité utile, mais limitée\nConforme sur le papier   !=   protégé dans la pratique\n\nIl faut aussi :\n- mesures réellement appliquées\n- preuves et vérifications\n- amélioration continue\n- adaptation au risque réel"},{"type":"text","content":"Les lois sur les données personnelles ajoutent un autre niveau. Le RGPD peut s’appliquer au-delà de l’Union européenne selon la situation. La Convention de Malabo, adoptée en 2014 et entrée en vigueur en 2023, donne un repère africain important, et de nombreux pays ont leur propre loi et autorité à rechercher. Les contrats imposent aussi parfois chiffrement, journalisation, délai de notification ou audit. Être conforme ne veut pourtant pas dire être en sécurité partout."},{"type":"text","content":"Démonstration guidée : prends une petite structure imaginaire et associe chaque besoin au bon cadre. Gouvernance globale : NIST CSF. SMSI formel : ISO 27001. Actions concrètes rapides : guide d’hygiène de l’ANSSI. Analyse de risques : EBIOS RM. Données personnelles : RGPD, Convention de Malabo et lois nationales. Sur téléphone, fais ce tri dans une note."},{"type":"code","content":"Besoins du Cabinet Moussa\n\n1. Prioriser les actions de base -> guide d’hygiène ANSSI\n2. Structurer la gouvernance -> NIST CSF 2.0\n3. Monter un SMSI certifiable -> ISO/IEC 27001\n4. Analyser les scénarios de risque -> EBIOS RM\n5. Encadrer les données personnelles -> RGPD,\n   Convention de Malabo, lois nationales","language":"text"},{"type":"example","content":"Exemple corrigé : une petite association n’a pas besoin de tout déployer d’un coup. Elle peut commencer par le guide d’hygiène de l’ANSSI, utiliser le NIST CSF pour classer ses actions, puis faire une première analyse de risques avec EBIOS RM. Si un partenaire exige une démarche plus formelle, elle pourra ensuite regarder ISO 27001."},{"type":"callout","content":"Erreurs fréquentes : confondre conformité et sécurité réelle ; croire qu’un seul référentiel couvre tous les besoins ; ignorer les obligations contractuelles ; lancer une certification avant les pratiques de base."},{"type":"callout","content":"Sécurité : les référentiels guident une protection défensive. Si tu analyses un dispositif réel, respecte la confidentialité des preuves, les clauses contractuelles et les règles locales sur les données personnelles."},{"type":"callout","content":"À retenir : loi, norme, cadre et bonne pratique ne jouent pas le même rôle. ISO 27001 structure un SMSI, le NIST CSF aide à piloter, le guide d’hygiène de l’ANSSI apporte des gestes concrets, et EBIOS RM aide à penser le risque. La conformité ne remplace pas l’application réelle des mesures."},{"type":"callout","content":"Pour pratiquer : ouvre « Projet final : auditer la sécurité du Centre Numérique Soleil ». Repère quelles recommandations relèvent des mesures d’hygiène, du pilotage ou de l’analyse des risques, puis termine par le quiz de la leçon."},{"type":"resource","content":"ANSSI : guide d’hygiène informatique","url":"https://cyber.gouv.fr/publications/guide-dhygiene-informatique"},{"type":"resource","content":"NIST : cadre de cybersécurité (CSF) (en anglais)","url":"https://www.nist.gov/cyberframework"},{"type":"resource","content":"ANSSI : la méthode EBIOS Risk Manager","url":"https://cyber.gouv.fr/securisation/analyse-des-risques/methode-ebios-rm/"}]}'::jsonb, 22, 30, 3),
  ('adc9689b-9ce8-4e74-a389-2165989d6350', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'ca0a03bc-9a5c-558f-11b7-093682de43c3', 'L’ingénierie sociale : comment on manipule les gens', 'Comprendre comment un attaquant exploite la confiance, l’urgence ou la curiosité pour contourner les protections techniques, puis adopter des réflexes simples pour stopper la manipulation.', '{"blocks":[{"type":"callout","content":"Objectifs : identifier les principaux leviers psychologiques, reconnaître les techniques courantes d’ingénierie sociale, décrire les cinq étapes d’une attaque, repérer le moment où elle aurait pu être stoppée et appliquer un réflexe de vérification par un second canal."},{"type":"callout","content":"Prérequis : avoir vu les familles de menaces informatiques ou connaître la différence entre une attaque technique et une manipulation humaine."},{"type":"callout","content":"Mise en situation : Nadia reçoit l’appel d’une personne qui se présente comme le support informatique de Baobab Tech. La voix parle vite, cite le nom du directeur et explique qu’un incident bloque les comptes. Nadia doit agir « tout de suite » pour éviter une coupure. Elle hésite, car l’interlocuteur semble bien informé et très sûr de lui."},{"type":"callout","content":"Vidéo à venir : Ingénierie sociale : reconnaître la manipulation avant de cliquer"},{"type":"text","content":"L’ingénierie sociale consiste à obtenir d’une personne une action, une information ou un accès qu’elle n’aurait pas dû donner. L’attaquant ne casse pas d’abord la machine : il influence un humain. Il cherche par exemple un mot de passe, un code de validation, un virement urgent, l’ouverture d’une pièce jointe ou l’accès à un bâtiment. La cible peut être un employé, un bénévole, un étudiant, un proche ou toi-même sur ton téléphone."},{"type":"schema","content":"Levier                Signal d’alarme              Réflexe\nAutorité              « Le directeur l’exige »       Vérifier la demande\nUrgence               « Dans 5 minutes sinon... »    Ralentir\nCuriosité             « Regarde ce document secret » Ouvrir avec prudence\nPeur                  « Ton compte sera bloqué »     Passer par un canal sûr\nAppât du gain         « Tu as gagné »                Chercher la contrepartie"},{"type":"text","content":"Les leviers psychologiques reviennent souvent : l’autorité, l’urgence, la rareté, la réciprocité, la preuve sociale, la sympathie, la peur, la curiosité et l’appât du gain. Un attaquant peut dire « tout le service l’a déjà fait » pour créer une preuve sociale, ou « je t’aide à distance » pour se rendre sympathique. Il peut aussi mélanger plusieurs leviers. Plus le message te pousse à agir vite et sans contrôle, plus le risque augmente."},{"type":"schema","content":"Anatomie d’une attaque en 5 étapes\n1. Reconnaissance : collecte d’infos publiques\n2. Prétexte : histoire crédible et rôle joué\n3. Contact : mail, SMS, appel, QR code, visite\n4. Action : obtenir clic, code, accès ou argent\n5. Exploitation : réutiliser ce qui a été obtenu"},{"type":"text","content":"La reconnaissance prépare l’attaque. Les réseaux sociaux, les signatures de courriel, un organigramme public, une affiche à l’accueil ou une conversation entendue dans un transport donnent déjà beaucoup d’indices. Ensuite vient le prétexte : faux support technique, faux collègue, faux recruteur, faux livreur, faux agent du service de paiement mobile. Les techniques varient : hameçonnage, SMS frauduleux, appel, QR code, clé USB abandonnée, filature à la porte, usurpation d’un collègue ou d’un prestataire."},{"type":"text","content":"Démonstration guidée : imagine qu’un appel commence par « je vois une activité anormale sur ton compte, donne-moi le code affiché pour que je bloque l’attaque ». Arrête-toi avant de répondre et déroule trois questions : qui parle réellement, par quel numéro rappelable, et quelle procédure interne autorise cette demande ? Si tu ne peux pas répondre clairement aux trois, coupe l’échange, retrouve le numéro officiel et appelle toi-même. Sur téléphone, le principe est le même : ne rappelle jamais le numéro dicté dans l’appel ou le SMS."},{"type":"code","content":"Appel reçu : « Bonjour, ici le support. J’ai besoin du code affiché sur ton téléphone. »\n\nRéponse sûre :\n1. « Je ne donne jamais de code pendant un appel. »\n2. « Je note votre demande. »\n3. Je raccroche.\n4. J’appelle le numéro officiel de l’organisation.\n5. Je signale la tentative à mon responsable ou au canal prévu.","language":"text"},{"type":"text","content":"Les contre-mesures sont surtout organisationnelles. Vérifier par un second canal, ralentir, demander une double validation pour l’argent ou les accès sensibles, limiter les privilèges, et installer une culture sans blâme : une personne doit pouvoir signaler un doute sans se faire ridiculiser. La meilleure défense n’est pas d’être « malin », mais d’avoir une procédure simple et répétable."},{"type":"example","content":"Exemple corrigé : Koffi reçoit l’appel d’un faux support. Le prétexte est crédible, car l’attaquant connaît le nom de son service. Les leviers utilisés sont l’autorité, l’urgence et la peur. L’attaque aurait pu s’arrêter dès la demande du code de validation, car un support légitime n’a pas besoin de ce secret. La bonne réaction est de raccrocher, de rappeler via le numéro officiel et de signaler la tentative."},{"type":"callout","content":"Erreurs fréquentes : croire qu’une attaque réussit seulement contre les personnes « inattentives », alors que la pression émotionnelle touche tout le monde ; répondre dans l’instant à une demande urgente sans chercher un second canal ; publier trop d’informations de contexte sur les réseaux sociaux ; punir le signalement d’une erreur, ce qui pousse ensuite au silence."},{"type":"callout","content":"Sécurité : n’imite pas un support, un collègue ou un service de paiement mobile en dehors d’un exercice autorisé. Tester quelqu’un sans accord clair peut causer un préjudice réel et reste une mauvaise pratique, voire une infraction selon le contexte."},{"type":"callout","content":"À retenir : l’ingénierie sociale cible d’abord l’humain. Les signes les plus utiles sont l’urgence, l’autorité non vérifiée et la demande d’un secret ou d’une action inhabituelle. Un second canal, une procédure simple et une culture sans blâme stoppent beaucoup d’attaques."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 1 : disséquer un courriel d’hameçonnage », observe comment l’attaquant pousse à agir vite, puis repère dans le SMS d’arnaque les leviers utilisés et la bonne réaction. Termine par le quiz de la leçon."},{"type":"resource","content":"Wikipédia : ingénierie sociale","url":"https://fr.wikipedia.org/wiki/Ing%C3%A9nierie_sociale_(s%C3%A9curit%C3%A9_de_l%27information)"},{"type":"resource","content":"Cybermalveillance.gouv.fr : fiche réflexe contre l’hameçonnage","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/hameconnage-phishing"},{"type":"resource","content":"CISA : Secure Our World, les gestes de base (en anglais)","url":"https://www.cisa.gov/secure-our-world"}]}'::jsonb, 20, 25, 1),
  ('f9873b02-e1f6-24c4-5bce-7081d13404d5', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'ca0a03bc-9a5c-558f-11b7-093682de43c3', 'Reconnaître un courriel d’hameçonnage : expéditeur, liens et pièces jointes', 'Apprendre à lire un message suspect sans se faire piéger : adresse réelle, en-têtes, domaine d’un lien, pièces jointes et bons réflexes si l’on a cliqué ou saisi un mot de passe.', '{"blocks":[{"type":"callout","content":"Objectifs : distinguer le nom affiché de l’adresse réelle, lire les champs essentiels d’un en-tête, interpréter simplement SPF, DKIM et DMARC, repérer un lien trompeur ou une pièce jointe risquée et choisir la bonne réaction après un clic."},{"type":"callout","content":"Prérequis : avoir suivi la leçon sur l’ingénierie sociale ou savoir qu’un message peut manipuler l’émotion pour obtenir une action."},{"type":"callout","content":"Mise en situation : Awa reçoit un courriel censé venir de la comptabilité d’Atlas. Le nom affiché semble correct, mais le message menace de bloquer son accès si elle n’ouvre pas la pièce jointe avant midi. Sur son téléphone, le lien paraît court et rassurant. Avant de cliquer, Awa doit lire ce que le message révèle vraiment."},{"type":"callout","content":"Vidéo à venir : Lire un courriel suspect sans tomber dans le piège"},{"type":"text","content":"Un courriel d’hameçonnage imite souvent une organisation, un collègue ou un service connu pour te pousser à cliquer, ouvrir une pièce jointe ou donner une information sensible. Le premier piège est visuel : le nom affiché n’est pas la preuve de l’expéditeur réel. Ton client de messagerie peut montrer « Comptabilité Atlas » alors que l’adresse véritable est autre chose. Il faut donc regarder l’adresse complète et, si besoin, les en-têtes du message."},{"type":"schema","content":"Nom affiché ≠ adresse réelle\n\nAffiché : Comptabilité Atlas\nFrom    : facturation@atlas-service.example.org\nReply-To: recouvrement@example.net\n\nSignal : la réponse part vers example.net,\npas vers le domaine affiché à l’écran."},{"type":"text","content":"Les en-têtes racontent le trajet du message. « From » indique l’adresse annoncée à l’utilisateur. « Reply-To » peut forcer les réponses vers une autre boîte. « Return-Path » montre souvent où reviennent les erreurs de distribution. Les lignes « Received » décrivent les serveurs traversés, du plus récent au plus ancien. Enfin, « Authentication-Results » résume des contrôles utiles : SPF vérifie surtout si l’adresse utilisée pendant l’envoi, souvent visible via « Return-Path » ou « MAIL FROM », autorise bien le serveur d’envoi, DKIM vérifie une signature associée au domaine indiqué par « d= », et DMARC vérifie surtout si le domaine affiché dans « From » est aligné avec un SPF ou un DKIM qui a réussi. « pass » veut dire que le contrôle a réussi, « fail » qu’il a échoué, et « none » qu’il n’y a pas de résultat utile pour ce contrôle."},{"type":"schema","content":"Extrait d’en-têtes annoté\nAuthentication-Results: mx.example.org;\n spf=fail smtp.mailfrom=atlas-service.example.org\n dkim=none header.d=none\n dmarc=fail header.from=atlas-service.example.org\nFrom: \"Comptabilité Atlas\" <facturation@atlas-service.example.org>\nReply-To: aide@example.net\n\nLecture simple : fail = échec, none = absent,\net la réponse veut partir ailleurs."},{"type":"text","content":"Un lien se lit de droite à gauche à partir du domaine enregistrable. Dans « paiement.atlas.example.org.verif-example.net », le vrai domaine est « verif-example.net », pas « atlas.example.org ». Les faux domaines utilisent aussi des lettres échangées, des tirets ou des sous-domaines trompeurs. Les liens raccourcis cachent encore plus l’adresse finale. Sur ordinateur, le survol aide à voir la destination. Sur téléphone, mieux vaut appuyer longuement si l’application l’autorise, ou taper soi-même l’adresse officielle dans le navigateur."},{"type":"text","content":"Les pièces jointes dangereuses cherchent à être ouvertes vite : double extension, archive protégée par mot de passe, document qui réclame une macro, ou fichier inattendu. Le cadenas d’un site ne prouve pas sa légitimité : il indique surtout que la connexion est chiffrée. Un faux site de connexion peut donc afficher HTTPS et rester un piège. Les signaux les plus fiables restent l’adresse réelle, le domaine du lien, la demande d’un secret, l’urgence inhabituelle et la cohérence avec le contexte."},{"type":"text","content":"Démonstration guidée : dans ton client mail, cherche l’option « Afficher l’original », « Afficher la source » ou son équivalent. Sur téléphone, elle se cache souvent dans le menu du message. Lis ensuite quatre zones dans cet ordre : From, Reply-To, Authentication-Results, puis les premiers Received. Tu ne dois pas tout comprendre techniquement. Le but est de répondre à trois questions pratiques : qui prétend envoyer, qui recevra la réponse, et les contrôles du domaine concordent-ils ou non ?"},{"type":"code","content":"Checklist minimale d’un courriel suspect\n1. Afficher l’original ou la source du message\n2. Lire From et Reply-To\n3. Lire Authentication-Results\n4. Regarder le domaine du lien sans cliquer\n5. Si doute : fermer, signaler, puis taper l’adresse officielle soi-même","language":"text"},{"type":"example","content":"Exemple corrigé : Awa voit le lien « https://espace.atlas.example.org.verif-example.net/connexion ». En le lisant de droite à gauche, elle repère que le vrai domaine est « verif-example.net ». Les en-têtes montrent « spf=fail » et « dmarc=fail », et la réponse partirait vers une autre adresse. Le bon choix est de ne pas cliquer, de signaler le message et d’ouvrir elle-même le site officiel si elle veut vérifier son compte. Si elle avait déjà saisi son mot de passe, elle devrait le changer depuis le vrai site, activer la double authentification et prévenir l’organisation."},{"type":"callout","content":"Erreurs fréquentes : se fier au seul nom affiché ; croire que le cadenas garantit l’identité du site ; ouvrir une pièce jointe inattendue « juste pour voir » ; répondre au message suspect pour demander si c’est vrai, alors que la réponse peut partir vers l’attaquant."},{"type":"callout","content":"Sécurité : n’ouvre pas volontairement des pièces jointes ou des liens suspects hors d’un laboratoire prévu pour cela. Si tu analyses un message réel, fais-le en lecture seule et suis la procédure de signalement de ton organisation."},{"type":"callout","content":"À retenir : pour juger un courriel, lis l’adresse réelle, les en-têtes utiles et le vrai domaine d’un lien. SPF, DKIM et DMARC donnent des indices, mais ils ne remplacent pas le contexte. En cas de doute, ne clique pas, signale et repasse par une adresse officielle saisie par toi."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 1 : disséquer un courriel d’hameçonnage », lis l’expéditeur réel, les liens et la pièce jointe, puis compare tes indices avec le SMS d’arnaque du même TP. Termine par le quiz de la leçon."},{"type":"resource","content":"Cybermalveillance.gouv.fr : fiche réflexe contre l’hameçonnage","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/hameconnage-phishing"},{"type":"resource","content":"RFC 5322 : format des messages électroniques (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc5322"},{"type":"resource","content":"RFC 7489 : DMARC (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc7489"}]}'::jsonb, 24, 30, 2),
  ('998aebd3-c337-e876-7d2c-f5c15fd999c7', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'ca0a03bc-9a5c-558f-11b7-093682de43c3', 'Arnaques par SMS, appels et paiements mobiles', 'Identifier les escroqueries qui visent surtout le téléphone : SMS, appels, QR codes, faux transferts, échange de carte SIM et faux comptes de messagerie instantanée.', '{"blocks":[{"type":"callout","content":"Objectifs : reconnaître les scénarios mobiles les plus courants, expliquer pourquoi un code reçu par SMS ne doit jamais être communiqué, repérer les signaux d’un faux transfert ou d’un faux conseiller et choisir la réaction la plus sûre sur téléphone."},{"type":"callout","content":"Prérequis : avoir vu les bases de l’ingénierie sociale ou savoir qu’une urgence émotionnelle peut pousser à une mauvaise décision."},{"type":"callout","content":"Mise en situation : Mamadou reçoit un SMS : « colis en attente, frais à régler ». Une heure plus tard, une autre personne l’appelle en disant qu’un transfert mobile a été envoyé par erreur et qu’il faut le rembourser tout de suite. En parallèle, un proche lui écrit sur messagerie instantanée : « j’ai changé de numéro ». Tout arrive sur le même téléphone, au moment où Mamadou est pressé."},{"type":"callout","content":"Vidéo à venir : SMS, appels et paiements mobiles : les réflexes qui évitent l’arnaque"},{"type":"text","content":"Le téléphone concentre beaucoup de choses : messagerie, banque, paiement mobile, réseaux sociaux, codes de validation et parfois comptes professionnels. C’est pour cela qu’il attire autant les escrocs. Les scénarios les plus courants sont les SMS frauduleux au sujet d’un colis, d’une amende, d’un gain ou d’un compte bloqué ; les appels de faux conseillers ; les faux emplois ou faux investissements ; les QR codes piégés ; et les applications téléchargées hors boutique officielle."},{"type":"schema","content":"Scénario                        Levier            Réflexe\nSMS « colis en attente »        Urgence           Taper l’adresse officielle\nAppel du « conseiller »         Autorité          Raccrocher et rappeler\n« Transfert envoyé par erreur » Pression morale   Vérifier le solde réel\n« J’ai changé de numéro »       Confiance         Vérifier par un autre canal\nQR code inconnu                 Curiosité         Demander l’URL avant d’ouvrir"},{"type":"text","content":"Le paiement mobile est une cible classique. Un escroc peut prétendre avoir envoyé de l’argent par erreur et te demander un remboursement immédiat avant que tu aies vérifié le solde réel dans l’application officielle. Un autre peut se faire passer pour un agent du service de paiement mobile et demander un code de validation ou un code PIN. Ce code ne se partage jamais. Un vrai conseiller n’en a pas besoin pour « sécuriser » ton compte."},{"type":"text","content":"La double authentification par SMS aide parfois, mais le SMS reste un facteur fragile. Un échange de carte SIM peut détourner les messages vers une autre puce si l’opérateur est trompé. C’est une raison de plus pour ne jamais considérer un code reçu par SMS comme une preuve d’identité à transmettre. Sur messagerie instantanée, le scénario « c’est moi, j’ai changé de numéro » sert souvent à réclamer de l’argent ou un code. Un mot de passe de famille ou une question connue seulement des proches peut casser cette manipulation."},{"type":"schema","content":"Réaction sûre sur téléphone\n1. Lire sans cliquer\n2. Chercher le service dans l’application officielle\n3. Raccrocher si un secret est demandé\n4. Vérifier par un autre canal\n5. Bloquer, signaler, conserver une preuve si besoin"},{"type":"text","content":"Démonstration guidée : prends un SMS suspect et réponds mentalement à trois questions avant toute action. Quel est le vrai domaine du lien ? Quelle émotion le message cherche-t-il à provoquer ? Quel canal officiel peux-tu utiliser à la place ? Si le message parle d’un colis, ouvre toi-même l’application ou le site officiel du transporteur. Si l’appel parle d’argent, raccroche puis rappelle le numéro officiel affiché sur ton contrat ou sur l’application connue."},{"type":"code","content":"Message reçu : « colis en attente, règle 1500 F maintenant »\n\nRéponse sûre :\n1. Je ne touche pas au lien.\n2. J’ouvre moi-même l’application ou le site officiel.\n3. Je vérifie si un colis existe vraiment.\n4. Si rien n’apparaît, je supprime et je signale.\n5. Si j’ai cliqué, je change mon mot de passe depuis le vrai site.","language":"text"},{"type":"text","content":"Si tu penses t’être fait piéger, agis vite : change le mot de passe du compte concerné depuis l’application ou le site légitime, active une méthode d’authentification plus robuste quand elle existe, contacte ton opérateur si tu crains un échange de SIM, surveille tes relevés, bloque le numéro et signale l’arnaque. Selon ton pays, tu peux aussi déposer plainte. Garde des captures datées, car elles peuvent servir pour le signalement."},{"type":"example","content":"Exemple corrigé : Mamadou reçoit « colis en attente » avec un lien vers « livraison-suivi.example.net ». Le domaine n’est pas celui du service officiel, l’urgence pousse à payer vite et le message demande une petite somme pour sembler crédible. Le bon réflexe est d’ouvrir lui-même l’application officielle de livraison ou le site saisi à la main, pas le lien reçu. Si un appel suit en demandant un code de validation, il doit raccrocher immédiatement."},{"type":"callout","content":"Erreurs fréquentes : croire qu’un petit montant n’est pas grave, alors que le premier paiement sert souvent à tester la victime ; rappeler le numéro dicté par l’appelant au lieu d’un numéro officiel ; donner un code de validation pour « annuler » une opération ; installer une application depuis un fichier reçu par message alors qu’elle devrait venir d’une boutique officielle."},{"type":"callout","content":"Sécurité : ne simule jamais un faux conseiller, un faux agent de paiement mobile ou un proche en détresse sur des personnes réelles. Même « pour tester » un ami, tu risques de provoquer un vrai préjudice financier ou émotionnel."},{"type":"callout","content":"À retenir : sur téléphone, l’urgence et la confiance sont exploitées en permanence. Un code de validation ou un code PIN ne se communique jamais. La règle la plus sûre reste de quitter le message, de rappeler un numéro officiel et de vérifier dans l’application légitime."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 1 : disséquer un courriel d’hameçonnage », puis applique les mêmes réflexes au SMS d’arnaque proposé : domaine du lien, émotion recherchée et bonne réaction. Termine par le quiz de la leçon."},{"type":"resource","content":"Cybermalveillance.gouv.fr : prévention et assistance aux victimes","url":"https://www.cybermalveillance.gouv.fr/"},{"type":"resource","content":"EFF : guide d’autodéfense contre la surveillance","url":"https://ssd.eff.org/fr"},{"type":"resource","content":"CISA : Secure Our World, les gestes de base (en anglais)","url":"https://www.cisa.gov/secure-our-world"}]}'::jsonb, 20, 25, 3),
  ('f4606174-e97e-7f03-2777-9ab40196495f', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', '465bec1c-2dfb-9ae1-24ff-c2889f98b52b', 'Mots de passe : comment on les attaque, comment les choisir', 'Comprendre les attaques contre les mots de passe, le rôle des empreintes salées, et pourquoi la longueur, l’unicité et les phrases de passe protègent mieux que des règles de complexité mal comprises.', '{"blocks":[{"type":"callout","content":"Objectifs : décrire les principales attaques contre les mots de passe, expliquer simplement le stockage par empreinte et sel, calculer une entropie et un nombre de combinaisons, distinguer un mot de passe faible d’une phrase de passe solide et choisir une stratégie défendable au quotidien."},{"type":"callout","content":"Prérequis : connaître les bases des menaces informatiques et savoir qu’un site ne devrait jamais stocker ton mot de passe en clair."},{"type":"callout","content":"Mise en situation : Rokia gère plusieurs comptes pour l’association Teranga. Elle hésite entre un mot de passe très compliqué mais réutilisé partout, et une phrase de passe plus longue, unique pour chaque service. Après avoir entendu parler d’une fuite, elle veut comprendre comment les mots de passe sont réellement attaqués avant de choisir une méthode."},{"type":"callout","content":"Vidéo à venir : Mots de passe : longueur, réutilisation et calculs simples"},{"type":"text","content":"On attaque les mots de passe de plusieurs façons. Il y a la devinette simple, le dictionnaire de mots courants, la force brute qui essaie toutes les combinaisons, le bourrage d’identifiants qui reteste ailleurs des couples déjà volés, l’hameçonnage qui les fait saisir sur un faux site, et l’enregistreur de frappe qui les vole au clavier. La défense change selon l’attaque : une bonne phrase de passe aide contre la force brute, mais elle ne sert plus à rien si tu la réutilises partout et qu’un autre service fuit."},{"type":"schema","content":"Attaque                     Ce qui aide à se défendre\nDictionnaire                Longueur, mots inattendus, blocage\nForce brute                 Phrase de passe longue, limite d’essais\nBourrage d’identifiants     Un mot de passe unique par service\nHameçonnage                 Vérifier le site, utiliser un gestionnaire\nEnregistreur de frappe      Poste sain, mises à jour, MFA"},{"type":"text","content":"Un service sérieux ne stocke pas ton mot de passe en clair. Il stocke une empreinte, aussi appelée hachage, plus un sel aléatoire. Le sel évite que deux personnes ayant le même mot de passe aient la même empreinte, et il gêne les tables pré-calculées. Des algorithmes lents comme bcrypt ou Argon2 sont utilisés pour rendre chaque essai coûteux. Cela protège mieux une base volée, mais ne corrige ni un mot de passe trop faible ni sa réutilisation."},{"type":"schema","content":"Entropie approximative\nbits = longueur × log2(taille de l’alphabet)\n\n62 caractères possibles : a-z A-Z 0-9\n8 caractères  : 8 × log2(62) ≈ 47,6 bits\n12 caractères : 12 × log2(62) ≈ 71,5 bits\n\nDiceware, 7776 mots :\n5 mots ≈ 64,6 bits\n6 mots ≈ 77,5 bits"},{"type":"text","content":"La longueur compte plus que la complexité superficielle. Un mot de passe comme « azerty » ou « password » est très faible. Ajouter une majuscule et un chiffre à un mot courant ne suffit pas toujours, car les attaquants testent ces variantes. Une phrase de passe de plusieurs mots tirés au hasard est souvent meilleure, plus mémorisable et plus robuste. Le principe important est l’unicité : un mot de passe solide réutilisé devient faible dès qu’un autre service est compromis."},{"type":"text","content":"Démonstration guidée : calcule l’empreinte SHA-256 d’une chaîne de test pour voir qu’un petit changement suffit à produire un résultat très différent. Sous Linux, la commande « sha256sum » est directe. Sous PowerShell, tu peux passer par .NET. Si tu n’as qu’un téléphone, contente-toi de comparer les sorties déjà fournies et n’utilise jamais un vrai secret. Le but n’est pas de retenir la commande par cœur, mais de voir qu’une empreinte ne permet pas de retrouver facilement l’entrée d’origine."},{"type":"code","content":"# Linux\nprintf \"motdepasse\" | sha256sum\n\n# PowerShell\n[System.BitConverter]::ToString(\n  [System.Security.Cryptography.SHA256]::Create().ComputeHash(\n    [System.Text.Encoding]::UTF8.GetBytes(\"motdepasse\")\n  )\n).Replace(\"-\", \"\").ToLower()\n\n# Node.js\nnode -e \"console.log(require(''crypto'').createHash(''sha256'').update(''motdepasse'').digest(''hex''))\"","language":"text"},{"type":"text","content":"Exemple numérique défensif : si un attaquant peut tester hypothétiquement 10 milliards de tentatives par seconde hors protections modernes, l’espace de 62 puissance 8 combinaisons représente 218340105584896 possibilités, soit environ 6,1 heures à parcourir entièrement dans le pire cas. Pour 62 puissance 12, on monte à environ 3,23 × 10 puissance 21 possibilités, soit environ 10 223 ans au même rythme. Dans la réalité, les services en ligne bloquent et ralentissent les essais, donc l’attaque directe en ligne est souvent bien plus lente que ce calcul de laboratoire. Le message à retenir reste simple : quelques caractères de plus changent énormément l’ordre de grandeur."},{"type":"example","content":"Exemple corrigé : Rokia compare deux choix. « abc123 » est faible, car il est court et très courant. Une phrase de passe de cinq mots tirés au hasard offre environ 64,6 bits d’entropie, déjà plus qu’un mot de passe de 8 caractères choisi dans un alphabet de 62 signes, qui tourne autour de 47,6 bits. Si Rokia utilise une phrase de passe unique par service et vérifie qu’elle n’est pas compromise, elle réduit à la fois le risque de devinette et celui de bourrage d’identifiants."},{"type":"callout","content":"Erreurs fréquentes : réutiliser le même mot de passe partout ; croire qu’un mot courant modifié par un chiffre devient soudain robuste ; changer ses mots de passe sans raison mais en gardant toujours le même motif ; choisir un mot de passe fort puis le saisir sur un faux site d’hameçonnage."},{"type":"callout","content":"Sécurité : n’essaie jamais de casser des empreintes ou de tester des comptes qui ne t’appartiennent pas. Les calculs de cette leçon servent à comprendre les ordres de grandeur pour mieux se protéger, pas à attaquer des services réels."},{"type":"callout","content":"À retenir : la longueur et l’unicité protègent mieux qu’une complexité décorative. Les services sérieux stockent des empreintes salées, mais cela n’excuse jamais la réutilisation. Une phrase de passe aléatoire, longue et unique, reste l’un des meilleurs choix pour un débutant."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 2 : auditer des mots de passe et des comptes » pour repérer des mots de passe faibles, la réutilisation et les entropies, puis ajoute le défi « Auditer l’hygiène des mots de passe » pour t’entraîner encore. Termine par le quiz de la leçon."},{"type":"resource","content":"Cybermalveillance.gouv.fr : bien gérer ses mots de passe","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/mots-de-passe"},{"type":"resource","content":"CNIL : mots de passe, les recommandations pour maîtriser sa sécurité","url":"https://www.cnil.fr/fr/mots-de-passe-recommandations-pour-maitriser-sa-securite"},{"type":"resource","content":"OWASP : aide-mémoire sur le stockage des mots de passe (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Password_Storage_Cheat_Sheet.html"}]}'::jsonb, 24, 30, 1),
  ('ed5343e4-8bcd-4ee8-5372-299bd9b2798c', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', '465bec1c-2dfb-9ae1-24ff-c2889f98b52b', 'Gestionnaires de mots de passe, double authentification et clés d’accès', 'S’équiper correctement avec un gestionnaire de mots de passe, choisir le bon second facteur et comprendre pourquoi les passkeys résistent mieux à l’hameçonnage que le SMS.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer ce qu’apporte un gestionnaire de mots de passe, distinguer les facteurs d’authentification, comparer SMS, TOTP et clés d’accès, choisir les comptes à protéger en priorité et appliquer une procédure simple si le téléphone est perdu."},{"type":"callout","content":"Prérequis : avoir vu comment un mot de passe est attaqué et pourquoi il doit être long, unique et difficile à réutiliser après une fuite."},{"type":"callout","content":"Mise en situation : Amina a amélioré ses mots de passe, mais elle craint toujours l’hameçonnage et la perte de son téléphone. Elle voit passer plusieurs options : SMS, application de codes, notifications « approuver ? », gestionnaire de mots de passe et nouvelles clés d’accès. Elle veut une méthode simple pour décider quoi activer en premier."},{"type":"callout","content":"Vidéo à venir : MFA et passkeys : choisir la bonne protection pour ses comptes"},{"type":"text","content":"Un gestionnaire de mots de passe stocke tes secrets dans un coffre chiffré protégé par un mot de passe principal solide. Il peut générer des mots de passe uniques, les mémoriser et les remplir à ta place. Un avantage pratique compte aussi pour la sécurité : si le site n’est pas le bon, le gestionnaire refuse souvent de remplir. Des options gratuites comme Bitwarden ou KeePassXC rendent cette discipline réaliste même avec peu de moyens."},{"type":"schema","content":"Facteurs d’authentification\nCe que je sais   : mot de passe, code PIN\nCe que j’ai      : téléphone, clé de sécurité\nCe que je suis   : empreinte, visage\n\nDouble authentification = au moins deux facteurs différents"},{"type":"text","content":"Tous les seconds facteurs ne se valent pas. Le SMS reste le plus fragile : échange de carte SIM, interception ou simple persuasion téléphonique peuvent suffire. Une application TOTP, décrite par la RFC 6238, génère un code qui change en général toutes les 30 secondes à partir d’un secret partagé. HOTP, son ancêtre, avance lui avec un compteur et non avec l’heure. TOTP est mieux que le SMS, mais un faux site peut encore te demander le code en direct. Les notifications push sont confortables, mais elles exposent à la fatigue d’approbation si un attaquant bombarde de demandes."},{"type":"schema","content":"Comparer les méthodes\nSMS        : simple, mais fragile face au SIM swap et au social\nTOTP       : mieux, mais un faux site peut voler le code\nPush       : pratique, mais risque de fatigue d’approbation\nClé d’accès: liée au site, très résistante à l’hameçonnage"},{"type":"text","content":"Les clés de sécurité et les clés d’accès, aussi appelées passkeys, utilisent WebAuthn. Elles sont liées au site légitime : même si tu arrives sur un faux domaine, la clé ne valide pas. C’est leur grand avantage contre l’hameçonnage. Quand c’est disponible, protège d’abord les comptes qui ouvrent la porte aux autres : ta messagerie principale, les comptes de paiement, les réseaux sociaux, puis les comptes d’administration ou professionnels. Pense aussi aux codes de secours : imprime-les ou note-les hors de l’appareil."},{"type":"text","content":"Démonstration guidée : pour activer une application TOTP, cherche dans un compte l’écran « sécurité » ou « double authentification ». Choisis l’option d’application d’authentification, scanne le QR code avec l’application, saisis le code affiché et enregistre immédiatement les codes de secours. Si tu changes de téléphone, transfère les comptes ou réactive la méthode un service après l’autre avant d’effacer l’ancien appareil."},{"type":"code","content":"Étapes génériques\n1. Ouvrir Paramètres > Sécurité du compte\n2. Choisir « application d’authentification »\n3. Scanner le QR code avec l’application TOTP\n4. Saisir le code à 6 chiffres affiché\n5. Télécharger ou noter les codes de secours\n6. Tester une reconnexion avant de fermer l’écran","language":"text"},{"type":"text","content":"Si tu perds ton téléphone, ne panique pas : utilise d’abord les codes de secours, une seconde clé d’accès ou un appareil déjà connecté si le service le permet. Change ensuite ton mot de passe principal si la situation est floue, révoque les sessions actives, retire l’ancien téléphone des appareils de confiance et contacte l’opérateur si tu crains un échange de SIM. Là encore, la préparation fait gagner du temps."},{"type":"example","content":"Exemple corrigé : face à trois attaques différentes, les méthodes n’offrent pas la même résistance. Contre un échange de carte SIM, le SMS est faible alors que TOTP et une clé d’accès restent meilleurs. Contre un faux site de connexion, le TOTP peut encore être recopié par la victime, alors qu’une clé d’accès liée au site bloque l’attaque. Contre la fatigue d’approbation, les notifications push sont les plus exposées si l’utilisateur finit par accepter sans vérifier."},{"type":"callout","content":"Erreurs fréquentes : activer la MFA sans sauvegarder les codes de secours ; protéger en priorité un réseau social secondaire mais pas sa messagerie principale ; approuver une notification push « pour voir » ; croire qu’un gestionnaire de mots de passe remplace à lui seul la double authentification."},{"type":"callout","content":"Sécurité : n’enrôle jamais ton second facteur sur un appareil prêté ou non maîtrisé. Conserve tes codes de secours hors du téléphone principal, et n’envoie jamais ces codes dans une messagerie non chiffrée ou à une autre personne."},{"type":"callout","content":"À retenir : un bon gestionnaire rend les mots de passe uniques réalistes au quotidien. La double authentification améliore beaucoup la sécurité, mais le SMS reste le plus faible des choix courants. Quand elles sont disponibles, les clés d’accès apportent la meilleure résistance à l’hameçonnage."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 2 : auditer des mots de passe et des comptes » pour repérer les comptes les plus sensibles et les faiblesses d’authentification, puis termine par le quiz de la leçon."},{"type":"resource","content":"ANSSI : recommandations relatives à l’authentification multifacteur et aux mots de passe","url":"https://messervices.cyber.gouv.fr/guides/recommandations-relatives-lauthentification-multifacteur-et-aux-mots-de-passe"},{"type":"resource","content":"RFC 6238 : mots de passe à usage unique basés sur le temps (TOTP) (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc6238"},{"type":"resource","content":"WebAuthn.guide : comprendre les clés d’accès et WebAuthn (en anglais)","url":"https://webauthn.guide/"}]}'::jsonb, 24, 30, 2),
  ('47ca7fff-1a12-0650-8cf2-a3c7724381ed', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', '465bec1c-2dfb-9ae1-24ff-c2889f98b52b', 'Fuites de données : vérifier, réagir, se protéger', 'Comprendre comment une fuite survient, ce que les attaquants réutilisent ensuite, puis appliquer un plan de réaction priorisé pour limiter les dégâts sur ses comptes personnels ou professionnels.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer comment une fuite de données arrive, identifier ce qui peut être réutilisé après la fuite, vérifier une adresse ou un mot de passe compromis sans l’exposer inutilement, prioriser les actions de réaction et éviter les erreurs les plus coûteuses."},{"type":"callout","content":"Prérequis : avoir vu les bases des mots de passe et de la double authentification, afin de comprendre pourquoi la réutilisation aggrave l’impact d’une fuite."},{"type":"callout","content":"Mise en situation : Seydou reçoit une alerte disant que son adresse figure dans une fuite. Il ne sait pas si le message est fiable, ni s’il doit d’abord changer un mot de passe, prévenir sa banque ou ignorer l’avertissement. Comme il a utilisé le même mot de passe sur plusieurs services il y a quelques années, il doit agir dans le bon ordre."},{"type":"callout","content":"Vidéo à venir : Fuites de données : que faire dans la première heure"},{"type":"text","content":"Une fuite de données peut venir d’un serveur piraté, d’une erreur de configuration, d’un appareil perdu, d’un partage mal maîtrisé ou d’une personne interne malveillante ou négligente. Ce qui fuit n’est pas toujours la même chose : adresses de messagerie, numéros de téléphone, mots de passe hachés, dates de naissance, documents, relevés, réponses à des questions de sécurité. Même une fuite ancienne peut être réutilisée longtemps après, car les attaquants croisent les données et les revendent."},{"type":"schema","content":"Après une fuite, les données servent à\n1. Tester la réutilisation sur d’autres sites\n2. Lancer un hameçonnage ciblé plus crédible\n3. Répondre à des questions de récupération\n4. Faire du chantage ou de l’usurpation\n5. Alimenter d’autres bases revendues"},{"type":"text","content":"Pour vérifier une adresse, tu peux utiliser un service connu comme Have I Been Pwned. Pour un mot de passe, le principe utile est différent : on ne l’envoie pas en clair. Le service s’appuie sur une idée de k-anonymat. Seuls les 5 premiers caractères de l’empreinte SHA-1 sont envoyés, puis la comparaison complète se fait localement. Par exemple, l’empreinte SHA-1 de « password » commence par « 5BAA6 ». Ce préfixe seul ne suffit pas à reconstruire le secret complet."},{"type":"text","content":"Démonstration guidée : avec une chaîne de test, calcule une empreinte SHA-1 et regarde seulement ses 5 premiers caractères. Tu verras ainsi l’idée du k-anonymat sans utiliser ton vrai mot de passe. Si tu n’as qu’un téléphone, compare simplement le préfixe obtenu avec l’exemple ci-dessous. Si tu consultes un service de vérification, fais-le depuis le site officiel et avec un mot de passe de démonstration, jamais un secret réel que tu utilises encore."},{"type":"code","content":"node -e \"console.log(require(''crypto'').createHash(''sha1'').update(''password'').digest(''hex'').toUpperCase())\"\n# Résultat attendu : 5BAA61E4C9B93F3F0682250B6CF8331B7EE68FD8\n# Préfixe envoyé dans le modèle k-anonymat : 5BAA6","language":"text"},{"type":"text","content":"La réaction doit être priorisée. D’abord, identifie le service concerné et change immédiatement le mot de passe de ce service, puis de tous les autres comptes où il a été réutilisé. Active ensuite la double authentification, surveille les comptes financiers, méfie-toi des courriels très ciblés qui peuvent suivre la fuite, et mets à jour les réponses ou adresses de récupération si nécessaire. Si des données financières sont concernées, contacte rapidement la banque ou le service de paiement."},{"type":"schema","content":"Plan d’action priorisé\n1. Vérifier que l’alerte est légitime\n2. Changer le mot de passe du service touché\n3. Changer partout où il a été réutilisé\n4. Activer la double authentification\n5. Surveiller comptes, relevés et messages suspects"},{"type":"text","content":"Une organisation a, elle aussi, des responsabilités : comprendre l’incident, protéger les personnes concernées, informer selon le cadre applicable et améliorer ses contrôles. Tu verras ce volet plus en détail dans le module sur les données personnelles et la conformité. Côté utilisateur, l’erreur la plus dangereuse reste d’ignorer l’alerte ou de ne changer qu’un seul mot de passe alors qu’il a été réutilisé ailleurs."},{"type":"example","content":"Exemple corrigé : Seydou reçoit une alerte fiable pour un ancien service. Il commence par changer le mot de passe de ce service, puis il dresse la liste des autres sites où il a réutilisé le même secret. Il change d’abord sa messagerie principale et ses comptes de paiement, active la double authentification, puis surveille ses relevés et les messages de récupération inhabituels. Il n’attend pas de voir un vol effectif pour agir."},{"type":"callout","content":"Erreurs fréquentes : ignorer l’alerte parce que la fuite semble ancienne ; changer uniquement le mot de passe du service cité sans traiter la réutilisation ; entrer son vrai mot de passe sur un site de vérification non officiel ; payer un maître chanteur au lieu de signaler, sécuriser et demander de l’aide adaptée."},{"type":"callout","content":"Sécurité : si tu analyses une fuite dans un cadre professionnel, ne collecte pas plus de données que nécessaire et respecte la confidentialité. La vérification d’un mot de passe compromis doit se faire avec des méthodes prévues pour cela, jamais en partageant le secret réel avec d’autres personnes."},{"type":"callout","content":"À retenir : une fuite devient grave surtout quand les mêmes secrets sont réutilisés ailleurs. Vérifie prudemment, puis agis par priorité : service touché, réutilisation, double authentification, surveillance. Plus la réaction est rapide et structurée, plus l’impact baisse."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 2 : auditer des mots de passe et des comptes » pour repérer la réutilisation et juger quelles actions lancer en premier après une fuite, puis termine par le quiz de la leçon."},{"type":"resource","content":"Have I Been Pwned : vérifier si une adresse figure dans une fuite (en anglais)","url":"https://haveibeenpwned.com/"},{"type":"resource","content":"Have I Been Pwned : vérifier un mot de passe sans le révéler (en anglais)","url":"https://haveibeenpwned.com/Passwords"},{"type":"resource","content":"CNIL : les violations de données personnelles, les règles à suivre","url":"https://www.cnil.fr/fr/violations-de-donnees-personnelles-les-regles-suivre"}]}'::jsonb, 20, 25, 3),
  ('8c59c582-1eb6-2ff0-0ab4-51844ad05b8d', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', '1c08c887-9d58-d609-e1b6-4cb0e3b85b54', 'Mises à jour, antivirus et surface d’attaque', 'Comprends pourquoi les correctifs, l’antivirus, le pare-feu local et le compte standard réduisent la fenêtre d’exposition d’un appareil du quotidien.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer pourquoi une mise à jour corrige une vulnérabilité, distinguer système, application, navigateur, micrologiciel et routeur, vérifier l’état d’un poste, calculer un retard moyen de correctif, et proposer des actions simples pour réduire la surface d’attaque."},{"type":"callout","content":"Prérequis : aucun. Savoir ouvrir les réglages d’un téléphone ou d’un ordinateur suffit."},{"type":"callout","content":"Mise en situation : Kwame aide la coopérative Harmattan, qui utilise cinq ordinateurs et plusieurs téléphones. Un poste sert encore pour la comptabilité alors que son navigateur n’a pas été mis à jour depuis longtemps. Un autre a deux antivirus installés en même temps. Kwame doit expliquer ce qui protège vraiment l’équipe, sans jargon inutile."},{"type":"callout","content":"Vidéo à venir : Mettre à jour sans paniquer : les bons réflexes sur ordinateur et téléphone"},{"type":"text","content":"Une mise à jour de sécurité corrige une vulnérabilité, c’est-à-dire une faiblesse exploitable dans un logiciel ou un appareil. Tant que le correctif n’est pas appliqué, la fenêtre d’exposition reste ouverte. Cela concerne le système, les applications, le navigateur, le téléphone et le micrologiciel d’un routeur ou d’une box. Un système en fin de support reste plus risqué : il fonctionne encore, mais ne reçoit plus les correctifs nécessaires."},{"type":"schema","content":"Élément à suivre         Exemple\nSystème                 Windows, Android, Ubuntu\nApplications            lecteur PDF, suite bureautique\nNavigateur              Firefox, Edge, Chrome\nMicrologiciel           box, routeur, imprimante\nÉtat critique           pris en charge ou fin de support"},{"type":"text","content":"Les mises à jour automatiques sont utiles, surtout pour les correctifs critiques, parce qu’elles raccourcissent le temps entre la publication d’une faille et sa correction. Lors de la propagation de WannaCry en 2017, le correctif existait déjà depuis environ deux mois. Il faut aussi télécharger depuis la source officielle : les logiciels piratés ou récupérés sur des sites douteux augmentent la surface d’attaque, c’est-à-dire le nombre de portes par lesquelles un attaquant peut entrer."},{"type":"schema","content":"Réduire la surface d’attaque\n1. désinstaller ce qui ne sert plus\n2. désactiver extensions et services inutiles\n3. garder un seul antivirus à la fois\n4. utiliser le pare-feu local\n5. travailler avec un compte standard"},{"type":"text","content":"Un antivirus aide, mais il n’est pas magique. Il repère des menaces connues par signature et certains comportements suspects. Deux antivirus actifs en même temps se gênent souvent. Sous Windows, Microsoft Defender offre déjà une base utile quand il est à jour. Le pare-feu local complète cette défense, et un compte standard limite les dégâts : un logiciel sans droits d’administration peut modifier moins de choses."},{"type":"text","content":"Démonstration guidée : sur Windows, tu peux vérifier d’un coup l’état de l’antivirus intégré. Sur Debian ou Ubuntu, tu peux lister les paquets à mettre à jour. L’idée n’est pas de devenir administrateur système en une minute, mais d’apprendre à regarder des indices concrets plutôt qu’à supposer que « tout va bien » parce que l’écran s’allume."},{"type":"code","content":"Get-MpComputerStatus | Select-Object AMServiceEnabled,AntivirusEnabled,AntivirusSignatureLastUpdated\n\n# Exemple de sortie\n# AMServiceEnabled              : True\n# AntivirusEnabled              : True\n# AntivirusSignatureLastUpdated : <date et heure récentes>\n\n# Debian ou Ubuntu\napt list --upgradable","language":"powershell"},{"type":"example","content":"Exemple corrigé : les cinq postes de Sahel Services ont 3, 7, 12, 20 et 28 jours de retard sur leurs mises à jour critiques. Le retard moyen vaut 14 jours, car (3 + 7 + 12 + 20 + 28) ÷ 5 = 14. Le poste à 28 jours n’est pas seulement « un peu en retard » : il tire la moyenne vers le haut et doit devenir prioritaire, avec celui à 20 jours."},{"type":"callout","content":"Erreurs fréquentes : laisser un système sans support « tant qu’il démarre encore » ; installer les logiciels depuis des sources non officielles ; croire qu’un antivirus remplace les correctifs ; travailler tous les jours avec un compte administrateur alors qu’un compte standard suffit dans la plupart des cas."},{"type":"callout","content":"Sécurité : n’installe jamais un correctif ou un antivirus téléchargé depuis un site non officiel. Sur un parc d’entreprise ou d’association, applique les procédures internes et vérifie les sauvegardes avant un changement important."},{"type":"callout","content":"À retenir : les correctifs réduisent la fenêtre d’exposition, mais seulement s’ils sont appliqués. Un antivirus à jour, un pare-feu actif, peu de logiciels inutiles et un compte standard changent beaucoup. Un appareil en fin de support doit être remplacé ou isolé."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 3 : auditer l’hygiène d’un parc de postes », calcule les retards de mises à jour, vérifie l’état de l’antivirus et repère les postes qui augmentent la surface d’attaque. Termine par le quiz de la leçon."},{"type":"resource","content":"Cybermalveillance.gouv.fr : faire les mises à jour de sécurité","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/mises-a-jour"},{"type":"resource","content":"Cybermalveillance.gouv.fr : utiliser un antivirus","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/antivirus"}]}'::jsonb, 22, 30, 1),
  ('c3c8ea55-49de-9d15-7ce3-cf2ca90b370b', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', '1c08c887-9d58-d609-e1b6-4cb0e3b85b54', 'Sauvegardes : la règle 3-2-1 et le test de restauration', 'Apprends à distinguer sauvegarde, synchronisation et archivage, puis à planifier une stratégie 3-2-1 qui résiste aussi aux rançongiciels.', '{"blocks":[{"type":"callout","content":"Objectifs : distinguer sauvegarde, synchronisation et archivage, expliquer la règle 3-2-1, comparer complète, incrémentale et différentielle, calculer un besoin d’espace, et vérifier qu’une restauration est réellement possible."},{"type":"callout","content":"Prérequis : avoir suivi « Mises à jour, antivirus et surface d’attaque » ou déjà connaître le risque de perte, de panne et de rançongiciel."},{"type":"callout","content":"Mise en situation : Awa gère les documents de la coopérative Harmattan. Ses fichiers sont aussi synchronisés sur un téléphone et un ordinateur portable. Un lundi matin, un logiciel malveillant chiffre le dossier partagé. Awa découvre alors qu’une synchronisation n’est pas une vraie sauvegarde : le fichier chiffré a été recopié partout."},{"type":"callout","content":"Vidéo à venir : Sauvegarder sans se mentir : copies, restauration et règle 3-2-1"},{"type":"text","content":"Une sauvegarde sert à retrouver des données perdues, supprimées ou modifiées. Une synchronisation recopie l’état actuel entre plusieurs appareils. Un archivage conserve des informations sur une longue durée. Ces trois notions se ressemblent, mais ne répondent pas au même besoin. Si un rançongiciel chiffre un dossier synchronisé, toutes les copies connectées peuvent propager le problème. Une vraie sauvegarde doit donc être séparée dans le temps, et au moins parfois séparée du réseau."},{"type":"schema","content":"But principal          Exemple\nSauvegarde             récupérer après panne, erreur, attaque\nSynchronisation        retrouver les mêmes fichiers partout\nArchivage              conserver longtemps, même peu consulté"},{"type":"text","content":"La règle 3-2-1 est un bon repère : 3 copies de tes données, sur 2 supports différents, dont 1 copie hors site. Pour les rançongiciels, une copie hors ligne ou immuable est encore meilleure : hors ligne signifie déconnectée, immuable signifie difficile à modifier avant la date prévue. Les sauvegardes sensibles doivent aussi être chiffrées, car une fuite de sauvegarde reste une fuite de données."},{"type":"schema","content":"Types de sauvegarde\nComplète       tout recopier\nIncrémentale   recopier ce qui a changé depuis la dernière sauvegarde\nDifférentielle recopier ce qui a changé depuis la dernière complète"},{"type":"text","content":"Le choix du type agit sur l’espace et sur le temps de restauration. Une complète est simple à restaurer, mais elle consomme plus d’espace. Une incrémentale est économe, mais elle exige souvent la complète initiale et toute la chaîne des changements. Une différentielle grossit au fil des jours, mais reste plus simple à restaurer qu’une longue chaîne d’incrémentales. Deux questions guident le choix : combien de données peux-tu perdre, ce qu’on appelle souvent le point de reprise, et combien de temps peux-tu rester à l’arrêt, c’est-à-dire la durée de reprise acceptable."},{"type":"text","content":"Démonstration guidée : avant une vraie copie, lance un test à blanc. Sous Linux ou macOS, « rsync -av --dry-run » montre ce qui serait copié sans rien modifier. Sous Windows, « robocopy » sert souvent au même type d’automatisation. Le point important est de vérifier ce qui va partir et ce qui va arriver avant d’utiliser des options destructrices."},{"type":"code","content":"# Linux ou macOS : test à blanc\nrsync -av --dry-run Documents/ sauvegarde/Documents/\n\n# Windows : exemple simple\nrobocopy Documents D:\\Sauvegardes\\Documents /MIR /L\n\n# /L affiche ce qui serait copié sans écrire\n# Évite d’ajouter une suppression sans avoir testé d’abord.","language":"bash"},{"type":"example","content":"Exemple corrigé : Awa stocke 80 Gio de données. Chaque semaine, elle fait une complète de 80 Gio. Chaque jour ouvré, elle produit environ 4 Gio de nouveaux fichiers ou de changements. Sur 4 semaines, avec 4 complètes et 20 incrémentales, il faut 400 Gio, car 4 × 80 + 20 × 4 = 320 + 80 = 400 Gio. Si sa dernière restauration de 1 250 Mo prend 25 minutes à 50 Mo par minute, sa durée de reprise est d’au moins 25 minutes pour ce lot précis."},{"type":"callout","content":"Erreurs fréquentes : confondre dossier synchronisé et sauvegarde ; conserver toutes les copies branchées en permanence, donc exposées au même rançongiciel ; ne jamais tester de restauration ; oublier de sauvegarder aussi les configurations, les codes de secours et les clés nécessaires au redémarrage."},{"type":"callout","content":"Sécurité : ne restaure jamais par-dessus les données encore présentes sans avoir vérifié la source et la date de la sauvegarde. Dans une structure, documente qui peut lancer une restauration et garde les clés de chiffrement hors de l’appareil sauvegardé."},{"type":"callout","content":"À retenir : une stratégie utile protège contre la panne, l’erreur humaine et l’attaque. La règle 3-2-1 donne une base solide, mais elle ne vaut que si tu testes la restauration. Une sauvegarde que tu n’as jamais restaurée est une promesse, pas une preuve."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 3 : auditer l’hygiène d’un parc de postes », vérifie si la règle 3-2-1 est respectée dans les journaux fournis et juge si les sauvegardes semblent réellement restaurables. Termine par le quiz de la leçon."},{"type":"resource","content":"Cybermalveillance.gouv.fr : effectuer des sauvegardes régulières","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/sauvegardes"},{"type":"resource","content":"CNIL : sécurité, sauvegarder","url":"https://www.cnil.fr/fr/securite-sauvegarder"}]}'::jsonb, 22, 30, 2),
  ('6691e9b7-e6bc-c9d8-72bc-46077a073445', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', '1c08c887-9d58-d609-e1b6-4cb0e3b85b54', 'Chiffrer ses appareils et se protéger sur le Wi-Fi', 'Protège tes appareils volés ou perdus grâce au chiffrement complet, puis adopte les bons réflexes sur le Wi-Fi domestique et public.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer à quoi sert le chiffrement complet du disque, choisir un verrouillage d’écran solide, sécuriser un Wi-Fi domestique, évaluer un Wi-Fi public, et décider quand un VPN aide vraiment ou non."},{"type":"callout","content":"Prérequis : avoir vu les bases des mises à jour et des sauvegardes, ou utiliser déjà un téléphone et un Wi-Fi au quotidien."},{"type":"callout","content":"Mise en situation : Fatou rentre d’un atelier avec son ordinateur portable et son téléphone. Dans le taxi, elle remarque trop tard que le sac a disparu. Le soir même, elle doit répondre à deux questions : un inconnu peut-il lire ses fichiers si l’appareil est éteint, et que vaut le Wi-Fi public utilisé la veille dans un café ?"},{"type":"callout","content":"Vidéo à venir : Téléphone perdu, Wi-Fi public : les protections qui comptent vraiment"},{"type":"text","content":"Le chiffrement complet du disque protège les données stockées quand un appareil est perdu ou volé. Sans la clé liée à ton mot de passe ou à ton code, le contenu reste illisible. Sur Windows, BitLocker remplit ce rôle. Sur macOS, on parle de FileVault. Sur Linux, LUKS est fréquent. Sur iPhone et sur beaucoup de téléphones Android récents, le stockage est chiffré quand un verrouillage d’écran est activé. Si l’appareil est déjà déverrouillé, le chiffrement aide beaucoup moins."},{"type":"schema","content":"Vol ou perte              Ce qui aide\nAppareil éteint           chiffrement complet + code solide\nAppareil déverrouillé     verrouillage rapide + effacement distant\nCompte lié à l’appareil   localisation + changement du mot de passe\nClé de récupération       copie hors de l’appareil"},{"type":"text","content":"Le code de déverrouillage doit être solide et différent des chiffres évidents comme 123456. La clé de récupération doit être conservée hors de l’appareil, par exemple imprimée ou notée dans un coffre numérique. Active aussi la fonction de localisation et d’effacement à distance quand elle existe. Perdre un téléphone peut exposer tes messages, tes photos, tes codes de secours et parfois tes accès professionnels."},{"type":"text","content":"Le Wi-Fi domestique mérite aussi de l’attention. Change le mot de passe d’administration de la box, active WPA2 ou WPA3, et coupe WPS si tu n’en as pas besoin. Sur un Wi-Fi public, le risque principal vient des faux points d’accès et des autres personnes sur le même réseau. HTTPS protège surtout le trajet vers le site visité, mais il ne masque pas tout le contexte et ne corrige pas un mauvais domaine. Un VPN peut chiffrer le trajet jusqu’au service VPN, mais il ne transforme pas un service malveillant en service honnête. Si tu veux aller plus loin sur le durcissement du Wi-Fi, le parcours Réseaux traite aussi ce sujet."},{"type":"schema","content":"À la maison              Dans un lieu public\nWPA2 ou WPA3             préférer HTTPS partout\nmot de passe box changé  éviter les opérations sensibles si possible\nWPS désactivé            se méfier des faux points d’accès\nappareils à jour         ne pas faire confiance au réseau seul"},{"type":"text","content":"Démonstration guidée : sur Windows, « netsh wlan show interfaces » affiche le nom du réseau, la bande et le type d’authentification. Si tu es administrateur, « manage-bde -status C: » indique l’état de BitLocker. Sur téléphone, ouvre les réglages de sécurité pour vérifier qu’un code protège bien l’appareil."},{"type":"code","content":"netsh wlan show interfaces\n\n# Exemple de sortie utile\n# SSID            : MonWiFiMaison\n# Authentification: WPA2 - Personnel\n# Chiffrement     : CCMP\n\nmanage-bde -status C:\n# Si BitLocker est actif, l’état du volume et la protection s’affichent.","language":"powershell"},{"type":"example","content":"Exemple corrigé : 1) ordinateur personnel à la maison sur WPA3 et système à jour : situation sûre ; 2) téléphone sans code sur le Wi-Fi d’un café : très risqué ; 3) portable chiffré, mais connecté à un faux point d’accès « WiFi Gratuit » pour saisir un mot de passe professionnel : le chiffrement du disque n’empêche pas l’hameçonnage ; 4) tablette en recharge sur une borne publique avec un câble inconnu : prudence. La réponse dépend du stockage, du réseau et du contexte."},{"type":"callout","content":"Erreurs fréquentes : croire qu’un cadenas dans le navigateur suffit à rendre un Wi-Fi public sûr ; stocker la clé de récupération sur l’appareil lui-même ; laisser le mot de passe d’administration de la box tel qu’à l’achat ; penser qu’un VPN gratuit protège automatiquement mieux qu’un service sérieux bien configuré."},{"type":"callout","content":"Sécurité : n’emprunte pas un compte ni une connexion d’administration qui ne t’appartiennent pas pour « vérifier vite ». Sur un appareil professionnel, applique la politique de l’organisation et signale immédiatement toute perte ou tout vol."},{"type":"callout","content":"À retenir : le chiffrement complet protège surtout un appareil éteint ou verrouillé. Un bon code, une clé de récupération séparée et l’effacement distant sont indispensables. Sur le Wi-Fi, protège la maison par une configuration correcte et traite les réseaux publics comme peu fiables."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 3 : auditer l’hygiène d’un parc de postes », repère quels postes sont chiffrés et lesquels restent exposés en cas de vol. Termine par le quiz de la leçon."},{"type":"resource","content":"Microsoft : BitLocker, chiffrement des disques","url":"https://learn.microsoft.com/fr-fr/windows/security/operating-system-security/data-protection/bitlocker/"},{"type":"resource","content":"ANSSI : recommandations de sécurité relatives aux réseaux Wi-Fi","url":"https://messervices.cyber.gouv.fr/guides/recommandations-de-securite-relatives-aux-reseaux-wi-fi"}]}'::jsonb, 22, 30, 3),
  ('fbcfdd5c-013d-e26b-a05b-c31f58ae5049', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'ecda4f3a-81bc-0e79-a332-df988e534741', 'Chiffrer, encoder, hacher : ne plus confondre', 'Distingue enfin trois opérations souvent mélangées, puis reconnais quand une donnée a été encodée, chiffrée ou condensée en empreinte.', '{"blocks":[{"type":"callout","content":"Objectifs : différencier encodage, chiffrement et hachage, définir texte en clair, texte chiffré et clé, appliquer le principe de Kerckhoffs, reconnaître une empreinte courante, et utiliser une petite démonstration Base64 et SHA-256."},{"type":"callout","content":"Prérequis : aucun. Il suffit de savoir qu’un message peut être transformé avant d’être transmis ou stocké."},{"type":"callout","content":"Mise en situation : Amina reçoit trois informations différentes : une chaîne « Qm9uam91cg== », un fichier accompagné d’une longue empreinte hexadécimale, et un message présenté comme « chiffré » alors qu’il suffit de décaler les lettres. Elle comprend vite que tout ce qui change l’apparence d’un texte n’a pas le même but. Pour se protéger, elle doit savoir quel outil répond à quel problème."},{"type":"callout","content":"Vidéo à venir : Encodage, chiffrement, hachage : trois outils, trois usages"},{"type":"text","content":"Encoder, chiffrer et hacher servent à des objectifs différents. L’encodage transforme des données pour les rendre compatibles avec un format ou un canal. Base64 et l’hexadécimal sont réversibles sans secret : ce n’est pas du chiffrement. Chiffrer vise la confidentialité : on part d’un texte en clair, on applique un algorithme et une clé, et on obtient un texte chiffré. Hacher produit une empreinte à sens unique, utile pour l’intégrité et le stockage prudent des mots de passe."},{"type":"schema","content":"Besoin                    Outil\ntransporter ou afficher    encodage\ncacher le contenu          chiffrement\nvérifier l’intégrité       hachage"},{"type":"text","content":"Le principe de Kerckhoffs dit qu’un système doit rester sûr même si tout le monde connaît l’algorithme, sauf la clé. Cacher l’algorithme ne suffit donc pas. Le chiffre de César et ROT13 sont utiles pour apprendre, mais ils sont faibles. À l’inverse, un chiffrement moderne comme AES est conçu pour résister à ces approches quand la clé est bien choisie et protégée."},{"type":"schema","content":"Vocabulaire utile\nTexte en clair   message lisible avant chiffrement\nTexte chiffré    message protégé par une clé\nClé              secret ou paramètre qui permet de chiffrer ou déchiffrer\nEmpreinte        résultat fixe d’une fonction de hachage"},{"type":"text","content":"Une bonne fonction de hachage est déterministe, rapide à calculer, produit un effet d’avalanche et doit rendre les collisions difficiles à trouver. L’effet d’avalanche signifie qu’un petit changement dans l’entrée transforme fortement la sortie. Pour la sécurité moderne, MD5 et SHA-1 sont à éviter. SHA-256 reste courant. Quand on protège des mots de passe, on ajoute aussi un sel, c’est-à-dire une valeur aléatoire différente pour chaque mot de passe, afin d’éviter que deux utilisateurs ayant le même secret aient la même empreinte stockée."},{"type":"text","content":"Démonstration guidée : avec Node.js, « Bonjour » encodé en Base64 donne « Qm9uam91cg== ». Ensuite, calcule une empreinte SHA-256 pour « Bonjour » puis pour « BonjouR ». Une seule lettre change, mais les deux empreintes n’ont presque rien en commun visuellement : c’est l’effet d’avalanche. Cette démonstration aide à reconnaître les transformations."},{"type":"code","content":"node -e \"console.log(Buffer.from(''Bonjour'').toString(''base64''))\"\n# Qm9uam91cg==\n\nnode -e \"const crypto=require(''node:crypto''); console.log(crypto.createHash(''sha256'').update(''Bonjour'').digest(''hex''))\"\n# 9172e8eec99f144f72eca9a568759580edadb2cfd154857f07e657569493bc44\n\nnode -e \"const crypto=require(''node:crypto''); console.log(crypto.createHash(''sha256'').update(''BonjouR'').digest(''hex''))\"\n# 68507c350137bf38f0f1bcc1bf8bf08c79d296ff5b194246c01a6b8fb701718d","language":"bash"},{"type":"example","content":"Exemple corrigé : une chaîne hexadécimale de 32 caractères évoque MD5, 40 caractères évoquent SHA-1, et 64 caractères évoquent SHA-256. Si tu vois « Qm9uam91cg== », tu reconnais plutôt du Base64 que du chiffrement. Pour vérifier un fichier téléchargé, compare l’empreinte publiée avec celle que tu calcules localement : si elles diffèrent, le fichier a changé."},{"type":"callout","content":"Erreurs fréquentes : dire « c’est chiffré » dès qu’un texte semble illisible ; croire que Base64 protège un secret ; utiliser encore MD5 ou SHA-1 pour un besoin de sécurité moderne ; oublier le sel quand on parle de stockage prudent des mots de passe."},{"type":"callout","content":"Sécurité : n’utilise ces notions que pour protéger, vérifier ou comprendre. Les exemples de César et de ROT13 sont pédagogiques et ne doivent pas servir à attaquer un système réel ou à contourner une protection."},{"type":"callout","content":"À retenir : encodage, chiffrement et hachage répondent à trois questions différentes. Base64 transporte, AES protège la confidentialité, SHA-256 aide à vérifier l’intégrité. Un algorithme connu n’est pas un problème si la clé reste secrète et si le système a été bien conçu."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 4 : intégrité, chiffrement et certificats », vérifie des empreintes SHA-256, décode du Base64 et compare les résultats avec le défi « Casser un chiffrement de César ». Termine par le quiz de la leçon."},{"type":"resource","content":"RFC 4648 : encodages Base16, Base32 et Base64 (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc4648"},{"type":"resource","content":"Wikipédia : SHA-2","url":"https://fr.wikipedia.org/wiki/SHA-2"}]}'::jsonb, 22, 30, 1),
  ('598013ad-c87c-7b37-81e2-7aee0e3947b9', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'ecda4f3a-81bc-0e79-a332-df988e534741', 'Clés secrètes, clés publiques et signatures numériques', 'Découvre la différence entre chiffrement symétrique et asymétrique, puis comprends comment une signature numérique prouve l’origine et l’intégrité d’un document.', '{"blocks":[{"type":"callout","content":"Objectifs : distinguer chiffrement symétrique et asymétrique, expliquer le problème du partage de clé, décrire le principe d’une signature numérique, protéger une clé privée, et lire une démonstration OpenSSL sans te perdre dans les mathématiques."},{"type":"callout","content":"Prérequis : avoir suivi « Chiffrer, encoder, hacher : ne plus confondre » ou déjà savoir ce qu’est une clé et une empreinte."},{"type":"callout","content":"Mise en situation : Désiré doit envoyer un contrat à Atlas sans qu’on puisse le modifier discrètement. Il entend parler de clés secrètes, de clés publiques, de signatures et de TLS, mais tout semble mélangé. Son besoin est pourtant simple : savoir qui peut lire, qui peut prouver l’origine, et quelle clé ne doit jamais quitter sa poche numérique."},{"type":"callout","content":"Vidéo à venir : Clés publiques, clés privées et signatures sans formules compliquées"},{"type":"text","content":"Le chiffrement symétrique utilise une seule clé pour chiffrer et déchiffrer. Il est rapide, ce qui le rend utile pour protéger un grand volume de données. Son problème principal est le partage de la clé. Le chiffrement asymétrique répond à ce point avec une paire de clés : une clé publique que l’on peut diffuser, et une clé privée qui doit rester secrète. Ce mécanisme est plus coûteux en calcul, mais très pratique pour établir la confiance initiale."},{"type":"schema","content":"Type                    Avantage principal         Limite principale\nSymétrique              rapide                      partage de la clé\nAsymétrique             pas besoin de secret initial plus lent\nHybride                 combine les deux            demande une bonne mise en œuvre"},{"type":"text","content":"En pratique, beaucoup de protocoles modernes utilisent un modèle hybride. On emploie l’asymétrique pour établir ou protéger une clé de session, puis on bascule sur du symétrique pour échanger les données courantes. C’est l’idée générale de TLS. Les clés SSH reposent aussi sur cette logique pour éviter d’envoyer un mot de passe à chaque connexion."},{"type":"text","content":"Signer numériquement n’est pas la même chose que chiffrer. Pour signer, on calcule d’abord l’empreinte du document, puis on la signe avec la clé privée. La vérification se fait avec la clé publique. Si la vérification réussit, on obtient trois garanties utiles : le document n’a pas été modifié depuis la signature, il provient de la personne ou du service possédant la clé privée, et cette personne aura du mal à nier l’opération si la clé a été bien protégée. La clé privée ne se partage jamais. Pour RSA, une taille de 2048 bits ou plus reste un minimum courant ; les courbes elliptiques offrent une autre famille de clés plus compactes."},{"type":"schema","content":"Signature numérique\nDocument -> empreinte -> signature avec clé privée\n\nVérification\nDocument reçu -> empreinte recalculée\nsignature + clé publique -> résultat : valide ou non"},{"type":"text","content":"Démonstration guidée : si OpenSSL est installé, les commandes suivantes génèrent une clé RSA de 2048 bits, extraient la clé publique, signent un fichier puis vérifient la signature. Si la dernière ligne répond « Verified OK », la signature correspond bien au fichier et à la paire de clés utilisée."},{"type":"code","content":"openssl genpkey -algorithm RSA -out cle.pem -pkeyopt rsa_keygen_bits:2048\nopenssl pkey -in cle.pem -pubout -out cle.pub\nopenssl dgst -sha256 -sign cle.pem -out message.sig message.txt\nopenssl dgst -sha256 -verify cle.pub -signature message.sig message.txt\n# Verified OK","language":"bash"},{"type":"example","content":"Exemple corrigé : Désiré envoie un contrat PDF à Atlas. S’il veut seulement cacher le contenu, il peut chiffrer. S’il veut prouver que le PDF vient bien de lui et qu’il n’a pas changé, il doit le signer avec sa clé privée. Atlas vérifie ensuite la signature avec la clé publique de Désiré. Si Atlas modifie une seule ligne du contrat, même un accent, la vérification échoue."},{"type":"callout","content":"Erreurs fréquentes : confondre signature et chiffrement ; partager la clé privée « pour dépanner vite » ; publier une clé privée dans un dépôt de code ; oublier de sauvegarder la clé privée et ses informations de récupération dans un endroit maîtrisé."},{"type":"callout","content":"Sécurité : ne signe ni ne chiffre jamais au nom d’une autre personne sans autorisation explicite. Une clé privée engage la confiance et parfois la responsabilité de son détenteur. Protège-la comme tu protégerais un cachet officiel ou une signature manuscrite importante."},{"type":"callout","content":"À retenir : le symétrique est rapide, l’asymétrique simplifie le partage de confiance, et le modèle hybride combine les deux. La signature numérique ne cache pas le contenu : elle prouve l’intégrité et l’origine. La clé privée doit rester secrète du début à la fin."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 4 : intégrité, chiffrement et certificats », repère où l’on vérifie une empreinte et où l’on s’appuie sur une clé publique, puis relie ces gestes à la logique des signatures numériques. Termine par le quiz de la leçon."},{"type":"resource","content":"Wikipédia : infrastructure à clés publiques","url":"https://fr.wikipedia.org/wiki/Infrastructure_%C3%A0_cl%C3%A9s_publiques"},{"type":"resource","content":"RFC 5280 : certificats X.509 et listes de révocation (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc5280"}]}'::jsonb, 24, 30, 2),
  ('6a204001-ea83-6f98-7582-68540ef889f4', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'ecda4f3a-81bc-0e79-a332-df988e534741', 'HTTPS, certificats et confiance sur le web', 'Comprends ce que garantit vraiment HTTPS, comment lire un certificat simple et pourquoi un cadenas n’est pas une preuve de légitimité d’un site.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer ce que garantit HTTPS, résumer le rôle de TLS, lire les champs essentiels d’un certificat, décrire une chaîne de confiance, et réagir correctement à un avertissement du navigateur."},{"type":"callout","content":"Prérequis : avoir suivi « Clés secrètes, clés publiques et signatures numériques » ou déjà comprendre le principe d’une paire de clés."},{"type":"callout","content":"Mise en situation : Rokia doit vérifier un portail de paiement ouvert dans son navigateur. Le cadenas est visible, mais l’adresse lui semble étrange. Elle doit décider si elle peut faire confiance au site, quoi regarder dans le certificat et quoi faire si le navigateur affiche une erreur de nom ou d’expiration."},{"type":"callout","content":"Vidéo à venir : HTTPS et certificats : pourquoi le cadenas ne suffit pas"},{"type":"text","content":"HTTPS ajoute TLS à HTTP. Son but est triple : protéger la confidentialité du trafic entre le navigateur et le serveur, préserver son intégrité, et fournir une identité de serveur que le navigateur peut vérifier. En grandes lignes, le client envoie un « hello », le serveur présente son certificat, les deux parties établissent des clés de session, puis le reste de l’échange se fait avec un chiffrement symétrique rapide. Cette négociation ne rend pas un site honnête par magie : elle sécurise surtout le canal."},{"type":"schema","content":"HTTPS garantit\n1. confidentialité du trajet\n2. intégrité du trajet\n3. identité du serveur si le certificat est valide\n\nHTTPS ne garantit pas\n1. que le site est bienveillant\n2. que son contenu est vrai\n3. que l’utilisateur ne se trompe pas d’adresse"},{"type":"text","content":"Un certificat contient notamment le sujet, l’émetteur, une période de validité, des noms alternatifs de sujet, appelés SAN, la clé publique du serveur et la signature de l’autorité qui l’a validé. Les navigateurs vérifient ensuite une chaîne de confiance : certificat du serveur, parfois un certificat intermédiaire, puis une autorité racine déjà approuvée. Des autorités de certification délivrent des certificats gratuits et de courte durée, comme Let’s Encrypt. Cela rend le renouvellement automatique très important."},{"type":"schema","content":"Chaîne de confiance\n[Autorité racine]\n        |\n[Autorité intermédiaire]\n        |\n[Certificat du serveur example.com]\n\nVérifications : nom, date, signature, chaîne"},{"type":"text","content":"Quand un navigateur avertit qu’un certificat est expiré, que le nom présenté ne correspond pas au site visité, ou que l’autorité est inconnue, il faut s’arrêter et vérifier. Le bon réflexe n’est pas de cliquer vite sur « continuer quand même », surtout sur un site sensible. HSTS demande au navigateur de revenir toujours en HTTPS pour un site qui l’a déjà annoncé. Le cadenas ne prouve pas la légitimité du domaine : un site d’hameçonnage peut aussi obtenir un certificat valide."},{"type":"text","content":"Démonstration guidée : tu peux afficher le certificat d’un site depuis le navigateur, puis lire sa période de validité et ses noms couverts. En ligne de commande (Linux, macOS ou Git Bash sous Windows), la commande suivante demande le certificat présenté par « example.com » puis n’en affiche que l’essentiel. Les options « -connect » et « -servername » sont celles attendues par OpenSSL pour viser le bon service et le bon nom. Les valeurs montrées ici sont fictives et servent seulement à apprendre quoi lire."},{"type":"code","content":"echo | openssl s_client -connect example.com:443 -servername example.com 2>/dev/null | openssl x509 -noout -subject -issuer -dates -ext subjectAltName\n\n# Exemple de sortie (valeurs fictives)\n# subject=CN=example.com\n# issuer=C=US, O=Example CA, CN=Example Intermediate CA\n# notBefore=Jan 10 00:00:00 2027 GMT\n# notAfter=Feb 15 00:00:00 2027 GMT\n# X509v3 Subject Alternative Name:\n#     DNS:example.com, DNS:www.example.com","language":"bash"},{"type":"example","content":"Exemple corrigé : si un certificat est valable du 10 janvier 2027 au 15 février 2027, il reste 36 jours au 10 janvier 2027 avant l’expiration. Ce nombre ne dit rien sur la qualité du site lui-même, seulement sur l’état temporel du certificat. Si Rokia visite « examp1e.com » avec un certificat valide pour ce faux domaine, le cadenas n’efface pas le risque d’hameçonnage : c’est l’adresse complète qu’il faut contrôler."},{"type":"callout","content":"Erreurs fréquentes : penser qu’un cadenas prouve la bonne foi d’un site ; ignorer les erreurs de nom ou de date ; croire qu’un certificat gratuit protège moins bien par principe ; oublier de renouveler un certificat court alors qu’un service dépend de lui."},{"type":"callout","content":"Sécurité : si un avertissement de certificat apparaît sur un site bancaire, administratif ou professionnel, ne passe pas outre sans vérification indépendante. Utilise l’adresse officielle saisie à la main ou un contact de confiance avant toute action."},{"type":"callout","content":"À retenir : HTTPS protège le canal, pas la moralité du site. Un certificat doit être valide, au bon nom et relié à une chaîne de confiance reconnue. Le cadenas est un indice technique utile, mais jamais un remplaçant de la vigilance sur l’adresse et le contexte."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 4 : intégrité, chiffrement et certificats », lis un certificat, vérifie une empreinte et relie chaque observation aux garanties réelles d’HTTPS. Termine par le quiz de la leçon."},{"type":"resource","content":"Let’s Encrypt : comment ça marche","url":"https://letsencrypt.org/fr/how-it-works/"},{"type":"resource","content":"RFC 5280 : certificats X.509 et listes de révocation (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc5280"}]}'::jsonb, 22, 30, 3),
  ('96b02bb7-463c-85b4-fcb9-14feebc83d24', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'c671b9d4-c599-d9f7-05ac-73248624d87d', 'Évaluer un risque : actifs, menaces, vulnérabilités', 'Apprends à inventorier ce qui compte, à distinguer menace et vulnérabilité, puis à prioriser des risques avec une matrice simple et un registre exploitable.', '{"blocks":[{"type":"callout","content":"Objectifs : identifier les actifs d’une petite structure, distinguer menace, vulnérabilité et risque, noter vraisemblance et impact sur une échelle claire, choisir un traitement adapté, et prioriser un registre de risques sans confondre urgence et gravité."},{"type":"callout","content":"Prérequis : avoir suivi « Les principes de la sécurité : confidentialité, intégrité, disponibilité, moindre privilège » ou déjà savoir ce qu’est un actif et une propriété C, I ou D."},{"type":"callout","content":"Mise en situation : Kwame aide la coopérative Harmattan à mieux protéger son activité. Les responsables parlent de tout à la fois : mots de passe, panne électrique, perte d’ordinateur, erreur de virement, fuite de données. Sans méthode, chacun défend son inquiétude du moment. Kwame doit transformer cette discussion en registre de risques pour savoir quoi traiter d’abord."},{"type":"callout","content":"Vidéo à venir : Construire une matrice de risques simple et utile"},{"type":"text","content":"Un actif est ce que tu veux protéger : un compte de messagerie, un ordinateur, une base de clients, une caisse mobile, mais aussi du temps de travail, la réputation ou la confiance d’un partenaire. Sa valeur ne se résume pas à son prix : demande-toi aussi ce qu’une perte de confidentialité, d’intégrité ou de disponibilité ferait à l’activité. Une menace est ce qui pourrait causer un dommage : rançongiciel, vol, erreur humaine, incendie, fraude, panne. Une vulnérabilité est la faiblesse qui rend la menace plausible : absence de sauvegarde, mot de passe réutilisé, poste non chiffré, procédure inexistante. Le risque combine donc trois idées : quelque chose de précieux, un danger, et une faiblesse exploitable."},{"type":"schema","content":"Actif + menace + vulnérabilité = risque\n\nActif : messagerie\nMenace : prise de contrôle du compte\nVulnérabilité : pas de double authentification\nImpact possible : lecture de courriels, fraude, perte de confiance"},{"type":"text","content":"Pour noter un risque, on utilise souvent une formule simple : risque = vraisemblance × impact. La vraisemblance estime la probabilité raisonnable du scénario dans ton contexte. L’impact mesure les dégâts si le scénario se réalise. Sur une échelle de 1 à 4, tu peux définir 1 comme faible, 2 comme notable, 3 comme fort, 4 comme majeur. Avec cette grille, un score de 1 à 3 reste faible, de 4 à 7 moyen, de 8 à 11 élevé, et de 12 à 16 critique. L’important n’est pas de jouer au mathématicien : il faut surtout écrire des critères compréhensibles pour que deux personnes notent à peu près de la même façon."},{"type":"schema","content":"Matrice 4 x 4\n\nImpact →        1     2      3       4\nVrais. 1        1     2      3       4\nVrais. 2        2     4      6       8\nVrais. 3        3     6      9      12\nVrais. 4        4     8     12      16"},{"type":"text","content":"Un registre de risques tient généralement en quelques colonnes : actif, scénario, menace, vulnérabilité, vraisemblance, impact, score, traitement, responsable, échéance, risque résiduel. Le traitement peut suivre quatre verbes. Réduire : ajouter une sauvegarde, activer la double authentification, former l’équipe. Éviter : abandonner un usage trop dangereux. Transférer : souscrire une assurance ou confier une fonction à un prestataire encadré. Accepter : garder le risque parce qu’il coûte plus cher à corriger que ce qu’il menace réellement. Même après une mesure, il reste souvent un risque résiduel : on le documente au lieu de faire semblant qu’il a disparu."},{"type":"text","content":"Démonstration guidée : ouvre un tableau sur ton téléphone, dans un tableur ou même sur papier. Liste d’abord cinq actifs réels, puis pour chacun une menace crédible et une faiblesse observable. Ensuite seulement, note vraisemblance et impact. Cette séquence évite l’erreur classique qui consiste à écrire directement « risque élevé » sans dire de quoi on parle."},{"type":"code","content":"Actif | Scénario | Menace | Vulnérabilité | V | I | Score | Traitement\nMessagerie | Compte repris | Hameçonnage | pas de MFA | 4 | 4 | 16 | Réduire\nPortable | Données lues après vol | Vol | disque non chiffré | 3 | 4 | 12 | Réduire\nSauvegarde | Activité arrêtée | Rançongiciel | une seule copie locale | 3 | 3 | 9 | Réduire\nComptes | Ancien accès encore valide | Menace interne | compte partagé | 2 | 4 | 8 | Éviter\nWi-Fi invité | Réseau interne exposé | Accès non autorisé | mauvaise séparation | 2 | 3 | 6 | Réduire","language":"text"},{"type":"example","content":"Exemple corrigé : chez la coopérative Harmattan, cinq risques sont notés. « Messagerie sans MFA » vaut 4 × 4 = 16, donc critique. « Portable non chiffré » vaut 3 × 4 = 12, critique aussi. « Sauvegarde unique sur le même poste » vaut 3 × 3 = 9, élevé. « Compte partagé après départ » vaut 2 × 4 = 8, élevé. « Wi-Fi invité mal séparé » vaut 2 × 3 = 6, moyen. L’ordre de traitement commence donc par la messagerie et le chiffrement du portable, avant d’optimiser le Wi-Fi invité."},{"type":"callout","content":"Erreurs fréquentes : confondre menace et vulnérabilité, par exemple écrire « mot de passe faible » comme menace alors que c’est une faiblesse ; utiliser une échelle sans critères écrits, ce qui rend les notes arbitraires ; oublier de réévaluer après une mesure, alors que le contexte change ; vouloir protéger à n’importe quel prix un actif dont la valeur est modeste."},{"type":"callout","content":"Sécurité : une analyse de risques sert à protéger, pas à désigner un coupable. Si tu travailles pour une structure, fais valider le périmètre et manipule le registre comme un document sensible : il décrit précisément les faiblesses à corriger."},{"type":"callout","content":"À retenir : un risque n’est ni une peur vague ni une simple panne : c’est un scénario qui relie un actif, une menace et une vulnérabilité. Une matrice simple suffit si ses critères sont clairs. Le vrai but est de prioriser l’action, pas de produire un beau tableau."},{"type":"callout","content":"Pour pratiquer : ouvre le laboratoire « TP 5 : construire un registre de risques », classe les incidents par propriété C, I ou D, puis note les scénarios avant de choisir un traitement. Termine par le quiz de la leçon."},{"type":"resource","content":"ANSSI : la méthode EBIOS Risk Manager","url":"https://cyber.gouv.fr/securisation/analyse-des-risques/methode-ebios-rm/"},{"type":"resource","content":"NIST : cadre de cybersécurité (CSF) (en anglais)","url":"https://www.nist.gov/cyberframework"},{"type":"resource","content":"NIST : ressources de cybersécurité pour les petites entreprises (en anglais)","url":"https://www.nist.gov/itl/smallbusinesscyber"}]}'::jsonb, 24, 30, 1),
  ('446b74b7-abca-595e-a061-3df539d89b4e', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'c671b9d4-c599-d9f7-05ac-73248624d87d', 'Protéger les données personnelles : principes, droits et obligations', 'Découvre ce qu’est une donnée personnelle, quels principes guident son traitement, quels droits ont les personnes et comment réagir quand une violation présente un risque.', '{"blocks":[{"type":"callout","content":"Objectifs : reconnaître une donnée personnelle, distinguer responsable de traitement et sous-traitant, citer les principes essentiels de protection, expliquer les droits des personnes, et réagir à une violation de données avec prudence juridique."},{"type":"callout","content":"Prérequis : avoir suivi « Évaluer un risque : actifs, menaces, vulnérabilités » ou déjà savoir inventorier des actifs et qualifier un impact."},{"type":"callout","content":"Mise en situation : Amina aide l’association Teranga à gérer des inscriptions à une formation. Le formulaire demande un nom, un téléphone, une adresse, l’âge, le quartier et parfois des informations de santé pour l’accessibilité. L’équipe veut aussi exporter le fichier vers un outil de publipostage gratuit. Amina doit décider quelles données sont vraiment nécessaires, qui y accède, combien de temps elles restent conservées et quoi faire si le fichier est envoyé au mauvais destinataire."},{"type":"callout","content":"Vidéo à venir : Données personnelles : les bons réflexes sans jargon juridique inutile"},{"type":"text","content":"Une donnée personnelle est toute information qui identifie directement ou indirectement une personne. Un nom ou une photo identifie directement. Un numéro de téléphone, une adresse, un identifiant de compte, une plaque, une combinaison de date de naissance et de quartier peuvent identifier indirectement. Certaines catégories exigent une prudence renforcée, notamment les données de santé, biométriques, les opinions religieuses ou l’appartenance syndicale. Les données relatives aux condamnations et infractions suivent elles aussi un cadre particulier. Le réflexe utile n’est pas de réciter une liste : demande-toi toujours si l’information permet de reconnaître quelqu’un, seule ou croisée avec d’autres."},{"type":"schema","content":"Exemples rapides\n\nDonnée personnelle : nom, téléphone, adresse, photo\nSouvent sensible : santé, biométrie, croyances\nPas forcément personnelle seule : numéro interne sans contexte\nDevient personnelle si on peut relier le numéro à une personne"},{"type":"text","content":"La protection des données repose sur des principes simples à retenir. Il faut une finalité claire : pourquoi collecter ? Il faut la licéité : sur quelle base agir, par exemple contrat, obligation légale, consentement, intérêt légitime. Il faut la minimisation : ne demander que ce qui est nécessaire. Il faut l’exactitude, une durée de conservation limitée, la transparence, et des mesures de sécurité adaptées. Le responsable de traitement décide pourquoi et comment les données sont utilisées. Le sous-traitant traite les données pour son compte, selon un cadre défini. Dans une petite structure, ces rôles peuvent tenir dans peu de personnes, mais ils doivent être compris. Le RGPD peut parfois s’appliquer même si l’organisation n’est pas établie dans l’Union européenne, par exemple si elle vise des personnes qui s’y trouvent."},{"type":"schema","content":"Questions avant toute collecte\n1. Pourquoi cette donnée ?\n2. Qui y accède ?\n3. Combien de temps la garder ?\n4. Où est-elle stockée ?\n5. Comment la protéger ?\n6. Comment la supprimer ou la corriger ?"},{"type":"text","content":"Les personnes disposent de droits : accéder à leurs données, demander une rectification, un effacement, une opposition, une limitation ou une portabilité selon les cas. Cela implique des procédures concrètes. Si quelqu’un écrit pour corriger son numéro ou demander ce que tu détiens, il faut savoir retrouver l’information, répondre clairement et documenter le traitement. Un registre des traitements aide justement à ne pas improviser. Un DPO, ou délégué à la protection des données, peut être désigné dans certains contextes ou simplement servir de point de contact quand la structure en a besoin."},{"type":"text","content":"Une violation de données personnelles correspond à un incident qui détruit, perd, altère, divulgue ou rend accessibles des données sans autorisation. Si cette violation présente un risque pour les personnes, une notification à l’autorité compétente peut être requise dans les 72 heures après en avoir pris connaissance. Si le risque est élevé, les personnes concernées doivent aussi être informées avec honnêteté. Tu n’as pas à mémoriser la loi de chaque pays. Retiens plutôt ceci : le RGPD est une référence utile, la Convention de Malabo pose un cadre africain, beaucoup de pays ont leur propre autorité, et il faut vérifier celle qui s’applique à ton contexte."},{"type":"text","content":"Démonstration guidée : prends un formulaire réel ou imaginaire et relis chaque champ comme si tu devais le défendre devant une personne concernée. Si tu ne peux pas expliquer en une phrase son utilité, enlève-le ou rends-le optionnel. Ensuite, note dans un mini-registre la finalité, la base légale, la durée de conservation et les mesures de sécurité. Tu peux faire cet exercice depuis un téléphone dans une note simple."},{"type":"code","content":"Traitement : inscriptions à une formation\nFinalité : gérer les candidatures et contacter les participants\nDonnées : nom, téléphone, adresse électronique\nÀ éviter si inutile : profession détaillée, copie d’identité, données de santé\nAccès : coordination et administration\nDurée : le temps nécessaire à la gestion puis archivage limité\nMesures : comptes nominatifs, MFA, export limité, suppression des doublons","language":"text"},{"type":"example","content":"Exemple corrigé : l’association Teranga collecte des fiches d’inscription pour une formation. La finalité est claire : organiser la session et prévenir les participants. Demander le nom, le téléphone et l’adresse électronique est cohérent ; demander l’état civil complet et une pièce d’identité ne l’est pas si rien ne le justifie. Les fiches sont conservées le temps de la session puis archivées de manière limitée pour le suivi administratif. Si Amina découvre un mercredi à 14 h 20 qu’un fichier a été envoyé à un mauvais destinataire et que le risque pour les personnes est réel, le délai de 72 heures mène au samedi à 14 h 20 pour la notification à l’autorité compétente."},{"type":"callout","content":"Erreurs fréquentes : croire qu’une petite structure n’a aucune obligation parce qu’elle est petite ; demander « au cas où » des données qu’on n’utilisera pas ; confondre consentement et seule base légale possible, alors qu’il existe d’autres fondements ; traiter une violation comme un problème d’image uniquement, sans évaluer le risque pour les personnes."},{"type":"callout","content":"Sécurité : appuie-toi sur des principes généraux utiles partout : collecter le minimum, expliquer l’usage, limiter les accès, protéger les exports et réagir vite en cas de fuite. Pour une décision juridique ou une notification réelle, vérifie toujours la loi et l’autorité compétente de ton pays ou de celui des personnes concernées."},{"type":"callout","content":"À retenir : une donnée personnelle n’est pas seulement un nom : c’est toute information qui permet d’identifier quelqu’un. Collecter moins, expliquer mieux et sécuriser davantage réduit à la fois le risque et la charge de conformité. En cas de violation, le temps compte, mais la qualité de l’évaluation compte aussi."},{"type":"callout","content":"Pour pratiquer : travaille d’abord dans « TP 5 : construire un registre de risques » pour repérer les actifs contenant des données personnelles, puis poursuis avec « Incident : un compte de messagerie compromis » pour raisonner sur le délai de notification et les mesures à prendre. Termine par le quiz de la leçon."},{"type":"resource","content":"CNIL : le RGPD, de quoi parle-t-on ?","url":"https://www.cnil.fr/fr/rgpd-de-quoi-parle-t-on"},{"type":"resource","content":"CNIL : les droits pour maîtriser ses données personnelles","url":"https://www.cnil.fr/fr/mes-demarches/les-droits-pour-maitriser-vos-donnees-personnelles"},{"type":"resource","content":"Union africaine : Convention de Malabo sur la cybersécurité et la protection des données personnelles (en anglais)","url":"https://au.int/en/treaties/african-union-convention-cyber-security-and-personal-data-protection"}]}'::jsonb, 24, 30, 2),
  ('a8d04f10-056b-7f35-7140-76d2ddb37768', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'c671b9d4-c599-d9f7-05ac-73248624d87d', 'Politiques de sécurité, sensibilisation et culture de la sécurité', 'Comprends comment une petite structure fixe des règles utiles, répartit les responsabilités et construit une culture de signalement sans transformer la sécurité en punition.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer le rôle d’une politique de sécurité, répartir les responsabilités essentielles, choisir des actions de sensibilisation adaptées à un petit budget, suivre quelques indicateurs simples, et rédiger des règles courtes que l’équipe peut vraiment appliquer."},{"type":"callout","content":"Prérequis : avoir suivi « Protéger les données personnelles : principes, droits et obligations » ou déjà connaître les enjeux de comptes, d’appareils et de signalement."},{"type":"callout","content":"Mise en situation : Mamadou coordonne une petite équipe chez Sahel Services. Tout le monde utilise la messagerie, parfois son propre téléphone, et certains travaillent à distance. Après plusieurs clics sur de faux messages, la direction demande « une politique de sécurité ». Mamadou veut éviter le document poussiéreux que personne ne lit. Il cherche des règles courtes, des responsabilités claires et une manière de faire remonter les incidents sans humilier les collègues."},{"type":"callout","content":"Vidéo à venir : Gouvernance sécurité : des règles simples qui changent vraiment les habitudes"},{"type":"text","content":"La gouvernance de la sécurité, ce n’est pas seulement un grand mot pour les grosses entreprises. C’est la manière d’organiser qui décide quoi, selon quelles règles, avec quels contrôles et quels retours d’expérience. Dans une petite structure, une politique de sécurité ou une charte informatique doit couvrir l’usage acceptable des outils, les mots de passe, la messagerie, les appareils personnels, le télétravail, les accès, le départ d’un collaborateur et le signalement des incidents. Si la règle n’est pas compréhensible en quelques secondes, elle sera contournée ou oubliée."},{"type":"schema","content":"Rôles minimaux\n\nDirection : fixe les priorités et valide les moyens\nRéférent sécurité : suit les actions et coordonne\nUtilisateurs : appliquent, signalent, demandent en cas de doute\nSupport ou prestataire : met en œuvre et documente"},{"type":"text","content":"Une bonne politique ne vit pas seule. Elle s’accompagne d’une sensibilisation continue : capsules courtes, affiches, rappels en réunion, mini-exercices, messages simples. Le but n’est pas de piéger l’équipe, mais d’installer des réflexes. Une culture sans blâme est décisive : si quelqu’un a peur d’avouer un clic ou une erreur, l’incident grossira en silence. En revanche, si l’équipe sait qu’un signalement rapide sera accueilli avec sérieux, elle aidera la défense au lieu de la retarder."},{"type":"schema","content":"Cycle simple\nRègle claire -> habitude -> signalement rapide -> retour d’expérience\n          ^                                         |\n          +--------------- amélioration continue ---+"},{"type":"text","content":"Les indicateurs servent à voir si les habitudes changent vraiment. Tu peux suivre le taux de clic lors d’un exercice annoncé et éthique, le nombre de signalements utiles, le délai moyen de mise à jour, ou le temps nécessaire pour désactiver le compte d’une personne qui quitte la structure. Il faut peu d’indicateurs, mais ils doivent mener à une décision. Mesurer pour mesurer ne sert à rien."},{"type":"text","content":"Démonstration guidée : rédige une charte en huit règles maximum. Chaque règle doit commencer par un verbe d’action et répondre à un risque visible. Par exemple : activer la double authentification, ne pas partager de compte, signaler tout message suspect, séparer usage personnel et usage professionnel autant que possible. Relis ensuite la charte avec une personne non technique : si elle ne comprend pas un point, réécris-le."},{"type":"code","content":"Charte courte de l’association Teranga\n1. Utilise un compte nominatif.\n2. Active la double authentification quand elle existe.\n3. Ne partage jamais ton mot de passe.\n4. Signale tout message ou lien suspect.\n5. Verrouille ton appareil quand tu t’éloignes.\n6. Stocke les documents sensibles aux emplacements prévus.\n7. Préviens le référent avant de quitter la structure.\n8. Demande de l’aide avant d’improviser un contournement.","language":"text"},{"type":"example","content":"Exemple corrigé : Sahel Services lance un exercice annoncé auprès de 48 personnes. Six personnes cliquent sur le faux message. Le taux de clic est donc de 6 ÷ 48 = 12,5 %. Ce chiffre n’est utile que s’il mène à une action : par exemple renforcer la vérification des expéditeurs et rappeler la procédure de signalement. Si, le mois suivant, le taux baisse et que les signalements augmentent, la sensibilisation produit un effet concret."},{"type":"callout","content":"Erreurs fréquentes : écrire une charte si longue qu’elle n’est jamais lue ; limiter la sécurité à la sanction, ce qui décourage le signalement ; oublier la gestion des arrivées, mutations et départs, alors que les comptes orphelins sont un risque classique ; suivre des indicateurs sans jamais les relier à une décision ou à un budget."},{"type":"callout","content":"Sécurité : les simulations d’hameçonnage doivent rester éthiques, proportionnées et connues du cadre interne. Le but est d’entraîner l’attention et le signalement, pas d’humilier des personnes ni de contourner leurs droits."},{"type":"callout","content":"À retenir : la gouvernance traduit la sécurité en règles applicables, responsabilités claires et suivi régulier. Une bonne culture de sécurité fait remonter les doutes vite et sans blâme. Même avec peu de budget, quelques priorités bien tenues changent fortement le niveau de protection."},{"type":"callout","content":"Pour pratiquer : prépare-toi pour « Projet final : auditer la sécurité du Centre Numérique Soleil » en relisant les règles, les rôles et les indicateurs que tu vérifierais dans une petite structure. Termine par le quiz de la leçon."},{"type":"resource","content":"ANSSI : guide d’hygiène informatique","url":"https://cyber.gouv.fr/publications/guide-dhygiene-informatique"},{"type":"resource","content":"CISA : Secure Our World, les gestes de base (en anglais)","url":"https://www.cisa.gov/secure-our-world"},{"type":"resource","content":"NIST : ressources de cybersécurité pour les petites entreprises (en anglais)","url":"https://www.nist.gov/itl/smallbusinesscyber"}]}'::jsonb, 20, 25, 3),
  ('149a681c-e466-bce3-5710-d81721a059cb', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', '637ef880-3754-45f8-323a-eb7a8f6f7361', 'Répondre à un incident : le cycle en six étapes', 'Suis une méthode simple pour distinguer événement, incident et crise, puis contenir, éradiquer et restaurer sans oublier la preuve, la communication et le retour d’expérience.', '{"blocks":[{"type":"callout","content":"Objectifs : distinguer événement, incident et crise, décrire les six étapes d’une réponse à incident, choisir des mesures de confinement adaptées, répartir les rôles essentiels, et conduire un retour d’expérience utile."},{"type":"callout","content":"Prérequis : avoir suivi « Politiques de sécurité, sensibilisation et culture de la sécurité » ou déjà connaître l’idée de rôles, d’escalade et de signalement."},{"type":"callout","content":"Mise en situation : Un lundi matin, Baobab Tech constate qu’un poste affiche une note de rançon et que des fichiers partagés deviennent illisibles. Le support veut éteindre toutes les machines. La direction veut prévenir immédiatement les clients. Une collègue pense qu’il suffit de restaurer les sauvegardes. Pour éviter la panique, Désiré doit conduire une réponse ordonnée et ne pas détruire les indices utiles."},{"type":"callout","content":"Vidéo à venir : Les six étapes d’une réponse à incident sans improvisation"},{"type":"text","content":"Tous les signaux ne sont pas des incidents. Un événement est un fait observé : une alerte antivirus, un échec de connexion, un service lent. Un incident de sécurité est un événement confirmé ou très plausible qui affecte la confidentialité, l’intégrité ou la disponibilité. Une crise apparaît quand l’impact dépasse le technique : activité bloquée, réputation menacée, décision de direction, obligations légales ou communication externe. Cette distinction évite deux excès : sous-réagir à un vrai problème, ou déclencher une cellule de crise pour une alerte isolée."},{"type":"schema","content":"Du signal à la décision\n\nÉvénement -> qualification -> incident\nIncident majeur + activité touchée + communication sensible -> crise"},{"type":"text","content":"Le cycle en six étapes est une façon simple de garder la tête froide. 1. Préparation : contacts, sauvegardes, journaux, exercices et fiche réflexe. 2. Identification : que se passe-t-il vraiment, sur quels actifs, avec quel impact ? 3. Confinement : empêcher la propagation. 4. Éradication : supprimer la cause technique, par exemple compte compromis, tâche malveillante ou point d’entrée. 5. Récupération : remettre en service et surveiller. 6. Retour d’expérience : comprendre ce qui a marché, ce qui a manqué, et quoi améliorer. Le NIST SP 800-61 révision 2, qui reste la référence citée ici, regroupe cette logique en quatre phases : préparation, détection et analyse, confinement-éradication-récupération, puis activité post-incident. Une révision 3 plus récente existe aussi, mais la logique pratique reste proche pour un débutant."},{"type":"schema","content":"Rôles pendant l’incident\nResponsable : arbitre et priorise\nTechnique : enquête, confine, restaure\nCommunication : prépare les messages internes et externes\nJuridique ou DPO : aide sur les obligations de notification"},{"type":"schema","content":"Cycle en 6 étapes\nPréparation -> Identification -> Confinement\n      ^                             |\n      |                             v\nRetour d’expérience <- Récupération <- Éradication"},{"type":"text","content":"Le confinement ne signifie pas « tout couper sans réfléchir ». Isoler une machine du réseau, désactiver un compte, révoquer des sessions ou changer un mot de passe peut être pertinent. En revanche, éteindre brutalement un poste peut détruire des preuves volatiles, par exemple des sessions actives ou certains processus en mémoire. Il faut donc arbitrer selon le type d’incident. La communication compte aussi : mieux vaut dire clairement ce que l’on sait, ce que l’on ne sait pas encore, et qui décide de la suite."},{"type":"text","content":"Démonstration guidée : construis une fiche réflexe avant l’incident. Écris qui appeler, dans quel ordre, quels comptes d’urgence utiliser, où se trouvent les sauvegardes et quel canal employer si la messagerie est compromise. Termine par un petit exercice sur table : chacun lit la fiche et explique ce qu’il ferait dans les dix premières minutes. Cette fiche doit pouvoir tenir sur une page et rester disponible même si le poste principal est inutilisable."},{"type":"code","content":"Fiche réflexe minimale\n1. Noter l’heure et le premier symptôme\n2. Prévenir le référent sécurité et la direction\n3. Isoler l’actif touché du réseau si la propagation est possible\n4. Conserver journaux, captures et messages observés\n5. Désactiver ou réinitialiser les comptes compromis\n6. Vérifier l’état des sauvegardes\n7. Préparer la communication interne et externe\n8. Planifier le retour d’expérience","language":"text"},{"type":"example","content":"Exemple corrigé : chez Baobab Tech, la préparation existe déjà avec une fiche réflexe et des sauvegardes testées. À l’identification, l’équipe confirme qu’un partage commun est chiffré. En confinement, le poste suspect est isolé et le compte concerné est suspendu. En éradication, l’accès initial compromis est supprimé et les mots de passe réinitialisés. En récupération, les fichiers sains sont restaurés puis surveillés. Enfin, le retour d’expérience montre que la double authentification manquait sur la messagerie et que le canal de secours entre direction et support était trop flou."},{"type":"callout","content":"Erreurs fréquentes : payer ou négocier avant d’avoir compris l’incident et évalué les options ; réinstaller trop vite sans conserver les journaux utiles ; confondre récupération et éradication, alors qu’un service remis en ligne peut rechuter ; ne rien noter pendant l’incident, ce qui ruine ensuite la chronologie et les leçons à tirer."},{"type":"callout","content":"Sécurité : tu n’interviens que sur des systèmes que tu es autorisé à traiter. Si des données personnelles sont impliquées, pense à l’évaluation du risque et au cadre de notification adapté sans improviser le droit d’un pays précis."},{"type":"callout","content":"À retenir : une bonne réponse à incident suit un ordre : comprendre, contenir, éliminer, remettre en service, apprendre. Le confinement protège le périmètre, mais il doit respecter la valeur des preuves. Une fiche réflexe claire fait gagner des minutes qui comptent."},{"type":"callout","content":"Pour pratiquer : travaille « Incident : un compte de messagerie compromis » en observant qui décide, qui confine et comment la chronologie mène aux bonnes mesures. Termine par le quiz de la leçon."},{"type":"resource","content":"NIST SP 800-61 : guide de gestion des incidents de sécurité (en anglais)","url":"https://csrc.nist.gov/pubs/sp/800/61/r2/final"},{"type":"resource","content":"Cybermalveillance.gouv.fr : fiche réflexe contre les rançongiciels","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/rancongiciels-ransomwares"},{"type":"resource","content":"CISA : arrêter les rançongiciels (en anglais)","url":"https://www.cisa.gov/stopransomware"}]}'::jsonb, 24, 30, 1),
  ('34038745-9c8e-0864-a30f-2f4080735d00', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', '637ef880-3754-45f8-323a-eb7a8f6f7361', 'Détecter, signaler et préserver les preuves', 'Repère les signaux utiles, qualifie une alerte, aligne des journaux dans le bon fuseau horaire et protège l’intégrité des preuves avant l’analyse détaillée.', '{"blocks":[{"type":"callout","content":"Objectifs : repérer des indicateurs de compromission, distinguer un vrai positif d’un faux positif plausible, signaler un incident avec les bonnes informations, reconstruire une chronologie en UTC, et préserver les preuves sans les altérer."},{"type":"callout","content":"Prérequis : avoir suivi « Répondre à un incident : le cycle en six étapes » ou déjà savoir pourquoi la chronologie et le confinement doivent être documentés."},{"type":"callout","content":"Mise en situation : Rokia reçoit trois signaux presque en même temps : un utilisateur dit que des courriels partent tout seuls, l’antivirus remonte une alerte mineure et le journal de la messagerie montre une connexion inhabituelle. Sur le groupe de discussion, chacun interprète les heures différemment car les outils n’utilisent pas le même fuseau. Rokia doit décider vite si c’est un vrai incident, puis conserver ce qui prouve la séquence des faits."},{"type":"callout","content":"Vidéo à venir : Chronologie, journaux et preuves : ne pas perdre l’essentiel"},{"type":"text","content":"La détection vient souvent de sources imparfaites. Un antivirus alerte, un utilisateur voit un comportement étrange, un journal de connexion signale un pays inattendu, ou des fichiers changent brutalement de nom. Un indicateur de compromission, ou IOC, peut être une adresse IP, un domaine, une empreinte de fichier, un nom de processus ou une règle de transfert de courriel. Aucun de ces éléments n’est magique pris seul. Il faut les recouper pour distinguer un vrai positif d’un faux positif, c’est-à-dire une alerte qui ressemble à une attaque sans en être une."},{"type":"schema","content":"Exemples de sources\n\nAlerte outil\nJournal de connexion\nSignalement utilisateur\nMessage de rançon\nFichiers renommés\nCourriels envoyés à l’insu du propriétaire"},{"type":"text","content":"Bien signaler un incident, c’est répondre à cinq questions : quoi, quand, où, comment, qui. Quoi : le symptôme précis. Quand : l’heure observée et le fuseau si nécessaire. Où : machine, compte, application, boîte mail, réseau concerné. Comment : pièce jointe, lien, session distante, support amovible, ou simple doute. Qui : personne qui observe et point de contact à prévenir. Une alerte vague comme « ça ne marche plus » ralentit tout le monde. Une alerte factuelle aide à qualifier sans dramatiser."},{"type":"schema","content":"Préserver la preuve\n1. Noter l’heure\n2. Capturer sans modifier si possible\n3. Copier avant d’analyser\n4. Calculer une empreinte si pertinent\n5. Garder la chaîne de conservation"},{"type":"text","content":"Le temps est un piège classique. Certains journaux parlent en UTC, d’autres en heure locale avec décalage. Pour aligner les événements, convertis tout dans un repère commun, souvent l’UTC, et vérifie que les horloges sont synchronisées, par exemple via NTP. Pense aussi à l’ordre de volatilité : la mémoire vive, les connexions actives et certains journaux temporaires peuvent disparaître plus vite qu’un fichier déjà écrit sur disque. Travailler sur des copies et vérifier leur intégrité avec une empreinte protège la valeur de la preuve. Cela compte pour l’analyse interne, et encore plus si un contentieux apparaît ensuite. Sur Windows, l’Observateur d’événements est une source courante ; sur Linux, on rencontre souvent « last » et « journalctl » ; une messagerie ou un service cloud possède aussi ses propres journaux."},{"type":"text","content":"Démonstration guidée : prends cinq lignes de journaux et convertis-les toutes en UTC avant de raconter l’histoire. Tu peux le faire dans un tableau, dans un fichier texte ou sur un téléphone. L’objectif n’est pas de devenir expert en forensique, mais d’éviter la chronologie fausse qui fait accuser la mauvaise action ou le mauvais compte."},{"type":"code","content":"09:05:00+01:00  Login success sur la messagerie\n10:25:00+02:00  Règle de transfert créée\n11:40:00+03:00  Transfert externe activé\n09:50:00Z       Compte désactivé\n09:55:00Z       Mot de passe réinitialisé\n\nConversion UTC\n09:05+01:00 -> 08:05Z\n10:25+02:00 -> 08:25Z\n11:40+03:00 -> 08:40Z","language":"text"},{"type":"example","content":"Exemple corrigé : une fois les heures alignées, la connexion réussie apparaît à 08:05Z, la règle de transfert à 08:25Z, l’activation du transfert externe à 08:40Z, puis le compte est désactivé à 09:50Z. La durée d’exposition entre le premier accès confirmé et la désactivation est donc de 1 h 45. Sans conversion en UTC, on pourrait croire à tort que la désactivation est arrivée avant certaines actions malveillantes."},{"type":"callout","content":"Erreurs fréquentes : mélanger des heures locales et UTC dans la même chronologie ; ouvrir directement un fichier suspect sur le poste de travail au lieu d’en faire une copie ; signaler un incident sans dire quel compte ou quel actif est concerné ; considérer une adresse IP ou un domaine comme preuve absolue sans contexte supplémentaire."},{"type":"callout","content":"Sécurité : préserver une preuve ne t’autorise pas à fouiller n’importe quel système. Agis dans ton périmètre, respecte les règles internes et documente qui a manipulé quoi, quand et pour quelle raison."},{"type":"callout","content":"À retenir : détecter, c’est recouper des signaux imparfaits. Signaler, c’est transmettre des faits exploitables. Préserver les preuves, c’est protéger la chronologie et l’intégrité de ce que tu observeras ensuite."},{"type":"callout","content":"Pour pratiquer : ouvre « Incident : un compte de messagerie compromis », reconstruis la chronologie des journaux et note les preuves à conserver avant toute action irréversible. Termine par le quiz de la leçon."},{"type":"resource","content":"NIST SP 800-61 : guide de gestion des incidents de sécurité (en anglais)","url":"https://csrc.nist.gov/pubs/sp/800/61/r2/final"},{"type":"resource","content":"ANSSI : guide d’hygiène informatique","url":"https://cyber.gouv.fr/publications/guide-dhygiene-informatique"},{"type":"resource","content":"Cybermalveillance.gouv.fr : prévention et assistance aux victimes","url":"https://www.cybermalveillance.gouv.fr/"}]}'::jsonb, 22, 30, 2),
  ('51de45b3-2f38-347c-e9eb-cbac4157ff42', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', '637ef880-3754-45f8-323a-eb7a8f6f7361', 'Auditer l’hygiène d’une petite structure : méthode et rapport', 'Apprends à cadrer un audit d’hygiène, à collecter des constats factuels, à noter des contrôles avec pondération et à restituer des recommandations utiles sans accusation inutile.', '{"blocks":[{"type":"callout","content":"Objectifs : définir le périmètre d’un audit avec accord écrit, suivre une méthode simple en cinq étapes, collecter des preuves factuelles, calculer un score de conformité pondéré, et rédiger un rapport court mais exploitable."},{"type":"callout","content":"Prérequis : avoir suivi « Évaluer un risque : actifs, menaces, vulnérabilités » et « Politiques de sécurité, sensibilisation et culture de la sécurité », ou déjà savoir prioriser des constats et formuler des actions."},{"type":"callout","content":"Mise en situation : Chantal doit auditer l’hygiène numérique du Cabinet Moussa avant l’ouverture d’un nouveau service en ligne. Le budget est limité, le personnel est peu nombreux et la direction veut « savoir où agir vite ». Chantal ne doit ni faire un test d’intrusion sauvage, ni livrer un rapport flou. Elle a besoin d’une méthode claire, de preuves concrètes et d’un langage compréhensible par la direction."},{"type":"callout","content":"Vidéo à venir : Audit d’hygiène : constater, noter, prioriser, restituer"},{"type":"text","content":"Auditer l’hygiène d’une petite structure, c’est vérifier si les pratiques de base sont tenues de façon régulière. Avant de commencer, il faut cadrer le périmètre et l’accord écrit : quels sites, quels postes, quels comptes, quels horaires, quelles limites. Sans cela, tu risques d’examiner trop, pas assez, ou sans autorisation. L’audit d’hygiène n’est pas un jugement moral. C’est un constat structuré qui relie des preuves, des risques et des recommandations réalistes."},{"type":"schema","content":"Méthode en 5 étapes\n1. Cadrer\n2. Inventorier\n3. Constater\n4. Évaluer\n5. Restituer"},{"type":"text","content":"La grille de contrôle peut couvrir au minimum : comptes et mots de passe, mises à jour et antivirus, sauvegardes, réseau et Wi-Fi, données personnelles, sensibilisation, gestion des incidents. Pour chaque point, tu cherches une preuve : observation, entretien, capture d’écran, export de configuration, journal, procédure écrite. Un constat solide ressemble à ceci : « sur 12 postes, 4 n’ont pas reçu les mises à jour critiques depuis plus de 30 jours ». Un constat faible ressemble à ceci : « la sécurité est moyenne ». Le premier se vérifie, le second se discute sans fin."},{"type":"schema","content":"Notation simple\nConforme = 1\nPartiel = 0,5\nNon conforme = 0\n\nScore domaine = somme pondérée / poids total"},{"type":"text","content":"La pondération aide à ne pas traiter tous les contrôles comme s’ils avaient le même poids. Une petite structure peut considérer que la double authentification, les sauvegardes testées et la revue des droits sont plus critiques qu’un point cosmétique. Après la note, il faut prioriser selon le risque et l’effort. Certains gains rapides valent beaucoup : activer la double authentification, retirer un compte partagé, changer le mot de passe de la box, vérifier une restauration. L’audit devient utile quand il débouche sur un plan d’action : quoi, qui, quand, coût ou effort estimé."},{"type":"text","content":"Démonstration guidée : prépare le squelette du rapport avant même la visite. Tu gagneras du temps et tu éviteras d’oublier une rubrique importante. Pendant l’audit, remplis les sections avec des faits observés, pas avec des impressions. Si un point n’a pas pu être vérifié, écris-le explicitement au lieu d’inventer une note."},{"type":"code","content":"Rapport d’audit d’hygiène\n1. Résumé pour la direction\n2. Périmètre et limites\n3. Méthode et sources de preuve\n4. Constats par domaine\n5. Score et priorités\n6. Plan d’action : quoi, qui, quand, effort\n7. Annexes : captures, extraits, inventaire","language":"text"},{"type":"example","content":"Exemple corrigé : pour le domaine « gestion des accès », Chantal pondère trois contrôles. MFA sur la messagerie, poids 5, partiel : 5 × 0,5 = 2,5. Sauvegardes des codes de secours administrateur, poids 3, conforme : 3 × 1 = 3. Revue trimestrielle des droits, poids 2, non conforme : 2 × 0 = 0. Le score du domaine vaut donc (2,5 + 3 + 0) ÷ 10 = 55 %. La priorité logique n’est pas de refaire le rapport, mais de compléter le MFA et d’instaurer la revue des droits."},{"type":"callout","content":"Erreurs fréquentes : juger sans preuve observable ; écrire des recommandations vagues comme « améliorer la sécurité » ; oublier les gains rapides au profit d’un plan trop ambitieux ; diffuser le rapport sans précaution alors qu’il contient parfois des faiblesses sensibles."},{"type":"callout","content":"Sécurité : n’audite qu’avec un accord explicite et reste dans le périmètre convenu. Protège le rapport comme un document sensible : il peut décrire des faiblesses exploitables s’il circule sans contrôle."},{"type":"callout","content":"À retenir : un audit d’hygiène utile est court, factuel et priorisé. La valeur vient des preuves, de la pondération assumée et d’un plan d’action concret. Le rapport doit aider à décider, pas seulement à archiver."},{"type":"callout","content":"Pour pratiquer : prépare-toi à « Projet final : auditer la sécurité du Centre Numérique Soleil » en t’exerçant à noter un domaine, à justifier les preuves et à rédiger des recommandations précises. Termine par le quiz de la leçon."},{"type":"resource","content":"ANSSI : guide d’hygiène informatique","url":"https://cyber.gouv.fr/publications/guide-dhygiene-informatique"},{"type":"resource","content":"NIST : ressources de cybersécurité pour les petites entreprises (en anglais)","url":"https://www.nist.gov/itl/smallbusinesscyber"},{"type":"resource","content":"CNIL : sécuriser les postes de travail","url":"https://www.cnil.fr/fr/securite-securiser-les-postes-de-travail"}]}'::jsonb, 24, 30, 3)
