  ('51aaa996-d408-4f6d-71e6-84b77c76aece', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'ecda4f3a-81bc-0e79-a332-df988e534741', 'fbcfdd5c-013d-e26b-a05b-c31f58ae5049', 'Quiz : encodage, chiffrement et hachage', 70, 1),
  ('d5a21808-9742-451c-c270-226b5d588932', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'ecda4f3a-81bc-0e79-a332-df988e534741', '598013ad-c87c-7b37-81e2-7aee0e3947b9', 'Quiz : clés et signatures numériques', 70, 2),
  ('cfd83a53-5a18-d2fc-c6cd-6b0ab194a0e0', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'ecda4f3a-81bc-0e79-a332-df988e534741', '6a204001-ea83-6f98-7582-68540ef889f4', 'Quiz : HTTPS et certificats', 70, 3),
  ('ce7e2be5-c2a1-8d67-c511-f4e49ab2867d', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'c671b9d4-c599-d9f7-05ac-73248624d87d', '96b02bb7-463c-85b4-fcb9-14feebc83d24', 'Quiz : évaluer un risque', 70, 1),
  ('d62c8a88-9e12-a07f-27ba-9762112dad97', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'c671b9d4-c599-d9f7-05ac-73248624d87d', '446b74b7-abca-595e-a061-3df539d89b4e', 'Quiz : données personnelles et obligations', 70, 2),
  ('f80f5985-78fd-f009-f724-b61e5e80c3a6', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'c671b9d4-c599-d9f7-05ac-73248624d87d', 'a8d04f10-056b-7f35-7140-76d2ddb37768', 'Quiz : gouvernance et culture sécurité', 70, 3),
  ('bdf4854c-d648-3776-5b86-371b9fbe1eef', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', '637ef880-3754-45f8-323a-eb7a8f6f7361', '149a681c-e466-bce3-5710-d81721a059cb', 'Quiz : réponse à incident', 70, 1),
  ('84a9064b-2fce-a865-30e5-2d3729f1aecc', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', '637ef880-3754-45f8-323a-eb7a8f6f7361', '34038745-9c8e-0864-a30f-2f4080735d00', 'Quiz : détection et preuves', 70, 2),
  ('1eb108f2-66ae-6a48-c651-31aadf3c0603', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', '637ef880-3754-45f8-323a-eb7a8f6f7361', '51de45b3-2f38-347c-e9eb-cbac4157ff42', 'Quiz : audit d’hygiène', 70, 3)
insert into public.quiz_questions (id, quiz_id, position, question_type, prompt, explanation, difficulty, xp_reward) values
  ('ae11208f-d6f8-e8df-a16c-d33d090f6f3d', '8a0c13ef-734d-431b-3d28-e75976b915b5', 1, 'single_choice', 'Quel énoncé décrit le mieux la cybersécurité ?', 'La cybersécurité couvre bien plus qu’un outil : elle protège des actifs, des comptes, des appareils et des personnes face à plusieurs types d’atteintes. L’antivirus aide, mais il ne couvre ni les procédures, ni les mots de passe, ni les erreurs humaines.', 'facile', 8),
  ('18d8e57a-9f63-db36-f15a-91c561232109', '8a0c13ef-734d-431b-3d28-e75976b915b5', 2, 'true_false', 'Dire qu’un système est « sécurisé à 100 % » est une bonne manière de raisonner en cybersécurité.', 'Faux : aucun système n’est totalement à l’abri. Le bon raisonnement consiste à réduire le risque par des mesures proportionnées. Promettre le risque zéro fait souvent oublier les priorités vraiment utiles.', 'moyen', 8),
  ('7e4e5b5e-3a63-6ec2-d69c-1ca5c1e16a8a', '8a0c13ef-734d-431b-3d28-e75976b915b5', 3, 'multiple_choice', 'Parmi ces situations, lesquelles relèvent surtout de la disponibilité ? (plusieurs réponses)', 'La disponibilité concerne l’accès au service au bon moment. Un rançongiciel ou une panne de messagerie empêchent de travailler. La fuite de clients relève d’abord de la confidentialité, et la facture modifiée touche surtout l’intégrité.', 'moyen', 7),
  ('3ba31ac4-fd3b-55a0-c074-5b35fd2f281e', '8a0c13ef-734d-431b-3d28-e75976b915b5', 4, 'single_choice', 'Une petite structure perd l’accès à ses dossiers clients pendant une journée. Elle traite 8 dossiers par jour avec 6 000 FCFA de marge chacun. Quel coût direct de marge peux-tu estimer ?', 'Le calcul correct est 8 x 6 000 = 48 000 FCFA. C’est une estimation directe et défensive, utile pour comprendre pourquoi la disponibilité mérite des sauvegardes et un plan de reprise. 24 000 FCFA semble tentant si on oublie la moitié des dossiers.', 'difficile', 7),
  ('ee80a2f0-aa35-7573-1a6a-8ddbde421fa4', '392479f3-eb14-c274-32b6-2a69e6f6b3b9', 1, 'single_choice', 'Qu’appelle-t-on un vecteur d’attaque ?', 'Le vecteur d’attaque est bien le chemin utilisé pour entrer : courriel, mot de passe faible, service exposé, réseau non sûr. Le but final peut être le vol, le sabotage ou l’extorsion, mais ce n’est pas le vecteur.', 'facile', 8),
  ('bd3b6ec0-d675-06bc-8967-44abd07b23d1', '392479f3-eb14-c274-32b6-2a69e6f6b3b9', 2, 'true_false', 'Une attaque par déni de service touche surtout la disponibilité.', 'Vrai : le but principal d’un DoS ou DDoS est d’empêcher un service de répondre. On ne cherche pas d’abord à voler des données, mais à rendre la ressource indisponible pour les utilisateurs légitimes.', 'facile', 8),
  ('21f036f8-cc16-e7f8-38af-8bb025650161', '392479f3-eb14-c274-32b6-2a69e6f6b3b9', 3, 'multiple_choice', 'Quelles situations relèvent surtout d’une menace interne, au moins en partie ? (plusieurs réponses)', 'Une menace interne peut venir d’une erreur ou d’une malveillance à l’intérieur de l’organisation. Le prestataire qui publie un faux site relève plutôt de la fraude externe ou de la chaîne d’approvisionnement selon le contexte.', 'moyen', 7),
  ('e4cea35b-45b7-f173-5f60-e22ef2296998', '392479f3-eb14-c274-32b6-2a69e6f6b3b9', 4, 'single_choice', 'Lis la situation suivante : « Nadia se connecte à un Wi-Fi public sans protection, puis son mot de passe de messagerie est capturé sur une page piégée ». Quelle lecture est la plus utile en premier ?', 'La scène pointe vers un vol d’identifiants via réseau non sûr, faux portail ou faux site de connexion. Les autres réponses paraissent possibles si on lit trop vite, mais elles n’expliquent ni la capture du mot de passe ni le contexte du Wi-Fi public.', 'difficile', 7),
  ('531987a2-702e-f057-48e6-53ddac97572a', '350b9ac4-57ef-1347-c270-c8371699f5e7', 1, 'single_choice', 'Quel principe dit qu’un compte doit recevoir uniquement les droits nécessaires à sa mission ?', 'Le moindre privilège limite l’exposition en réduisant les droits disponibles. Le chiffrement ou la disponibilité répondent à d’autres besoins. La non-répudiation concerne plutôt la preuve d’une action et non le volume des autorisations.', 'facile', 8),
  ('8c14021a-01fd-9c4a-ad95-3e8e9f422033', '350b9ac4-57ef-1347-c270-c8371699f5e7', 2, 'true_false', 'Identification, authentification et autorisation veulent dire exactement la même chose.', 'Faux : l’identification déclare une identité, l’authentification cherche à la prouver, puis l’autorisation décide ce que cette identité peut faire. Confondre ces étapes conduit souvent à de mauvaises conceptions d’accès.', 'moyen', 8),
  ('3ee0f9dd-4dc3-eb49-505e-df644a4940f1', '350b9ac4-57ef-1347-c270-c8371699f5e7', 3, 'multiple_choice', 'Quelles situations illustrent une défense en profondeur utile ? (plusieurs réponses)', 'La défense en profondeur consiste à empiler des couches techniques et organisationnelles. Le mot de passe partagé va au contraire contre l’imputabilité et augmente le risque au lieu de le réduire.', 'moyen', 7),
  ('6bb23e0b-88db-9a07-f9ef-6c7e853f6027', '350b9ac4-57ef-1347-c270-c8371699f5e7', 4, 'single_choice', 'Dans une petite association, la même personne prépare un paiement, l’approuve et l’exécute seule. Quel principe manque le plus clairement ?', 'Quand une seule personne peut réaliser toute l’opération sensible sans contrôle croisé, la séparation des tâches manque. Les autres mesures peuvent être utiles, mais elles ne répondent pas directement à ce risque de fraude ou d’erreur.', 'difficile', 7),
  ('30bfe714-9518-61e4-75bf-37cbf1a2a9e2', 'd0948983-d4f6-c304-99a8-0a6ff76b4144', 3, 'single_choice', 'Dans une petite structure victime d’une compromission de messagerie, quel acteur est le plus directement chargé de coordonner la réponse technique et organisationnelle ?', 'Le CERT ou CSIRT, ou à défaut le responsable sécurité désigné, coordonne la collecte d’informations, les actions de confinement et la circulation des décisions. Le fournisseur d’accès peut aider sur un point précis, mais il ne pilote pas toute la réponse.', 'moyen', 20),
  ('7cd79ed6-a686-e4da-ba8e-83c99d6c0e5a', 'd0948983-d4f6-c304-99a8-0a6ff76b4144', 4, 'multiple_choice', 'Quelles affirmations sont correctes ? (plusieurs réponses)', 'Le white hat agit avec autorisation, la purple team organise l’apprentissage entre offensif et défensif, et l’utilisateur repère souvent les premiers symptômes. Dire qu’un éditeur ne sert plus à rien est faux : il publie des correctifs, des avis et parfois des consignes de mitigation.', 'difficile', 20),
  ('556f7470-ba9f-8555-e38b-f6b6264a79cc', '62d14b68-4653-2a6c-f711-ce889728597b', 1, 'single_choice', 'Quel rôle est le plus directement centré sur la surveillance des alertes et leur qualification quotidienne ?', 'L’analyste SOC suit les alertes, les qualifie et les escalade si nécessaire. Les autres métiers peuvent contribuer à la sécurité, mais ce n’est pas leur mission principale au quotidien.', 'facile', 8),
  ('c7d1069b-b6fc-5e45-6124-e900c9739a05', '62d14b68-4653-2a6c-f711-ce889728597b', 2, 'true_false', 'En cybersécurité, savoir rédiger et expliquer clairement est secondaire par rapport aux compétences techniques.', 'Faux : une bonne analyse mal expliquée aide peu. La rédaction, la pédagogie, la preuve et la méthode permettent aux autres d’agir, de comprendre le risque et de reproduire les bonnes pratiques.', 'moyen', 8),
  ('72b7da73-023a-a582-d53b-4821ed468f71', '62d14b68-4653-2a6c-f711-ce889728597b', 3, 'multiple_choice', 'Quelles démarches sont pertinentes pour un débutant avec peu de moyens ? (plusieurs réponses)', 'Les laboratoires, les comptes rendus et le référentiel NICE permettent d’avancer sans gros budget. Attendre des moyens parfaits bloque inutilement. Ce qui compte d’abord, c’est une progression régulière et documentée.', 'moyen', 7),
  ('bfa08c58-6f1b-7d07-fb8e-d0ff5ae93c33', '62d14b68-4653-2a6c-f711-ce889728597b', 4, 'single_choice', 'Binta aime lire des journaux, comprendre les incidents et expliquer ses conclusions. Quel premier chemin paraît le plus cohérent ?', 'Ce chemin construit d’abord le langage, les observations réseau et la lecture des incidents. Les autres choix sautent des étapes utiles ou misent sur des signes extérieurs sans preuves concrètes de compréhension.', 'difficile', 7),
  ('ec3d7d38-d0d1-2531-cfdb-6a6e5fb599e4', '64dc5581-c967-b537-e463-c0e8e8506cdc', 1, 'single_choice', 'Quel énoncé décrit le mieux ISO/IEC 27001 ?', 'ISO/IEC 27001 est une norme de management de la sécurité de l’information. Elle ne chiffre pas à elle seule et ne remplace ni des outils techniques, ni des procédures réellement appliquées.', 'facile', 8),
  ('e0676d38-4253-dfc9-b6a3-32660f4866aa', '64dc5581-c967-b537-e463-c0e8e8506cdc', 2, 'true_false', 'Être conforme à un référentiel donné garantit automatiquement qu’une organisation est totalement en sécurité.', 'Faux : la conformité peut améliorer la structure, mais elle ne garantit ni l’application réelle, ni l’adaptation au risque, ni l’amélioration continue. Une sécurité vivante demande des vérifications concrètes.', 'moyen', 8),
  ('5289c7dd-0a52-3c7f-ed2c-48200d679a1b', '64dc5581-c967-b537-e463-c0e8e8506cdc', 3, 'multiple_choice', 'Quelles associations sont correctes ? (plusieurs réponses)', 'Le guide d’hygiène de l’ANSSI et EBIOS RM ont bien ces rôles, et les contrats peuvent imposer des obligations fortes. Le NIST CSF n’est pas réservé à un seul secteur ou pays : il peut servir à de nombreuses organisations.', 'moyen', 7),
  ('131cb270-5202-8c75-1785-531f77ce6c24', '64dc5581-c967-b537-e463-c0e8e8506cdc', 4, 'single_choice', 'Une petite association veut d’abord lister ses actions prioritaires sans lancer une certification complète. Quel point de départ est le plus raisonnable ?', 'Commencer par des mesures concrètes et structurantes est le choix le plus réaliste. Copier une norme entière ou attendre passivement donne l’illusion d’avancer sans améliorer tout de suite la protection effective.', 'difficile', 7),
  ('27739cf1-cf92-3e93-a6f8-f30298d8bc78', '73c1a0bf-44b8-298d-05b7-a6d1903b0be9', 1, 'single_choice', 'Quel signal doit t’alerter en priorité pendant un appel de « support » ?', 'La demande immédiate d’un secret, comme un code de validation, est le meilleur indice d’une tentative de manipulation. Connaître le nom de l’organisation ou ton prénom peut venir d’informations publiques et ne prouve rien à lui seul.', 'facile', 8),
  ('8fd018ea-eabc-0845-afee-61a9a03dd70c', '73c1a0bf-44b8-298d-05b7-a6d1903b0be9', 2, 'true_false', 'Vérifier une demande urgente par un second canal montre surtout que tu refuses d’aider l’équipe.', 'Faux : vérifier par un second canal est un réflexe de sécurité, pas un manque de coopération. Cela protège l’équipe, les comptes et l’argent contre les prétextes crédibles qui exploitent précisément la pression du moment.', 'moyen', 8),
  ('2ba1ea43-25d6-d36e-e693-30010e4c9625', '73c1a0bf-44b8-298d-05b7-a6d1903b0be9', 3, 'multiple_choice', 'Quelles mesures peuvent réellement casser une attaque d’ingénierie sociale ? Plusieurs réponses sont justes.', 'Rappeler un numéro officiel, imposer une double validation et encourager le signalement interrompent souvent la chaîne de manipulation. En revanche, envoyer un code parce que l’appel paraît urgent donne exactement à l’attaquant ce qu’il cherche.', 'difficile', 7),
  ('00af3026-4b9a-f482-3c53-63518d33dc4f', '73c1a0bf-44b8-298d-05b7-a6d1903b0be9', 4, 'single_choice', 'Dans ce scénario, à quel moment l’attaque aurait-elle dû être stoppée ? « Bonjour, ici le support. Le directeur est au courant. J’ai besoin du code affiché sur ton téléphone avant 10 h. »', 'Le moment décisif est la demande du code affiché, car ce secret sert souvent à prendre le contrôle du compte. Le nom du directeur peut être public, et attendre un autre message garde la conversation ouverte inutilement.', 'difficile', 7),
  ('1a5336ab-c573-879a-8dbb-aa8daf9856d5', '4a4cc440-1fb2-8653-b315-dbbabeaac2eb', 1, 'single_choice', 'Quel champ doit t’alerter si le message semble venir d’une organisation connue, mais que les réponses partent ailleurs ?', 'Le champ Reply-To indique où partira ta réponse. S’il pointe vers un autre domaine que celui attendu, c’est un excellent signal d’alarme. Received et Date apportent du contexte, mais ils ne montrent pas directement ce piège de redirection.', 'facile', 8),
  ('33fcce67-29f7-f26f-c8c4-b79721f9f130', '4a4cc440-1fb2-8653-b315-dbbabeaac2eb', 2, 'true_false', 'Si un site de connexion affiche un cadenas et « https », cela prouve que le site est légitime.', 'Faux : le cadenas montre surtout que la connexion est chiffrée. Un attaquant peut très bien obtenir un certificat pour un faux domaine crédible. Il faut donc vérifier l’adresse complète et le domaine, pas seulement la présence de HTTPS.', 'moyen', 8),
  ('ae76b341-7108-7420-a6aa-3be3d03c4a24', '4a4cc440-1fb2-8653-b315-dbbabeaac2eb', 3, 'multiple_choice', 'Que peux-tu conclure de cet extrait ? « spf=fail », « dkim=none », « dmarc=fail », Reply-To vers example.net. Plusieurs réponses sont justes.', 'Les échecs SPF et DMARC, l’absence de DKIM et un Reply-To différent montrent une forte incohérence. Les en-têtes ne rendent pas un message fiable par eux-mêmes : ils fournissent justement les indices qui permettent de douter.', 'difficile', 7),
  ('35d9a2a2-0ebf-63de-674d-af254e411d01', '4a4cc440-1fb2-8653-b315-dbbabeaac2eb', 4, 'single_choice', 'Dans l’URL « portail.atlas.example.org.verif-example.net », quel est le domaine enregistrable à vérifier en priorité ?', 'Le vrai domaine se lit de droite à gauche : ici, c’est « verif-example.net ». Le reste n’est qu’un sous-domaine placé pour te rassurer. Beaucoup de faux sites jouent précisément sur cette confusion visuelle.', 'difficile', 7),
  ('24cc548f-66c3-a607-c7d8-52e9995ea9d6', '66b14ff7-c7f2-ff89-bbf6-53add2a9b353', 1, 'single_choice', 'Que dois-tu faire si un appelant dit être ton conseiller et demande le code reçu par SMS pour « bloquer » une fraude ?', 'Le code reçu par SMS ou dans une application sert à prouver que c’est bien toi. Le communiquer donne souvent le contrôle du compte à l’attaquant. Le bon réflexe est de raccrocher puis de rappeler un numéro officiel trouvé par toi.', 'facile', 8),
  ('85177164-98fa-622b-904a-a42ece06688a', '66b14ff7-c7f2-ff89-bbf6-53add2a9b353', 2, 'true_false', 'Le SMS est toujours une preuve d’identité forte, car seul le propriétaire du numéro peut le recevoir.', 'Faux : un SMS peut être intercepté ou détourné, notamment en cas d’échange de carte SIM ou de faiblesse chez l’opérateur. C’est mieux que rien dans certains cas, mais ce n’est pas une preuve absolue d’identité.', 'moyen', 8),
  ('bf0529b2-e7cc-3708-c85f-0f407279fcd8', '66b14ff7-c7f2-ff89-bbf6-53add2a9b353', 3, 'multiple_choice', 'Quels réflexes sont adaptés face à un faux transfert envoyé « par erreur » ? Plusieurs réponses sont justes.', 'La capture d’écran peut être falsifiée ou sortir du contexte. Il faut vérifier le solde réel dans l’application légitime, contacter le support officiel si nécessaire et ne jamais communiquer de secret. Céder sous la pression morale fait précisément réussir l’arnaque.', 'difficile', 7),
  ('8e785570-e18f-613c-0fda-e03890476fd9', '66b14ff7-c7f2-ff89-bbf6-53add2a9b353', 4, 'single_choice', 'Quel indice rend un QR code reçu sur une affiche ou dans un message particulièrement risqué ?', 'Le danger principal d’un QR code est qu’il masque l’adresse réelle tant que tu ne l’as pas ouverte ou prévisualisée. Sa couleur ou sa rapidité n’ont aucun rapport direct avec la sécurité ; le problème vient du manque de visibilité sur la destination.', 'difficile', 7),
  ('6ba98d34-b500-d99c-3fda-a8c32d6d04de', '818e2d83-07cd-0c87-c9b4-2f2c440703f1', 1, 'single_choice', 'Quelle pratique réduit le mieux le risque de bourrage d’identifiants après une fuite chez un autre service ?', 'Le bourrage d’identifiants réutilise des couples déjà volés sur d’autres sites. La seule vraie défense côté utilisateur est donc l’unicité par service. Changer un seul compte ou modifier légèrement le même secret laisse les autres services exposés.', 'facile', 8),
  ('9b6b6e6a-e872-7edb-4172-82cc1eccff8f', '818e2d83-07cd-0c87-c9b4-2f2c440703f1', 2, 'true_false', 'À sécurité égale, la longueur d’une phrase de passe compte souvent plus que l’ajout décoratif de symboles à un mot courant.', 'Vrai : ajouter un symbole à un mot courant reste souvent prévisible, alors qu’augmenter réellement la longueur fait exploser le nombre de combinaisons possibles. Cela ne remplace pas l’unicité, mais améliore bien mieux la résistance à la force brute hors ligne.', 'moyen', 8),
  ('26956ce4-a2a7-1248-e699-915995a5745e', '818e2d83-07cd-0c87-c9b4-2f2c440703f1', 3, 'multiple_choice', 'Quelles affirmations sont justes ? Plusieurs réponses sont correctes.', 'Le stockage par empreinte salée, l’unicité et la compréhension du bourrage d’identifiants sont des bases correctes. En revanche, « azerty » reste faible même s’il n’est connu de personne aujourd’hui, car il fait partie des premiers essais des attaquants.', 'difficile', 7),
  ('1b7fc8a2-119d-7c2b-3f15-1016d3921663', '818e2d83-07cd-0c87-c9b4-2f2c440703f1', 4, 'single_choice', 'Au rythme hypothétique de 10 milliards d’essais par seconde, quel ordre de grandeur est le plus proche pour parcourir 62 puissance 8 combinaisons ?', '62 puissance 8 vaut 218340105584896. Divisé par 10 milliards d’essais par seconde, on obtient environ 21834 secondes, soit environ 6,1 heures. Le piège le plus tentant est de sous-estimer l’impact énorme d’un alphabet large, mais ici le calcul reste de l’ordre de quelques heures seulement.', 'difficile', 7),
  ('e9794926-3fb6-bf61-08a9-afff331bfc1c', 'a37f428a-8e71-2100-c2b9-f405a7bc55ea', 1, 'single_choice', 'Quelle méthode résiste le mieux à un faux site de connexion bien imité ?', 'La clé d’accès, ou passkey, est liée au bon domaine et refuse normalement de s’authentifier sur un faux site. Le SMS et le TOTP peuvent encore être demandés puis saisis sur un site piégé, et la notification push ne corrige pas ce problème d’origine.', 'facile', 8),
  ('e9748e60-a6e8-1b44-aa09-a96a0125974b', 'a37f428a-8e71-2100-c2b9-f405a7bc55ea', 2, 'true_false', 'Un code TOTP reste valable tant que tu ne fermes pas l’application qui l’affiche.', 'Faux : un code TOTP change à intervalles réguliers, souvent toutes les 30 secondes. Fermer ou laisser ouverte l’application ne change pas ce principe. C’est précisément ce renouvellement qui limite la durée d’utilisation du code.', 'moyen', 8),
  ('4b342d08-3732-7bb9-78e9-d6bd8fc36796', 'a37f428a-8e71-2100-c2b9-f405a7bc55ea', 3, 'multiple_choice', 'Quels comptes faut-il protéger en priorité par une double authentification ? Plusieurs réponses sont justes.', 'La messagerie principale sert souvent de clé de récupération pour les autres comptes. Le paiement et l’administration ont un impact direct important. Un compte secondaire sans conséquence est moins prioritaire, même s’il vaut mieux le protéger ensuite si possible.', 'difficile', 7),
  ('159eae86-36ad-f705-139b-4d60f62c884d', 'a37f428a-8e71-2100-c2b9-f405a7bc55ea', 4, 'single_choice', 'Quel risque correspond le mieux aux notifications push ?', 'La fatigue d’approbation survient quand un utilisateur reçoit beaucoup de demandes et finit par en valider une par lassitude. Le vol de carte SIM concerne plutôt le SMS. Les codes de secours restent recommandés, mais leur absence n’est pas le risque spécifique du push.', 'difficile', 7),
  ('cd1da553-69f4-65a5-19a2-7e55aaa2cc16', '3a76d3c6-d09e-3ad9-04d6-0f15c98e98d7', 1, 'single_choice', 'Quelle action est la plus urgente si une alerte fiable indique qu’un ancien mot de passe réutilisé a fuité ?', 'Le vrai danger vient de la réutilisation : il faut donc sécuriser le service touché puis tous les autres comptes partageant le même secret, en commençant par la messagerie principale et les paiements. Attendre ou répondre au message peut faire perdre un temps précieux.', 'facile', 8),
  ('12b5d5a0-15f3-206a-425b-73b41505b40a', '3a76d3c6-d09e-3ad9-04d6-0f15c98e98d7', 2, 'true_false', 'Dans le modèle de vérification de mots de passe compromis par k-anonymat, le service reçoit le mot de passe complet en clair.', 'Faux : le principe consiste justement à ne pas envoyer le mot de passe complet. Seul un préfixe de l’empreinte est transmis, puis la comparaison complète se fait côté client, ce qui réduit l’exposition du secret.', 'moyen', 8),
  ('f0c8e966-ae4d-6dac-7f81-30a2b4870551', '3a76d3c6-d09e-3ad9-04d6-0f15c98e98d7', 3, 'multiple_choice', 'Après une fuite, quels risques secondaires sont plausibles ? Plusieurs réponses sont justes.', 'Une fuite alimente souvent d’autres attaques : réutilisation des identifiants, hameçonnage ciblé et abus de données personnelles pour la récupération de compte. En revanche, rien ne fait disparaître magiquement les traces, les copies ou la revente des données.', 'difficile', 7),
  ('ec9b2edd-8cd2-6bf4-5e78-a5e02c98caf1', '3a76d3c6-d09e-3ad9-04d6-0f15c98e98d7', 4, 'single_choice', 'Quel raisonnement décrit le mieux l’intérêt du préfixe « 5BAA6 » dans l’exemple de l’empreinte SHA-1 de « password » ?', 'Le préfixe « 5BAA6 » sert à montrer l’idée du k-anonymat : on compare une partie de l’empreinte au lieu d’envoyer le mot de passe complet. Ce n’est ni une garantie de reconstruction du secret, ni une recommandation pour stocker des mots de passe avec SHA-1.', 'difficile', 7),
  ('b69c4b8d-9330-278e-b26a-f8285ebd81aa', 'ba2d534d-dea9-ebdb-9a9e-9e0f377a1461', 1, 'single_choice', 'Pourquoi un système en fin de support pose-t-il un problème de sécurité ?', 'Le risque principal vient de l’absence de correctifs : une faille connue peut rester exploitable pendant des mois. Le piège tentant est de croire qu’un système encore fonctionnel est forcément encore protégé, ce qui est faux.', 'facile', 8),
  ('b4653735-06e8-32ee-cf37-48dfba045a72', 'ba2d534d-dea9-ebdb-9a9e-9e0f377a1461', 2, 'true_false', 'Installer deux antivirus actifs en même temps améliore presque toujours la protection d’un poste.', 'Faux : deux antivirus actifs se gênent souvent, ralentissent la machine et peuvent produire des conflits de détection. Le vrai gain vient d’un seul outil bien configuré, à jour, complété par les correctifs et le pare-feu local.', 'moyen', 8),
  ('974bc81a-6d2f-2822-fb5c-abacd685b362', 'ba2d534d-dea9-ebdb-9a9e-9e0f377a1461', 3, 'multiple_choice', 'Quelles actions réduisent réellement la surface d’attaque d’un poste ? (plusieurs réponses)', 'Retirer l’inutile, limiter les services actifs et travailler sans droits d’administration réduisent les possibilités d’abus. Le faux bon choix est le site tiers : même rapide, il ajoute un risque de logiciel modifié ou piégé.', 'difficile', 7),
  ('00f383bb-e9e4-a448-7159-1a408c7e38d1', 'ba2d534d-dea9-ebdb-9a9e-9e0f377a1461', 4, 'single_choice', 'Un parc affiche des retards de 3, 7, 12, 20 et 28 jours. Quel poste faut-il traiter en premier si tu ne peux en corriger qu’un maintenant ?', 'Le poste à 28 jours cumule la plus grande fenêtre d’exposition et doit donc être prioritaire. La moyenne du parc aide à piloter l’ensemble, mais elle ne remplace pas le traitement du cas le plus en retard.', 'moyen', 7),
  ('ce963308-e597-3901-1998-7398c8b6a725', '1a2eb7bc-8915-061e-3f10-3c63db617ad9', 1, 'single_choice', 'Quelle phrase décrit le mieux une sauvegarde ?', 'Une sauvegarde vise la récupération après incident. La réponse qui ressemble le plus, la synchronisation, recopie surtout l’état courant et peut donc propager une suppression ou un chiffrement non désiré.', 'facile', 8),
  ('e760f6cc-81ad-3ee8-e9e1-4c75b3b5433a', '1a2eb7bc-8915-061e-3f10-3c63db617ad9', 2, 'true_false', 'Si tes fichiers sont synchronisés sur deux appareils, tu respectes déjà automatiquement la règle 3-2-1.', 'Faux : deux appareils synchronisés peuvent partager la même panne logique ou la même corruption. La règle 3-2-1 demande plusieurs copies, des supports différents et une copie hors site, pas seulement deux dossiers qui se suivent.', 'moyen', 8),
  ('55b4e0bf-8e4f-1583-49a4-34593f32726c', '1a2eb7bc-8915-061e-3f10-3c63db617ad9', 3, 'multiple_choice', 'Quelles pratiques renforcent vraiment la capacité de restauration ? (plusieurs réponses)', 'Une copie séparée, un chiffrement adapté et un test de restauration réduisent le risque de mauvaise surprise. L’option tentante mais fausse est de tout laisser branché : c’est pratique, mais cela expose toutes les copies au même incident.', 'difficile', 7),
  ('9592682c-749d-f176-d4ce-99b45f392f63', '1a2eb7bc-8915-061e-3f10-3c63db617ad9', 4, 'single_choice', 'Tu planifies 4 sauvegardes complètes de 80 Gio et 24 incrémentales de 4 Gio. Quel espace total dois-tu prévoir ?', 'Le calcul correct est 4 × 80 + 24 × 4 = 320 + 96 = 416 Gio. Le piège le plus courant consiste à oublier les incrémentales ou à les compter comme des complètes, ce qui fausse complètement le dimensionnement.', 'moyen', 7),
  ('ecc148fd-f821-1aa9-9ac2-e81f0e3738f2', '106b7a6b-f2cc-65a1-5d29-b10e6f6ca827', 1, 'single_choice', 'Que protège d’abord le chiffrement complet du disque ?', 'Le chiffrement complet vise la confidentialité des données au repos sur l’appareil. L’erreur la plus tentante est de lui attribuer des pouvoirs réseau qu’il n’a pas : il ne remplace ni HTTPS, ni un pare-feu, ni une bonne prudence sur le Wi-Fi.', 'facile', 8),
  ('695329cf-f264-1f4c-f9e8-0505ed8fe2bd', '106b7a6b-f2cc-65a1-5d29-b10e6f6ca827', 2, 'true_false', 'Si un site affiche HTTPS, le Wi-Fi public utilisé devient automatiquement digne de confiance pour tout le reste.', 'Faux : HTTPS protège surtout l’échange avec ce site précis, pas l’ensemble du réseau local ni les autres services. Un faux point d’accès, une mauvaise application ou une opération sensible sur un mauvais site restent dangereux.', 'moyen', 8),
  ('210312d1-db63-0e8e-5a87-531c52f54ccb', '106b7a6b-f2cc-65a1-5d29-b10e6f6ca827', 3, 'multiple_choice', 'Quels réflexes améliorent vraiment la sécurité d’un Wi-Fi domestique ? (plusieurs réponses)', 'Changer l’administration, choisir un chiffrement moderne et retirer WPS quand il est inutile réduisent les risques. Le faux bon choix est de garder la clé de récupération sur l’appareil : en cas de vol, elle accompagne précisément ce qu’elle devrait protéger.', 'difficile', 7),
  ('7cb7689d-61ec-3d7e-1ab7-3db3600dee2c', '106b7a6b-f2cc-65a1-5d29-b10e6f6ca827', 4, 'single_choice', 'Quelle situation est la plus préoccupante ?', 'Le téléphone sans code cumule risque physique et exposition réseau : l’accès local devient presque immédiat. Les autres situations restent plus maîtrisées, même si aucune configuration n’est parfaite sans vigilance continue.', 'moyen', 7),
  ('388647df-404a-7726-1a7f-dbe68670495e', '51aaa996-d408-4f6d-71e6-84b77c76aece', 1, 'single_choice', 'Quel outil répond d’abord à un besoin de confidentialité ?', 'Le chiffrement protège le contenu contre une lecture non autorisée. Base64 et l’hexadécimal sont réversibles sans secret, tandis que le hachage produit une empreinte utile pour l’intégrité mais pas pour relire le message.', 'facile', 8),
  ('0c2039cf-32fb-e07b-897b-cc96edc92281', '51aaa996-d408-4f6d-71e6-84b77c76aece', 2, 'true_false', 'Une chaîne Base64 doit être considérée comme secrète, car elle ne peut être lue qu’avec une clé.', 'Faux : Base64 est un encodage réversible sans clé, utilisé pour transporter ou représenter des données. Le piège courant consiste à confondre apparence inhabituelle et protection cryptographique réelle.', 'moyen', 8),
  ('c00bd18f-18d5-a3a7-58f7-34830f98ddf5', '51aaa996-d408-4f6d-71e6-84b77c76aece', 3, 'multiple_choice', 'Quelles affirmations sont correctes ? (plusieurs réponses)', 'Un bon système reste sûr même si l’algorithme est connu, SHA-256 s’écrit souvent sur 64 caractères hexadécimaux, et le sel empêche des égalités trop révélatrices. MD5 est le piège classique : il est encore vu partout, mais il n’est plus recommandé pour ce rôle.', 'difficile', 7),
  ('5ca2714e-3e05-b081-5324-1b7b2706d388', '51aaa996-d408-4f6d-71e6-84b77c76aece', 4, 'single_choice', 'Tu vois la chaîne « Qm9uam91cg== ». Quelle interprétation est la plus probable ?', 'Cette chaîne correspond très bien à un encodage Base64, ici celui de « Bonjour ». L’option la plus tentante mais fausse est le hachage : une empreinte SHA-256 aurait une forme hexadécimale beaucoup plus longue.', 'moyen', 7),
  ('86ea2411-9ec7-adf0-6f95-03fd0d9bc3fd', 'd5a21808-9742-451c-c270-226b5d588932', 1, 'single_choice', 'Quel est le principal problème du chiffrement symétrique ?', 'Le vrai défi du symétrique est la distribution sûre de la clé aux deux parties. Le piège le plus courant est de croire qu’il est faible par nature, alors qu’il est au contraire très efficace une fois la clé bien partagée.', 'facile', 8),
  ('a574ab5d-dd24-dac7-b63e-3c6722761e18', 'd5a21808-9742-451c-c270-226b5d588932', 2, 'true_false', 'Vérifier une signature numérique se fait avec la clé publique du signataire.', 'Vrai : le signataire utilise sa clé privée pour créer la signature, et toute personne disposant de la clé publique correspondante peut vérifier le résultat. Inverser les rôles des clés est l’erreur la plus classique.', 'moyen', 8),
  ('6a94f48c-fc15-abac-7bfb-359852b0114d', 'd5a21808-9742-451c-c270-226b5d588932', 3, 'multiple_choice', 'Quelles affirmations sont exactes ? (plusieurs réponses)', 'TLS combine asymétrique et symétrique, une taille RSA de 2048 bits ou plus reste une base courante, et SSH exploite aussi une paire de clés. L’option trompeuse est la signature : elle ne cache pas le contenu, elle en prouve surtout l’origine et l’intégrité.', 'difficile', 7),
  ('18aca14a-1616-fbb9-03d0-677b0cf7d810', 'd5a21808-9742-451c-c270-226b5d588932', 4, 'single_choice', 'Atlas reçoit un contrat signé numériquement. Quel événement fera échouer la vérification ?', 'Une modification du contenu change l’empreinte recalculée et casse la vérification. Renommer ou copier un fichier ne modifie pas son contenu binaire dans ce scénario, et diffuser la clé publique est au contraire attendu.', 'moyen', 7),
  ('db01a0cd-460a-e2e3-6e3a-10c81dc45567', 'cfd83a53-5a18-d2fc-c6cd-6b0ab194a0e0', 1, 'single_choice', 'Que garantit principalement HTTPS quand tout se passe bien ?', 'HTTPS protège le canal entre le client et le serveur et aide à vérifier l’identité du serveur présenté. Le piège le plus fréquent est d’y voir une garantie globale de fiabilité du site, ce qu’aucun certificat ne peut promettre seul.', 'facile', 8),
  ('0bb1f57c-50be-0098-cba7-282575210ff7', 'cfd83a53-5a18-d2fc-c6cd-6b0ab194a0e0', 2, 'true_false', 'Un site d’hameçonnage peut lui aussi afficher un cadenas HTTPS valide.', 'Vrai : un certificat valide prouve surtout qu’un serveur contrôle un domaine et présente une chaîne de confiance acceptable. Il ne garantit pas que ce domaine n’imite pas frauduleusement un autre service.', 'moyen', 8),
  ('b402d76a-64c4-b467-6dbf-36b76d7ddd0b', 'cfd83a53-5a18-d2fc-c6cd-6b0ab194a0e0', 3, 'multiple_choice', 'Quels éléments sont typiquement vérifiés dans un certificat de serveur ? (plusieurs réponses)', 'Le nom, les dates et la chaîne de confiance sont au cœur de la vérification. L’option trompeuse est le nombre de visiteurs : c’est peut-être intéressant pour le marketing, mais cela n’a rien à voir avec la validité cryptographique du certificat.', 'difficile', 7),
  ('87f43f91-bd85-b38c-1413-11c9fe7da64b', 'cfd83a53-5a18-d2fc-c6cd-6b0ab194a0e0', 4, 'single_choice', 'Le navigateur signale que le certificat présenté par un portail sensible est expiré. Quelle réaction est la plus prudente ?', 'Une expiration casse une vérification importante et doit déclencher une pause. Continuer sans contrôle expose à des erreurs d’identité ou à une interception. Le design du site ou le souvenir d’une visite précédente ne remplacent pas cette vérification technique.', 'moyen', 7),
  ('d77cc264-9c24-ebb2-b807-f6c9aad72d61', 'ce7e2be5-c2a1-8d67-c511-f4e49ab2867d', 1, 'single_choice', 'Quelle formulation décrit correctement un risque ?', 'La bonne réponse relie ce que tu protèges, ce qui peut lui nuire et la faiblesse exploitable. Une menace seule ou une vulnérabilité seule reste trop vague pour décider d’une priorité ou d’une mesure concrète.', 'facile', 8),
  ('edb64b8d-2b22-64ae-dae9-70891c47e5e4', 'ce7e2be5-c2a1-8d67-c511-f4e49ab2867d', 2, 'multiple_choice', 'Quelles actions relèvent bien d’un traitement du risque ? (plusieurs réponses)', 'Activer une mesure réduit le risque, abandonner un usage l’évite, et une assurance peut en transférer une partie. En revanche, écrire seulement « critique » ne traite rien : cela décrit une priorité sans action.', 'moyen', 8),
  ('0923012e-dbae-0519-f819-402919f12439', 'ce7e2be5-c2a1-8d67-c511-f4e49ab2867d', 3, 'true_false', 'Si un risque est noté 12 sur 16, cela signifie qu’il se réalisera forcément.', 'Faux : un score élevé signale une priorité de traitement, pas une certitude. La note combine vraisemblance et impact pour aider à décider avant l’incident, justement parce qu’on ne peut pas prédire l’avenir avec certitude.', 'moyen', 7),
  ('649c4d86-e28d-31f4-6d38-e2e4337664be', 'ce7e2be5-c2a1-8d67-c511-f4e49ab2867d', 4, 'single_choice', 'Une association note « base des adhérents, exposition sur une messagerie sans MFA, vraisemblance 4, impact 4 ». Quel choix est le plus cohérent ?', 'Un score de 16 est critique : il mérite une action rapide avant un scénario moyen noté 6. La formule est volontairement simple mais utile, et attendre un achat ou un incident réel serait justement une mauvaise gestion du risque.', 'difficile', 7),
  ('fe95980f-60e8-27c1-afb2-597e507c8e1a', 'd62c8a88-9e12-a07f-27ba-9762112dad97', 1, 'single_choice', 'Quelle information est la plus clairement une donnée personnelle ?', 'Le nom et le téléphone permettent d’identifier directement une personne. Les autres éléments, pris seuls dans cet énoncé, ne permettent pas d’identifier quelqu’un avec la même évidence.', 'facile', 8),
  ('928ad32c-7e8a-9015-0800-9f33d4164171', 'd62c8a88-9e12-a07f-27ba-9762112dad97', 2, 'true_false', 'Si une violation de données présente un risque pour les personnes, le délai de notification de référence au titre du RGPD est de 72 heures après en avoir pris connaissance.', 'Vrai : la logique n’est pas « 72 heures après l’incident réel », mais bien après le moment où l’organisation en prend connaissance. Cela oblige à documenter l’heure de découverte et à évaluer rapidement le risque.', 'moyen', 8),
  ('475d4e04-92e3-623a-cf7a-8855256de10f', 'd62c8a88-9e12-a07f-27ba-9762112dad97', 3, 'multiple_choice', 'Quelles pratiques respectent mieux les principes de protection des données ? (plusieurs réponses)', 'Expliquer la finalité, minimiser la collecte et prévoir la rectification ou la suppression vont dans le sens des principes de licéité, minimisation et durée limitée. En revanche, garder tous les exports « au cas où » contredit justement ces principes.', 'moyen', 7),
  ('627faf3c-d047-92d8-b944-690ee479f8f2', 'd62c8a88-9e12-a07f-27ba-9762112dad97', 4, 'single_choice', 'Une petite association confie l’envoi de courriels à un prestataire selon ses instructions. Quel énoncé est le plus juste ?', 'La structure qui décide du but et des moyens essentiels du traitement reste en général responsable de traitement. Le prestataire agit alors comme sous-traitant selon le cadre prévu. Le prix du service ne change pas cette logique.', 'difficile', 7),
  ('9ddd56de-f01c-4af4-efb6-485560a53f94', 'f80f5985-78fd-f009-f724-b61e5e80c3a6', 1, 'single_choice', 'Quel énoncé décrit le mieux une bonne politique de sécurité pour une petite structure ?', 'Une politique utile doit être lisible, applicable et reliée à des rôles concrets. Un document caché ou purement punitif ne crée pas d’habitudes sûres et freine le signalement des incidents.', 'facile', 8),
  ('e899758f-b645-43fc-cb0d-5602579a9395', 'f80f5985-78fd-f009-f724-b61e5e80c3a6', 2, 'true_false', 'Une culture sans blâme signifie qu’aucune erreur n’a plus de conséquence.', 'Faux : sans blâme ne veut pas dire sans responsabilité. Cela signifie qu’on favorise le signalement rapide et l’apprentissage, au lieu de pousser les personnes à cacher leurs erreurs par peur de la réaction.', 'moyen', 8),
  ('18ce2731-306c-ac0a-fc18-93e368fcdca9', 'f80f5985-78fd-f009-f724-b61e5e80c3a6', 3, 'multiple_choice', 'Quels indicateurs peuvent aider un référent sécurité ? (plusieurs réponses)', 'Ces trois indicateurs disent quelque chose sur les accès, les habitudes et la remontée d’alerte. En revanche, compter les fonds d’écran n’aide pas à piloter un risque de sécurité identifié.', 'moyen', 7),
  ('c3afc351-1ea4-218d-8ede-3542284e7838', 'f80f5985-78fd-f009-f724-b61e5e80c3a6', 4, 'single_choice', 'Dans une équipe où les collègues cachent leurs clics sur des messages suspects, quelle priorité est la plus pertinente ?', 'Quand les personnes cachent leurs erreurs, le problème est d’abord culturel et organisationnel. Un canal clair et une réponse non humiliante améliorent la détection réelle. Ajouter du jargon ou ne suivre que les sanctions aggrave souvent le silence.', 'difficile', 7),
  ('6de6af67-7347-71c2-6e84-5eda73b777e3', 'bdf4854c-d648-3776-5b86-371b9fbe1eef', 1, 'single_choice', 'Quelle étape vient juste après l’identification dans le cycle en six étapes présenté ici ?', 'Une fois l’incident qualifié, la priorité est d’empêcher son extension. La récupération et le retour d’expérience viennent plus tard, après la maîtrise de la propagation et la suppression de la cause.', 'facile', 8),
  ('ea486952-44e7-c4ee-1492-8c2229cf3b4f', 'bdf4854c-d648-3776-5b86-371b9fbe1eef', 2, 'true_false', 'Éteindre immédiatement toute machine touchée est toujours la meilleure décision de confinement.', 'Faux : couper brutalement peut parfois détruire des preuves volatiles utiles à l’analyse. Le bon réflexe est de choisir une mesure de confinement adaptée au scénario, par exemple isolation réseau ou désactivation d’un compte.', 'moyen', 8),
  ('da515661-e185-830c-bf30-98ee95461c88', 'bdf4854c-d648-3776-5b86-371b9fbe1eef', 3, 'multiple_choice', 'Quelles actions relèvent bien du confinement ? (plusieurs réponses)', 'Isoler, révoquer et suspendre limitent la propagation ou l’usage malveillant en cours. En revanche, supprimer les journaux détruit des éléments utiles pour comprendre, prouver et corriger correctement l’incident.', 'moyen', 7),
  ('7457e7ff-d935-916c-96d0-33549d065502', 'bdf4854c-d648-3776-5b86-371b9fbe1eef', 4, 'single_choice', 'Dans une petite structure touchée par un rançongiciel, quelle formulation montre la meilleure maturité ?', 'Cette réponse garde l’ordre logique : observation, confinement, vérification des sauvegardes puis décision de restauration. Les autres options sautent des étapes essentielles ou privilégient la communication avant la compréhension.', 'difficile', 7),
  ('fc857093-b5d2-b82c-60c4-995f61c75fc4', '84a9064b-2fce-a865-30e5-2d3729f1aecc', 1, 'single_choice', 'Quel énoncé ressemble le plus à un bon signalement initial ?', 'Ce signalement précise quand, qui, où et quoi. Les autres formulations sont trop vagues pour aider à qualifier l’incident ou à retrouver les bons journaux sans perdre du temps.', 'facile', 8),
  ('1220eae1-fa57-7d3b-154d-5e4a4bdb9580', '84a9064b-2fce-a865-30e5-2d3729f1aecc', 2, 'true_false', 'Pour comparer des journaux issus de plusieurs systèmes, convertir toutes les heures en UTC peut éviter des erreurs d’interprétation.', 'Vrai : quand les sources n’utilisent pas le même fuseau, l’UTC fournit un repère commun. Sans cette conversion, une action peut sembler antérieure ou postérieure alors que seul l’affichage diffère.', 'moyen', 8),
  ('59e77263-ba15-1018-9dbe-71af9bf02329', '84a9064b-2fce-a865-30e5-2d3729f1aecc', 3, 'multiple_choice', 'Quelles pratiques aident à préserver des preuves exploitables ? (plusieurs réponses)', 'Copier, tracer la manipulation et contrôler l’intégrité renforcent la valeur de la preuve. Supprimer les journaux lus détruit au contraire des éléments qui peuvent devenir utiles plus tard, même s’ils semblent banals au premier regard.', 'moyen', 7),
  ('8005124c-52fc-fb6b-0b35-484ae1fbca68', '84a9064b-2fce-a865-30e5-2d3729f1aecc', 4, 'single_choice', 'Si un journal affiche « 10:25+02:00 » et qu’un autre affiche « 09:50Z », quelle conclusion est correcte après conversion ?', 'Le décalage +02:00 signifie qu’il faut retrancher deux heures pour obtenir l’UTC : 10:25+02:00 devient 08:25Z. L’événement de 08:25Z est donc antérieur à 09:50Z.', 'difficile', 7),
  ('126f5047-85c7-1114-d5b3-85d944992c99', '1eb108f2-66ae-6a48-c651-31aadf3c0603', 1, 'single_choice', 'Quel élément doit être clarifié avant de lancer l’audit ?', 'Sans périmètre clair ni accord écrit, tu risques d’auditer sans autorisation ou de produire un résultat inutile. Les autres éléments sont secondaires par rapport au cadre et aux limites de la mission.', 'facile', 8),
  ('caf6fe94-6e6c-eeea-b75a-6dda0668f1d6', '1eb108f2-66ae-6a48-c651-31aadf3c0603', 2, 'true_false', 'Le constat « la sécurité est moyenne » est suffisant pour justifier une recommandation.', 'Faux : ce constat n’est ni mesurable ni vérifiable. Un audit crédible s’appuie sur des faits observables, comme un nombre de postes non à jour, un contrôle absent ou une procédure introuvable.', 'moyen', 8),
  ('93fd3fab-bbff-a9fc-e741-f5f70c19f802', '1eb108f2-66ae-6a48-c651-31aadf3c0603', 3, 'multiple_choice', 'Quelles pratiques rendent un rapport d’audit plus utile ? (plusieurs réponses)', 'Une preuve, une priorité et un plan d’action rendent le rapport exploitable. En revanche, déclarer « non conforme » sans vérification fabrique une certitude artificielle et affaiblit la crédibilité de l’audit.', 'moyen', 7),
  ('a9f812dd-05fc-2ab8-6523-a8506b1c8259', '1eb108f2-66ae-6a48-c651-31aadf3c0603', 4, 'single_choice', 'Un domaine obtient 55 % après pondération. Quelle réaction est la plus pertinente ?', 'Le score sert à prioriser, pas à humilier ni à rassurer artificiellement. Un 55 % signale des écarts significatifs : il faut cibler les mesures les plus utiles plutôt que nier le résultat ou poursuivre une perfection irréaliste.', 'difficile', 7)
insert into public.quiz_answers (id, question_id, position, label, is_correct) values
  ('3bb49017-7165-5b63-14c3-bbecd68e9bf4', 'ae11208f-d6f8-e8df-a16c-d33d090f6f3d', 1, 'Installer un antivirus sur tous les ordinateurs', false),
  ('847907cc-3286-e7a3-0364-fe19a5c76705', 'ae11208f-d6f8-e8df-a16c-d33d090f6f3d', 2, 'Protéger systèmes, réseaux, données et personnes contre les usages non autorisés, les manipulations et les interruptions', true),
