insert into public.labs (id, slug, title, description, category, difficulty, xp_reward, objectives, hints, terminal_lines, position, course_id, format, briefing, constraints, tools, requires_computer, is_assessment, estimated_minutes) values
  ('0fd79772-16c1-88dd-7689-69dbf1f61367', 'tp-analyse-phishing', 'TP 1 : disséquer un courriel d’hameçonnage', 'Tu examines un faux message bancaire, un SMS de livraison et une conversation de paiement mobile pour repérer les signaux d’alerte et choisir le bon premier réflexe si quelqu’un a cliqué.', 'securite', 'debutant', 130, array['Distinguer domaine affiché, domaine réel et adresses de retour', 'Compter des signaux d’alerte précis sans te laisser distraire par le bruit', 'Choisir le bon premier réflexe après une saisie de mot de passe sur un faux site']::text[], array['Lis les en-têtes du haut vers le bas puis les Received du bas vers le haut.', 'Pour un lien trompeur, regarde le domaine de droite à gauche.', 'Dans l’arnaque mobile, l’élément critique est demandé après l’arrivée d’un SMS.']::text[], '{}'::text[], 500, '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'logs', 'Le mardi 3 mars 2026, Aïssatou Ndiaye reçoit un courriel qui prétend venir de Banque Horizon. Le message annonce une suspension rapide, pousse vers un lien de vérification et joint une prétendue facture. En parallèle, un SMS de livraison puis un faux agent de paiement mobile réclament un code temporaire. Ta mission est de lire les en-têtes, les adresses de retour, la vraie destination du lien et la conversation mobile pour distinguer le vrai du faux, puis d’indiquer le bon premier réflexe si le mot de passe a déjà été saisi sur la fausse page.', array['Travaille uniquement sur les fichiers fictifs fournis ici.', 'N’ouvre aucun lien ni pièce jointe ailleurs que dans le labo.']::text[], array['Visionneuse de journaux CyberPingo', 'Guide pas à pas du TP 1', 'Un éditeur de texte ou un simple navigateur si tu préfères lire les fichiers hors ligne']::text[], false, false, 35),
  ('db853d51-4336-09b4-eae5-b1b058490092', 'tp-audit-mots-de-passe', 'TP 2 : auditer des mots de passe et des comptes', 'Tu recoupes un inventaire de comptes et un extrait d’empreintes SHA-256 sans sel pour retrouver quelques mots de passe faibles, mesurer le risque et prioriser la première mesure de réduction d’exposition.', 'securite', 'intermediaire', 160, array['Comparer un dictionnaire à des empreintes SHA-256 sans sel', 'Lire un inventaire de comptes pour prioriser les risques réels', 'Relier mot de passe faible, privilèges et absence de double authentification']::text[], array['Une empreinte identique sur deux lignes signifie le même mot de passe.', 'Pour le compte humain résistant au dictionnaire, regarde d’abord les identifiants de personnes, pas les comptes techniques.', 'La règle de priorité du guide ne dépend pas d’une intuition mais d’un croisement précis de trois critères.']::text[], '{}'::text[], 510, '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'logs', 'Le lundi 9 mars 2026, Jean-Marc Tchoumi récupère un extrait d’un ancien outil interne qui stockait des empreintes SHA-256 sans sel, ainsi qu’un inventaire des comptes de la messagerie de Soleil. Tu dois comparer ces empreintes à un petit dictionnaire fictif, repérer les réutilisations, mesurer l’ancienneté des mots de passe et déterminer quel compte doit être traité en premier. Le but n’est pas d’attaquer un vrai service, mais de comprendre pourquoi un mot de passe faible, réutilisé et sans double authentification devient immédiatement dangereux.', array['N’utilise que le dictionnaire fictif fourni avec ce labo.', 'Ne colle jamais de vrai mot de passe dans un service externe.']::text[], array['Visionneuse de journaux CyberPingo', 'Guide pas à pas du TP 2', 'Node.js, PowerShell ou un shell Unix pour recalculer des empreintes']::text[], true, false, 50),
  ('75586b43-2547-2060-a233-aec440b878c0', 'tp-hygiene-postes', 'TP 3 : auditer l’hygiène d’un parc de postes', 'Lis un inventaire de parc, repère les retards de maintenance et transforme des constats bruts en priorités d’action claires pour la directrice.', 'securite', 'debutant', 140, array['Comparer un inventaire à une table de fin de support', 'Mesurer des retards de mises à jour, d’antivirus et de sauvegarde en jours', 'Appliquer une grille de risque simple pour désigner le poste le plus exposé', 'Vérifier la règle 3-2-1 et calculer un taux de conformité global']::text[], array['Commence par relever toutes les dates du même type dans le même fichier.', 'Le guide distingue bien le journal des sauvegardes et le test de restauration.', 'Pour la conformité, chaque poste compte pour six contrôles exactement.']::text[], '{}'::text[], 520, '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'logs', 'Le jeudi 12 mars 2026, Jean-Marc Tchoumi t’apporte l’inventaire exporté des 12 postes du Centre Numérique Soleil, le tableau des fins de support, le journal des sauvegardes nocturnes et la note sur les copies 3-2-1. La directrice veut une lecture simple : quels retards sont réellement dangereux, quel poste cumule le plus de points faibles, et où faut-il corriger en premier.', array['Tu travailles uniquement sur les exports fournis, dans un cadre pédagogique entièrement fictif.', 'Ne lances aucune commande sur un vrai poste et ne modifies aucune vraie configuration de sauvegarde ou de chiffrement.']::text[], array['Visionneuse de journaux CyberPingo', 'Un terminal pour faire des écarts de dates si tu veux les recalculer', 'Le guide du labo, qui donne la grille de score et la formule de conformité']::text[], false, false, 45),
  ('3fddeace-1761-3450-bd81-bfb403bb73a3', 'tp-integrite-chiffrement', 'TP 4 : intégrité, chiffrement et certificats', 'Tu compares des empreintes SHA-256, décodes trois messages, reconnais des familles de condensats et lis deux certificats X.509 pour vérifier validité, couverture de nom et taille de clé.', 'cryptographie', 'intermediaire', 160, array['Comparer des empreintes publiées aux octets réellement téléchargés', 'Distinguer base64, hexadécimal, condensats et chiffrement de César', 'Lire les dates, les SAN et la taille de clé d’un certificat X.509']::text[], array['Un seul fichier ne correspond pas au manifeste : compare chaque ligne au lieu de supposer.', 'La longueur d’un condensat donne déjà un indice fort sur l’algorithme utilisé.', 'Un certificat ne couvre que son nom commun utile et surtout les SAN listés.']::text[], '{}'::text[], 530, '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'logs', 'Le lundi 16 mars 2026, Idriss Camara télécharge trois petits fichiers pour la salle de formation. L’éditeur publie leurs empreintes SHA-256, mais l’un des fichiers fournis ici a été modifié. En plus de cette vérification d’intégrité, tu dois décoder quelques messages d’exemple et contrôler un certificat du site de Soleil ainsi qu’un second certificat plus ancien. Ta mission est de montrer que tu sais distinguer intégrité, encodage, chiffrement simple et validation d’un certificat, sans jamais confondre longueur de condensat et confiance réelle.', array['Vérifie uniquement les fichiers fictifs du labo.', 'Ne te fie pas à l’apparence d’un fichier ou d’un certificat : lis les champs utiles.']::text[], array['Visionneuse de journaux CyberPingo', 'Guide pas à pas du TP 4', 'Node.js, PowerShell ou un shell Unix pour recalculer et décoder']::text[], true, false, 50),
  ('abd6404e-6914-ba7f-6a04-a0faae4f4122', 'tp-registre-risques', 'TP 5 : construire un registre de risques', 'Transforme un atelier de risques en réponses exploitables : classification C I D, calcul des scores, choix de traitement et moindre privilège.', 'securite', 'debutant', 150, array['Classer un incident selon la propriété principalement touchée', 'Calculer et comparer des scores de risques', 'Repérer l’actif qui concentre le plus de risque', 'Appliquer le moindre privilège sur une table d’accès simple']::text[], array['Pour les incidents passés, ne retiens qu’une propriété principale par phrase.', 'Le scénario le plus élevé ne dépend pas du ressenti mais du produit vraisemblance fois impact.', 'Additionne les scores par actif pour voir où se concentre le risque cumulé.']::text[], '{}'::text[], 540, '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'logs', 'Le mercredi 18 mars 2026, Mariam Sow réunit l’équipe du Centre Numérique Soleil pour un atelier de risques. Tu disposes de l’inventaire des actifs, d’une liste de scénarios cotés, de six incidents passés résumés en une phrase et d’une table de droits sur le dossier de comptabilité. Ton rôle est de transformer ces éléments en registre lisible et cohérent.', array['Tu raisonnes sur des actifs fictifs et des cotations déjà posées pendant l’atelier.', 'Ne fais aucune hypothèse supplémentaire sur les droits ou sur la gravité : tout doit venir des fichiers fournis.']::text[], array['Visionneuse de journaux CyberPingo', 'Une calculatrice ou Node.js pour multiplier vraisemblance et impact', 'Le guide du labo, qui rappelle les niveaux et les traitements']::text[], false, false, 45),
  ('a4e51978-2e64-b285-a90f-7ee13bc08b82', 'incident-compte-compromis', 'Incident : un compte de messagerie compromis', 'Reconstitue un incident de messagerie de bout en bout, mesure la fenêtre d’exposition et choisis les premières actions de confinement adaptées.', 'securite', 'intermediaire', 220, array['Retrouver la première connexion malveillante et ses indices techniques', 'Lire un journal d’audit de boîte mail pour confirmer l’accès réel au contenu', 'Calculer une fenêtre d’exposition et une échéance réglementaire', 'Choisir une mesure de confinement adaptée et justifier la notification']::text[], array['Cherche d’abord le premier succès anormal du compte ciblé, pas le premier échec.', 'La création puis la suppression de la règle de transfert encadrent la fenêtre d’exposition.', 'Le fichier qui prouve l’accès à la boîte n’est pas celui des authentifications.']::text[], '{}'::text[], 550, '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'logs', 'Le mercredi 25 mars 2026 à 09:40 UTC, Yao Kouassi signale que des collègues reçoivent de lui des messages étranges. Mariam Sow te demande de reconstituer l’incident à partir du journal de connexions, de la table de géolocalisation, du journal d’audit de la boîte et du courriel d’hameçonnage signalé. Tu dois retrouver la chronologie, la cause racine, la durée d’exposition et les actions immédiates à prendre.', array['Tu analyses des traces figées dans un cadre purement pédagogique, sans te connecter à aucun vrai service.', 'Toutes les heures du journal sont en UTC et doivent rester en UTC dans tes réponses.']::text[], array['Visionneuse de journaux CyberPingo', 'Un terminal pour filtrer et recalculer des écarts de temps', 'Le guide de l’incident, qui rappelle la règle des 72 heures et le premier confinement attendu']::text[], false, true, 60),
  ('379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 'projet-audit-soleil', 'Projet final : auditer la sécurité du Centre Numérique Soleil', 'Synthétise des constats de terrain, calcule des scores d’audit, priorise les actions et transforme des notes brutes en décisions défendables.', 'securite', 'intermediaire', 260, array['Calculer un score pondéré par domaine et un score global', 'Compter les non-conformités et repérer le domaine le plus faible', 'Trier un plan d’action par risque et effort', 'Relier des constats concrets à des obligations simples de protection des données']::text[], array['La grille note, les notes justifient et le fichier de risques priorise.', 'Les gains rapides combinent un effort faible et un risque déjà significatif.', 'Le guide précise exactement comment compter les personnes à sensibiliser en priorité.']::text[], '{}'::text[], 560, '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'logs', 'Le mardi 31 mars 2026, tu interviens comme auditeur bénévole au Centre Numérique Soleil. Tu repars avec des notes de terrain numérotées, une grille d’audit pondérée, un fichier de risques associés aux constats et un modèle de rapport. Ton objectif est de noter l’association, d’identifier le domaine le plus faible, de classer les priorités d’action et de vérifier les points réglementaires de base.', array['Tu t’appuies uniquement sur les constats, la grille et le fichier de risques fournis dans le projet.', 'Toutes les réponses doivent être déduites des pièces, sans inventer de contrôle ni de risque supplémentaire.']::text[], array['Visionneuse de journaux CyberPingo', 'Un terminal pour refaire les calculs de dates et de pourcentages', 'Le guide du projet, qui donne la formule de score et la règle de priorité']::text[], false, true, 90)
insert into public.lab_tasks (id, lab_id, position, prompt, hint, answer_format) values
  ('3cfe871f-ac28-fc55-31f1-66b5eeea20b6', '0fd79772-16c1-88dd-7689-69dbf1f61367', 1, 'Dans le champ From du courriel brut, quel est le domaine réel de l’expéditeur qui se cache derrière le nom affiché « Banque Horizon, Service Sécurité » ?', 'Ne retiens pas le nom affiché : isole l’adresse entre chevrons puis lis sa partie après le signe @.', 'Nom de domaine'),
  ('3995bc76-a910-fda9-f60b-fc3ccda652f4', '0fd79772-16c1-88dd-7689-69dbf1f61367', 2, 'Quel domaine apparaît dans le Return-Path, donc dans l’adresse de rebond utilisée si le message est refusé ?', 'Cherche la première ligne du fichier : elle commence par Return-Path.', 'Nom de domaine'),
  ('2fced884-af70-5593-6669-49ff4a238ac8', '0fd79772-16c1-88dd-7689-69dbf1f61367', 3, 'Quelle est l’adresse IPv4 du premier saut externe à l’origine du message, avant son arrivée sur l’infrastructure de Soleil ?', 'Dans les lignes Received, pars du plus ancien saut et ignore le réseau local 192.168.77.0/24.', 'Adresse IPv4'),
  ('0a0fc54c-78a2-0146-1dca-708b348e1e0c', '0fd79772-16c1-88dd-7689-69dbf1f61367', 4, 'Quel est le résultat SPF annoncé dans Authentication-Results pour ce message ?', 'Repère la portion spf=... dans le bloc Authentication-Results.', 'Un mot'),
  ('8d9f1b28-f3ac-918f-0d50-d702b2e1f1d5', '0fd79772-16c1-88dd-7689-69dbf1f61367', 5, 'Si tu lis la vraie destination du lien de droite à gauche, quel est son domaine enregistrable réel ?', 'Trouve d’abord l’hôte complet de la destination réelle, puis garde seulement le domaine réellement possédé tout à droite.', 'Nom de domaine'),
  ('e50f5008-dc26-a5f9-a308-86372d119ea3', '0fd79772-16c1-88dd-7689-69dbf1f61367', 6, 'Quelle est la vraie extension finale de la pièce jointe annoncée dans le courriel brut ?', 'Ne t’arrête pas au milieu du nom : regarde ce qui vient après le dernier point.', 'Extension seule, sans point'),
  ('da286c3f-44c1-b30a-0b93-c849cc2a2189', '0fd79772-16c1-88dd-7689-69dbf1f61367', 7, 'Quel délai maximum le message laisse-t-il avant la suspension annoncée du compte de l’association ?', 'Cherche la contrainte de temps écrite dans le corps du courriel, juste avant la conséquence annoncée.', 'Un nombre d’heures'),
  ('6b86aab3-f471-9d7e-0b5a-db99415940a4', '0fd79772-16c1-88dd-7689-69dbf1f61367', 8, 'Dans le SMS et la conversation mobile, quel élément précis ne faut-il jamais transmettre à un tiers, même s’il prétend « vérifier » l’opération ? Réponds par une lettre. a) le code reçu par SMS b) le prénom complet c) l’heure de réception du message d) le nom du service affiché', 'Repère la demande du faux agent, puis choisis l’option qui correspond à un secret temporaire destiné à valider une opération.', 'Une seule lettre'),
  ('9dbb1074-c473-a642-74b1-21bcbabefef4', '0fd79772-16c1-88dd-7689-69dbf1f61367', 9, 'Après avoir saisi ton mot de passe sur la fausse page, quelle première action est correcte ? Réponds par une lettre. a) attendre un rappel bancaire b) changer le mot de passe depuis le vrai site puis activer la double authentification c) répondre au courriel pour demander si le message est légitime d) transférer le message à tous les collègues', 'Agis d’abord sur le vrai service pour reprendre le contrôle du compte, pas sur le message reçu.', 'Une seule lettre'),
  ('94655ba1-3833-f9c2-d82c-9cc6efd2c78f', '0fd79772-16c1-88dd-7689-69dbf1f61367', 10, 'D’après la grille de 10 signaux du guide, combien de signaux sont réellement présents dans ce courriel ?', 'La grille mélange des signaux présents et absents. Vérifie les 10 points un par un au lieu de compter au jugé.', 'Un nombre entier'),
  ('8a9d183d-028a-f748-63b4-46ad28ed7bb4', 'db853d51-4336-09b4-eae5-b1b058490092', 1, 'Quel mot de passe en clair retrouves-tu pour le compte jm.tchoumi en comparant le dictionnaire et l’empreinte SHA-256 fournie ?', 'Hache les mots du dictionnaire un par un, puis compare exactement les 64 caractères hexadécimaux.', 'Le mot de passe fictif complet'),
  ('377f7dec-d49c-490a-fe05-806850a33103', 'db853d51-4336-09b4-eae5-b1b058490092', 2, 'Quel mot de passe en clair retrouves-tu pour le compte yao.kouassi ?', 'Le procédé est exactement le même : dictionnaire, SHA-256, comparaison caractère par caractère.', 'Le mot de passe fictif complet'),
  ('b9e4be1c-cf1d-e962-ec70-3c1568fa65cf', 'db853d51-4336-09b4-eae5-b1b058490092', 3, 'Quel mot de passe en clair retrouves-tu pour le compte salle-03 ?', 'Si deux comptes partagent le même condensat, un seul calcul permet de retrouver les deux secrets.', 'Le mot de passe fictif complet'),
  ('ed2ef513-097b-8d7a-410c-264e749559af', 'db853d51-4336-09b4-eae5-b1b058490092', 4, 'Combien de comptes du fichier d’empreintes partagent exactement la même empreinte SHA-256, signe d’une réutilisation du même mot de passe ?', 'Cherche les doublons dans la colonne des empreintes, puis compte les comptes concernés, pas seulement le nombre de doublons.', 'Un nombre entier'),
  ('f1ed15f5-d1b6-9e86-a00c-4fab8f744075', 'db853d51-4336-09b4-eae5-b1b058490092', 5, 'Quel compte humain du fichier d’empreintes résiste au dictionnaire fourni et correspond donc à la phrase de passe forte absente de cette liste ?', 'Commence par repérer quelles empreintes ne trouvent aucun candidat dans le dictionnaire, puis concentre-toi sur les comptes de personnes.', 'Identifiant de compte'),
  ('85eccba5-fb19-c193-0d3f-f055c895a279', 'db853d51-4336-09b4-eae5-b1b058490092', 6, 'Combien d’administrateurs de l’inventaire n’ont pas la double authentification activée ?', 'Filtre d’abord les lignes au privilège administrateur, puis regarde seulement la colonne de double authentification.', 'Un nombre entier'),
  ('f363d055-039d-b629-3dd8-62d846fd153c', 'db853d51-4336-09b4-eae5-b1b058490092', 7, 'À la date d’audit du 2026-03-09, quel est l’âge en jours du mot de passe le plus ancien de l’inventaire ?', 'Repère la date de changement la plus ancienne puis calcule la différence jusqu’au 9 mars 2026.', 'Un nombre entier de jours'),
  ('8bfee4dd-edd1-284f-bf4e-85f186125443', 'db853d51-4336-09b4-eae5-b1b058490092', 8, 'Quelle part des comptes de l’inventaire a la double authentification, arrondie à l’entier le plus proche ?', 'Compte les comptes avec « oui », divise par le total puis arrondis au pourcentage entier.', 'Un pourcentage entier, sans signe'),
  ('65539d03-3a09-744b-ba3a-f9bcf6997921', 'db853d51-4336-09b4-eae5-b1b058490092', 9, 'Calcul de méthode : une phrase de passe de 5 mots tirés dans une liste de 7776 mots donne environ combien de bits d’entropie, après arrondi ?', 'Le guide donne la formule : nombre de mots multiplié par log2 de la taille de la liste.', 'Un nombre entier'),
  ('b8c36a05-9e51-5a47-b227-4ae70e55fb05', 'db853d51-4336-09b4-eae5-b1b058490092', 10, 'Calcul de méthode : à un million d’essais par seconde, combien d’heures faut-il environ pour parcourir toutes les combinaisons possibles de 8 caractères pris parmi 62 caractères ?', 'Utilise la formule du guide : charset puissance longueur, puis conversion en heures avec un arrondi final.', 'Un nombre d’heures, sans signe'),
  ('aca45bc7-41c4-1677-3aa9-9d86f38f3716', 'db853d51-4336-09b4-eae5-b1b058490092', 11, 'Quelle heure UTC de dernière connexion apparaît pour le compte sans double authentification dont le mot de passe est le plus ancien dans l’inventaire ?', 'Filtre d’abord les comptes sans double authentification, puis garde celui dont la date de changement de mot de passe est la plus ancienne avant de lire sa dernière connexion.', 'HH:MM:SS'),
  ('33d20b6e-6ebe-4a2f-b6de-aa59cb42519a', 'db853d51-4336-09b4-eae5-b1b058490092', 12, 'Selon la règle du guide, quel compte faut-il désactiver ou isoler en premier parce qu’il cumule privilèges d’administration, absence de double authentification et mot de passe retrouvé ? Réponds par une lettre. a) archives-bot b) jm.tchoumi c) salle-03 d) pc-direction-local', 'Croise l’inventaire et l’extrait d’empreintes au lieu de te fier à une seule colonne.', 'Une seule lettre'),
  ('05c984c1-8cdc-2027-b99c-3014300546db', '75586b43-2547-2060-a233-aec440b878c0', 1, 'Combien de postes utilisent encore un système déjà hors support au jeudi 12 mars 2026 ?', 'Compare chaque système du parc avec sa date de fin de support officielle.', 'Un nombre entier'),
  ('99c43083-1631-fee3-1bb7-570038844d0b', '75586b43-2547-2060-a233-aec440b878c0', 2, 'Quel est le retard maximal de mise à jour observé dans le parc, en jours ?', 'Cherche la date de mise à jour la plus ancienne puis calcule l’écart.', 'Un nombre entier de jours'),
  ('33c2e48b-62a0-c7b6-614a-3f2d4f939e61', '75586b43-2547-2060-a233-aec440b878c0', 3, 'Combien de portables ne sont pas chiffrés au moment de l’audit ?', 'Ne compte que les lignes dont le type est portable et dont le chiffrement est absent.', 'Un nombre entier'),
  ('ace108e5-7e00-5bc9-8fee-bc3881ca4af1', '75586b43-2547-2060-a233-aec440b878c0', 4, 'Combien de postes ont des signatures antivirus âgées de plus de 7 jours ?', 'Calcule l’écart entre le 12 mars 2026 et la date des signatures.', 'Un nombre entier'),
  ('05db822d-fed0-138c-9c29-6228843e167c', '75586b43-2547-2060-a233-aec440b878c0', 5, 'Quelle est la plus longue série de jours consécutifs sans sauvegarde nocturne réussie ?', 'Lis le journal par date et repère la plus grande suite de lignes sans statut OK.', 'Un nombre entier de jours'),
  ('f2243281-f9d3-a780-7fea-f2ab133ea648', '75586b43-2547-2060-a233-aec440b878c0', 6, 'La règle 3-2-1 est-elle entièrement respectée d’après le tableau des copies fourni ?', 'Compte les copies, vérifie les supports différents puis cherche si un lieu est réellement hors site.', 'Réponse binaire : oui ou non'),
  ('cf911d3e-3108-129a-2103-e9266393bff6', '75586b43-2547-2060-a233-aec440b878c0', 7, 'Quelle condition manque pour respecter la règle 3-2-1 ? Réponds par une lettre. a) avoir trois copies b) avoir deux supports différents c) avoir une copie hors site', 'Le tableau des copies donne les supports et les lieux, à toi d’évaluer laquelle des trois conditions n’est pas remplie.', 'Une seule lettre'),
  ('2396bf3c-3734-a894-0c69-2371b800469a', '75586b43-2547-2060-a233-aec440b878c0', 8, 'À quelle date le dernier test de restauration réussi a-t-il eu lieu ?', 'Cherche la ligne RESTORE_OK du journal et relève sa date.', 'Date au format AAAA-MM-JJ'),
  ('c92bbd67-7663-91eb-f3f8-54b3d342b0b7', '75586b43-2547-2060-a233-aec440b878c0', 9, 'Combien de jours se sont écoulés entre ce test de restauration et la date d’audit ?', 'Utilise la date du test puis compare-la au jeudi 12 mars 2026.', 'Un nombre entier de jours'),
  ('4a7ca08c-94c7-fd1f-fd33-1ef5e53789b8', '75586b43-2547-2060-a233-aec440b878c0', 10, 'Quel poste obtient le score de pénalité le plus élevé avec la grille du guide ?', 'Additionne les pénalités pour chaque poste puis garde le total le plus grand.', 'Nom exact du poste'),
  ('3fb8148f-cf2a-6ecb-9189-9a68b8dfdfa1', '75586b43-2547-2060-a233-aec440b878c0', 11, 'Quel est le pourcentage de conformité global du parc avec la formule du guide ?', 'Compte les contrôles conformes sur l’ensemble des 72 contrôles attendus.', 'Pourcentage entier'),
  ('17ae1d81-5ab6-b31d-9450-f3ae4472785f', '75586b43-2547-2060-a233-aec440b878c0', 12, 'Combien de postes ont plus d’un administrateur local ?', 'Relève les lignes dont le nombre d’administrateurs dépasse un seul compte.', 'Un nombre entier'),
  ('3d166e85-5856-03fe-5268-6e20dd7f8783', '3fddeace-1761-3450-bd81-bfb403bb73a3', 1, 'Parmi les fichiers A, B et C, quel fichier est altéré par rapport au manifeste publié ? Réponds par une lettre.', 'Calcule l’empreinte réelle de chaque fichier puis compare-la au manifeste ligne par ligne.', 'Une seule lettre'),
  ('a2349150-5e32-86fc-a84d-825acc075808', '3fddeace-1761-3450-bd81-bfb403bb73a3', 2, 'Quels sont les 12 premiers caractères hexadécimaux de l’empreinte SHA-256 réelle du fichier altéré ?', 'Recalcule le condensat sur le fichier téléchargé, puis conserve seulement le début demandé.', '12 caractères hexadécimaux'),
  ('f16a5ea3-26c6-b642-c08b-68076c6e1af0', '3fddeace-1761-3450-bd81-bfb403bb73a3', 3, 'Combien d’octets contient le fichier altéré fourni dans le labo ?', 'Compte les octets du fichier tel qu’il est distribué, pas ceux du manifeste publié par l’éditeur.', 'Un nombre entier'),
  ('1d239708-0c5c-6961-e341-0039aade6caf', '3fddeace-1761-3450-bd81-bfb403bb73a3', 4, 'Quel texte obtiens-tu en décodant le message Base64 du journal de messages ?', 'Le Base64 est un encodage : il faut le décoder tel quel, sans modifier les caractères.', 'Le texte décodé'),
  ('256b969c-ef74-80c2-78d1-5fdd1e2ee76f', '3fddeace-1761-3450-bd81-bfb403bb73a3', 5, 'Quel texte obtiens-tu en décodant la chaîne hexadécimale du journal de messages ?', 'Deux caractères hexadécimaux représentent un octet. Convertis-les puis lis le texte en UTF-8.', 'Le texte décodé'),
  ('13602d8b-35ce-ea18-2fbd-078371619abb', '3fddeace-1761-3450-bd81-bfb403bb73a3', 6, 'Quel texte obtiens-tu si tu déchiffres le message de César du journal avec le décalage 7 ?', 'Le décalage est connu : ramène chaque lettre en arrière dans l’alphabet du même nombre de positions.', 'Le texte déchiffré'),
  ('d951ab19-f552-e826-35b0-56988846eaa0', '3fddeace-1761-3450-bd81-bfb403bb73a3', 7, 'Dans le journal de messages, quel est l’algorithme le plus probable pour l’empreinte de 32 caractères hexadécimaux ? Réponds par une lettre. a) md5 b) sha1 c) sha256 d) bcrypt', 'Reconnais la famille par sa longueur habituelle en hexadécimal.', 'Une seule lettre'),
  ('e349af93-5f97-b35c-c270-5a8a47ad1bec', '3fddeace-1761-3450-bd81-bfb403bb73a3', 8, 'Si tu recalcules SHA-256 sur la chaîne « certificat », obtiens-tu exactement la valeur indiquée à la ligne empreinte_64 du carnet ?', 'Recalcule l’empreinte de la chaîne exacte, sans retour à la ligne final (sous bash : printf ou echo -n), puis compare-la caractère par caractère à la valeur du carnet.', 'oui ou non'),
  ('4068559e-71e6-d684-629e-7ec73ae6bad6', '3fddeace-1761-3450-bd81-bfb403bb73a3', 9, 'Quelle est la date de fin de validité du certificat principal du site, au format AAAA-MM-JJ ?', 'Lis la ligne Not After du premier certificat puis remets-la au format demandé.', 'AAAA-MM-JJ'),
  ('6a7c9b7c-81d9-f1f3-f7db-9288bba801ca', '3fddeace-1761-3450-bd81-bfb403bb73a3', 10, 'Au 16 mars 2026, combien de jours calendaires entiers reste-t-il avant cette date de fin de validité ?', 'Calcule l’écart entre les deux dates AAAA-MM-JJ, sans compter l’heure précise du champ Not After.', 'Un nombre entier de jours'),
  ('f8778da8-0688-3b7a-4d3b-c39c0c957527', '3fddeace-1761-3450-bd81-bfb403bb73a3', 11, 'Le certificat principal couvre-t-il aussi le nom soleil.example sans www ?', 'Ne te fie pas au seul CN : cherche surtout les noms présents dans la section SAN.', 'oui ou non'),
  ('4d8dd3c0-8899-2682-c609-85a7cff6d6fa', '3fddeace-1761-3450-bd81-bfb403bb73a3', 12, 'Quelle est la taille de la clé publique RSA du certificat principal, en bits ?', 'Lis la ligne Public-Key du premier certificat.', 'Un nombre entier'),
  ('4025c737-8664-6256-2566-28d348271c25', '3fddeace-1761-3450-bd81-bfb403bb73a3', 13, 'Le second certificat du fichier est-il encore valide le 16 mars 2026 ?', 'Compare la date de référence à sa ligne Not After.', 'oui ou non'),
  ('eacde095-4eb2-16de-9fff-57484ebc6539', 'abd6404e-6914-ba7f-6a04-a0faae4f4122', 1, 'Pour INC-01, quelle propriété principale est touchée en premier ?', 'Applique la règle du guide : cherche d’abord ce qui est atteint directement avant les effets secondaires.', 'Une lettre : c, i ou d'),
  ('92fdec1f-6ca9-c753-6cc3-77da5c8a3deb', 'abd6404e-6914-ba7f-6a04-a0faae4f4122', 2, 'Pour INC-02, quelle propriété principale est touchée en premier ?', 'Applique la règle du guide : cherche d’abord ce qui est atteint directement avant les effets secondaires.', 'Une lettre : c, i ou d'),
  ('eb8ab581-5f86-ec40-6ee5-ac845682cd44', 'abd6404e-6914-ba7f-6a04-a0faae4f4122', 3, 'Pour INC-03, quelle propriété principale est touchée en premier ?', 'Applique la règle du guide : cherche d’abord ce qui est atteint directement avant les effets secondaires.', 'Une lettre : c, i ou d'),
  ('364a4d98-28c2-4d25-158e-9bd2f1820ab0', 'abd6404e-6914-ba7f-6a04-a0faae4f4122', 4, 'Quel score obtient le scénario SC-07 avec la formule du guide ?', 'Multiplie simplement la vraisemblance par l’impact indiqués dans la ligne.', 'Un nombre entier'),
  ('c4214d6d-eec1-cac7-1e7b-933495971c22', 'abd6404e-6914-ba7f-6a04-a0faae4f4122', 5, 'Quel identifiant porte le scénario au score le plus élevé du registre ?', 'Calcule les scores puis cherche le maximum unique.', 'Identifiant de scénario'),
  ('033a6b9b-0b9b-536d-0aca-59ff95c5cb2b', 'abd6404e-6914-ba7f-6a04-a0faae4f4122', 6, 'Combien de scénarios sont de niveau critique selon les seuils du guide ?', 'Le niveau critique couvre les scores de 12 à 16 inclus.', 'Un nombre entier'),
  ('85bd6f51-ad6a-e2c1-deb8-72e28ec03fb4', 'abd6404e-6914-ba7f-6a04-a0faae4f4122', 7, 'Quel est le score résiduel de SC-10 si la nouvelle mesure fait passer la vraisemblance à 1 ?', 'L’impact ne change pas, seule la vraisemblance est remplacée.', 'Un nombre entier'),
  ('2e89e895-f552-9953-3f86-14b03d256c04', 'abd6404e-6914-ba7f-6a04-a0faae4f4122', 8, 'Quel actif cumule la somme de scores la plus élevée quand on additionne ses scénarios ?', 'Additionne les scores par identifiant d’actif avant de comparer les totaux.', 'Identifiant d’actif'),
  ('e1d2f17a-2b95-6392-14b1-5408ab2ecd87', 'abd6404e-6914-ba7f-6a04-a0faae4f4122', 9, 'Combien d’actifs contiennent des données personnelles dans l’inventaire ?', 'Compte uniquement les lignes marquées oui dans la colonne dédiée.', 'Un nombre entier'),
  ('5bed7b8c-5526-6412-348f-68846b248516', 'abd6404e-6914-ba7f-6a04-a0faae4f4122', 10, 'Quel traitement convient à SC-11 en appliquant strictement la règle du guide ? Réponds par une lettre. a) réduire b) éviter c) transférer d) accepter', 'Commence par déterminer son niveau avant de choisir le traitement associé.', 'Une seule lettre'),
  ('d479db81-a794-5e5b-3d81-fde49defea8d', 'abd6404e-6914-ba7f-6a04-a0faae4f4122', 11, 'Quel compte détient sur le dossier de comptabilité des droits d’écriture ou de suppression que son rôle n’exige pas ? Une seule personne est concernée.', 'Compare le rôle métier de chaque personne avec ses droits réels d’écriture et de suppression.', 'Adresse de messagerie complète'),
  ('2d05a517-f563-948b-7047-c0d91cc3358e', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 1, 'À quelle heure UTC apparaît la première connexion réussie de l’attaquant sur le compte touché ?', 'Isole les lignes du compte concerné puis garde le premier succès depuis l’adresse inhabituelle.', 'Heure UTC au format HH:MM'),
  ('54661267-c85b-3663-7eca-605794619ada', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 2, 'Quelle adresse IP correspond à cette première connexion réussie anormale ?', 'Relève l’adresse de la même ligne que le premier succès identifié.', 'Adresse IPv4'),
  ('b95e2d22-a41f-a614-a162-2f1896b40682', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 3, 'Dans quel pays fictif cette adresse est-elle géolocalisée selon la table fournie ?', 'Croise l’adresse IP avec la table de géolocalisation, sans interprétation supplémentaire.', 'Nom du pays'),
  ('0d8e6be8-7bb0-271b-39dc-3282eda96d4c', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 4, 'Combien d’échecs précèdent ce premier succès de l’attaquant ?', 'Compte seulement les lignes d’échec du même compte et de la même adresse avant le succès.', 'Un nombre entier'),
  ('e329573f-81ee-18a5-c4ec-9fa63e38a930', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 5, 'La double authentification était-elle active sur ce compte au moment de l’incident ?', 'Regarde la méthode utilisée par les connexions réussies du compte concerné.', 'Réponse binaire : oui ou non'),
  ('2baef09b-13c8-0457-04a9-a58949a47102', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 6, 'Quelle adresse externe reçoit le transfert automatique créé dans la boîte compromise ?', 'Lis le détail de l’événement de création de règle dans le journal d’audit.', 'Adresse de messagerie complète'),
  ('d23fed39-f418-8d96-91ab-46a9aa1e3d9d', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 7, 'Combien de messages l’attaquant a-t-il supprimés selon le journal d’audit ?', 'Cherche l’action de suppression puis relève la quantité indiquée.', 'Un nombre entier'),
  ('0a87dccd-f250-bd99-076b-5e14312adfbc', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 8, 'Combien de téléchargements de pièces jointes sont enregistrés pour l’attaquant ?', 'Cherche l’action qui mentionne explicitement les pièces jointes.', 'Un nombre entier'),
  ('23d3e66c-e28b-3045-28da-2aed7d0850a3', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 9, 'À quelle heure UTC Yao réinitialise-t-il son mot de passe après le signalement ?', 'Repère l’événement de réinitialisation du mot de passe dans la boîte.', 'Heure UTC au format HH:MM'),
  ('ef12b4d7-49d7-fb1c-a29b-e8cd9a627a38', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 10, 'Quelle est la durée d’exposition entre la première connexion réussie de l’attaquant et la suppression de la règle de transfert, en minutes entières arrondies à la minute la plus proche ?', 'Calcule l’écart entre ces deux horodatages complets, puis convertis-le en minutes avant d’arrondir.', 'Un nombre entier de minutes'),
  ('4827bdbc-010f-691f-b2fd-26a953d731b2', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 11, 'Quelle est la date et l’heure limites de notification à l’autorité, calculées 72 heures après la prise de connaissance ?', 'La prise de connaissance officielle est le signalement de 09:40 UTC le 25 mars.', 'AAAA-MM-JJ HH:MM UTC'),
  ('2d218ce2-701f-e52e-d6cd-2a388d95da49', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 12, 'Une notification est-elle requise au vu des pièces jointes d’adhérents présentes dans la boîte ?', 'Applique la règle du guide sur l’exposition de données personnelles.', 'Réponse binaire : oui ou non'),
  ('a6a29087-fc74-32b5-52d8-2987fe17d949', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 13, 'Quelle est la première mesure de confinement correcte ? Réponds par une lettre. a) révoquer les sessions actives puis réinitialiser le mot de passe b) supprimer le compte immédiatement c) éteindre le serveur de messagerie d) attendre un nouveau message de l’attaquant', 'Choisis l’action qui coupe l’accès de l’attaquant tout de suite sans détruire les preuves utiles.', 'Une seule lettre'),
  ('e5065804-8baf-8c0f-7f9e-1b441c9f7941', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 14, 'Combien d’adresses IP distinctes l’attaquant utilise-t-il avec succès dans cette chronologie ?', 'Compte uniquement les adresses qui apparaissent sur des succès anormaux du compte compromis.', 'Un nombre entier'),
  ('625ac682-d4f6-b0b8-ab0b-f3a4f64d6c4b', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 15, 'Quel nom de fichier parmi les pièces fournies prouve l’accès à la boîte elle-même ?', 'Cherche la pièce qui journalise les actions internes à la boîte, comme les règles et les téléchargements, plutôt que les seules authentifications.', 'Nom exact du fichier'),
  ('a53182be-393b-0029-290e-9c19b592aa5b', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 1, 'Quel est le score pondéré du domaine sauvegardes dans la grille d’audit, arrondi à l’entier le plus proche (0,5 vers le haut) ?', 'Applique la formule du guide uniquement aux lignes du domaine demandé.', 'Pourcentage entier'),
  ('99172c3c-3696-aa99-bab3-a931464dd512', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 2, 'Quel est le score global du Centre Numérique Soleil, arrondi à l’entier le plus proche (0,5 vers le haut) ?', 'Additionne tous les points pondérés puis divise par la somme de tous les poids.', 'Pourcentage entier'),
  ('356020e4-1929-7cff-9372-dd8c1c6dee92', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 3, 'Quel domaine obtient le score le plus faible dans cette grille ? Réponds par une lettre. a) authentification b) postes c) sauvegardes d) réseau et wi-fi e) données personnelles f) gestion des incidents', 'Compare les scores pondérés domaine par domaine après calcul.', 'Une seule lettre'),
  ('71675368-1d27-082f-9755-f070b0a22b1e', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 4, 'Combien de contrôles sont totalement non conformes dans la grille ?', 'Compte uniquement les lignes marquées non, sans inclure les statuts partiels.', 'Un nombre entier'),
  ('370f1c7e-e9d2-1900-0321-c050c3cd9110', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 5, 'Quel identifiant d’action arrive en priorité n°1 dans le fichier de risques ?', 'Trie d’abord par score de risque décroissant, puis par effort croissant.', 'Identifiant d’action'),
  ('b0f56d80-0792-9f7f-3c74-94d4fff39bb4', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 6, 'Combien de gains rapides le projet contient-il ?', 'Un gain rapide combine un effort de 1 et un risque au moins égal à 6.', 'Un nombre entier'),
  ('f83b43f4-106d-34e2-024a-1c3220c74b08', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 7, 'Quel âge en jours a la dernière sauvegarde réussie à la date d’audit du 31 mars 2026 ? Compte en jours calendaires : l’écart entre les deux dates, sans tenir compte de l’heure.', 'Lis le journal des sauvegardes du projet, garde la dernière ligne SUCCESS puis compare sa date au 31 mars 2026.', 'Un nombre entier de jours'),
  ('29d11aed-2387-2f81-559e-aebf737ab0e3', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 8, 'Quel est le taux de couverture de la double authentification parmi les 6 salariés, arrondi à l’entier le plus proche (0,5 vers le haut) ?', 'Compte dans le relevé d’accès MFA les salariés marqués « oui », puis divise par le total des 6 lignes.', 'Pourcentage entier'),
  ('324fb2ee-b5ac-884a-4464-69d432bd325f', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 9, 'En recoupant l’inventaire des postes du projet et la table de fin de support fournie dans ce même projet, combien de postes sont encore sur un système hors support lors de la visite d’audit ?', 'Compare la version de chaque poste à sa date de fin de support au 31 mars 2026.', 'Un nombre entier'),
  ('d46772f2-ba54-cf8c-be83-b31c9b1114f1', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 10, 'Combien de jours restent-ils avant l’expiration du certificat du site web à la date du 31 mars 2026 ?', 'Lis la date d’expiration du certificat dans les notes puis calcule l’écart.', 'Un nombre entier de jours'),
  ('1cf8975c-449e-b97c-c8a2-6de260bf2dc3', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 11, 'L’algorithme d’intégrité utilisé pour les sauvegardes est-il acceptable pour un audit actuel ?', 'Croise le journal d’intégrité des sauvegardes avec la règle indiquée dans la grille d’audit.', 'Réponse binaire : oui ou non'),
  ('d20bef55-1cf5-fbc0-be90-70ff7acefcbe', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 12, 'Quel algorithme apparaît dans le journal d’intégrité des sauvegardes du projet ?', 'Lis la colonne de l’algorithme dans le fichier d’intégrité des sauvegardes.', 'Nom d’algorithme en minuscules'),
  ('ddfd69b7-9fb3-e154-e4f8-7268a5b88049', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 13, 'Un registre des traitements existe-t-il au moment de la visite ?', 'Vérifie l’inventaire documentaire de conformité et lis l’état indiqué pour le registre des traitements.', 'Réponse binaire : oui ou non'),
  ('94e6ffe2-b5c5-b499-baaf-44578ab1c513', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 14, 'Quel est le délai réglementaire de notification d’une violation de données, en heures ?', 'Le guide rappelle ce délai comme une règle fixe, pas comme un calcul variable.', 'Un nombre entier d’heures'),
  ('2b56ed85-51eb-d787-f2bc-1bdeb86d276d', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 15, 'Combien de personnes dois-tu sensibiliser en priorité après la simulation de phishing ?', 'Compte dans le relevé de simulation les personnes marquées comme ayant cliqué.', 'Un nombre entier')
insert into private.lab_task_keys (task_id, accepted, explanation) values
  ('3cfe871f-ac28-fc55-31f1-66b5eeea20b6', array['banque-horzion.example']::text[], 'Le nom affiché essaie d’inspirer confiance, mais l’adresse réelle révèle le piège. Le domaine banque-horzion.example imite la banque légitime avec une légère faute, ce qui est un classique de l’hameçonnage. La bonne méthode consiste toujours à extraire l’adresse complète avant de juger le message.'),
  ('3995bc76-a910-fda9-f60b-fc3ccda652f4', array['paiement-horizon.test']::text[], 'Le Return-Path est le domaine technique qui sert au rebond. Ici, paiement-horizon.test ne correspond ni au nom affiché ni au domaine légitime attendu, ce qui renforce fortement le soupçon. Comparer From, Reply-To et Return-Path aide à voir les incohérences cachées derrière une belle mise en forme.'),
  ('2fced884-af70-5593-6669-49ff4a238ac8', array['198.51.100.77']::text[], 'Les lignes Received se lisent du bas vers le haut pour reconstruire le trajet. L’adresse 198.51.100.77 est la première source externe visible avant les relais de Soleil. Cette lecture permet de distinguer le point de départ d’un message des serveurs qui ne font que le transmettre.'),
  ('0a0fc54c-78a2-0146-1dca-708b348e1e0c', array['fail']::text[], 'Le résultat SPF vaut fail. Cela signifie que le serveur expéditeur observé n’est pas autorisé à envoyer du courrier pour ce domaine. Un SPF en échec ne suffit pas à lui seul pour conclure, mais combiné au reste il devient un signal d’alerte solide.'),
  ('8d9f1b28-f3ac-918f-0d50-d702b2e1f1d5', array['horizon-securite.test']::text[], 'Le texte visible imite la banque, mais l’hôte réel se termine par horizon-securite.test. C’est donc ce domaine qui contrôle réellement la page visée. Lire un domaine de droite à gauche évite de se faire piéger par des sous-domaines trompeurs placés au début.'),
  ('e50f5008-dc26-a5f9-a308-86372d119ea3', array['exe']::text[], 'La dernière extension décide du type de fichier réellement lancé. Ici, exe montre qu’il s’agit d’un exécutable déguisé derrière un mot rassurant. Les doubles extensions servent précisément à faire croire à un document banal alors que le système verra tout autre chose.'),
  ('da286c3f-44c1-b30a-0b93-c849cc2a2189', array['24', '24 heures', '24h']::text[], 'Le message impose un délai de 24 heures avant la suspension annoncée. Relever ce délai est utile, car c’est un signe classique de pression artificielle : l’attaquant veut faire agir vite avant que la victime n’ait le temps de vérifier.'),
  ('6b86aab3-f471-9d7e-0b5a-db99415940a4', array['a']::text[], 'L’élément à ne jamais transmettre est le code de validation. Ce code sert justement à prouver que tu es la bonne personne ou à valider une opération. Le donner à quelqu’un, même s’il se présente comme un agent d’aide, revient souvent à lui remettre le contrôle.'),
  ('9dbb1074-c473-a642-74b1-21bcbabefef4', array['b']::text[], 'La bonne réponse est lettre b. Quand un mot de passe a été saisi sur un faux site, il faut agir tout de suite sur le vrai service, changer le secret compromis puis activer la double authentification si elle existe. Attendre, discuter avec l’attaquant ou diffuser le message ne protège pas le compte.'),
  ('94655ba1-3833-f9c2-d82c-9cc6efd2c78f', array['8']::text[], 'Le guide propose dix signaux possibles, mais le courriel n’en présente que 8. Les deux autres servent de faux amis pour t’obliger à vérifier chaque point au lieu de supposer que toute liste du guide s’applique automatiquement au message étudié.'),
  ('8a9d183d-028a-f748-63b4-46ad28ed7bb4', array['routeur-soleil-2026']::text[], 'L’empreinte de jm.tchoumi correspond au mot de passe fictif routeur-soleil-2026. Comme le stockage est sans sel, le même calcul sur le dictionnaire suffit à retrouver la valeur. Cet exercice montre pourquoi un hachage rapide et sans sel protège mal contre une attaque par dictionnaire.'),
  ('377f7dec-d49c-490a-fe05-806850a33103', array['journal-cns-09']::text[], 'Le mot de passe trouvé pour yao.kouassi est journal-cns-09. Ici encore, la faiblesse ne vient pas d’une faille du calcul SHA-256 lui-même, mais du fait qu’un secret prévisible et non salé se retrouve vite dans un dictionnaire réaliste.'),
  ('b9e4be1c-cf1d-e962-ec70-3c1568fa65cf', array['atelier-salle-03']::text[], 'Le compte salle-03 utilise atelier-salle-03. Cette valeur réapparaît ailleurs dans l’extrait, ce qui prouve une réutilisation. Dès qu’un mot de passe est craqué une fois, tous les comptes qui partagent la même empreinte tombent en même temps.'),
  ('ed2ef513-097b-8d7a-410c-264e749559af', array['2']::text[], 'Deux comptes partagent exactement la même empreinte, donc le même mot de passe. La bonne réponse est 2. Une réutilisation augmente fortement l’impact d’une compromission, car un seul craquage ouvre plusieurs accès.'),
  ('f1ed15f5-d1b6-9e86-a00c-4fab8f744075', array['mariam.sow']::text[], 'Le compte humain qui résiste au dictionnaire est mariam.sow. Les autres comptes non retrouvés sont techniques ou locaux, alors que celui-ci appartient à une personne et conserve une empreinte non corrélée à la liste fournie. C’est le bon exemple d’un secret plus robuste face à une attaque simple.'),
  ('85eccba5-fb19-c193-0d3f-f055c895a279', array['1']::text[], 'L’inventaire montre 1 administrateur sans double authentification. C’est critique, car un mot de passe seul ne suffit alors plus à bloquer une réutilisation ou un vol d’identifiants. Les privilèges élevés doivent être protégés en priorité.'),
  ('f363d055-039d-b629-3dd8-62d846fd153c', array['295']::text[], 'Le mot de passe le plus ancien a 295 jours. Mesurer cette ancienneté aide à voir les comptes oubliés, souvent moins suivis et donc plus exposés. Un secret très ancien n’est pas forcément compromis, mais il mérite une attention immédiate.'),
  ('8bfee4dd-edd1-284f-bf4e-85f186125443', array['57']::text[], 'La couverture de la double authentification est de 57 pour cent après arrondi. Ce calcul transforme une impression vague en indicateur utile pour piloter une amélioration. Plus ce taux monte, moins un mot de passe volé suffit à compromettre un compte.'),
  ('65539d03-3a09-744b-ba3a-f9bcf6997921', array['65']::text[], 'Avec 5 mots et une liste de 7776 possibilités par mot, on obtient environ 65 bits après arrondi. Cette estimation rappelle qu’une phrase de passe longue et bien choisie résiste mieux qu’un mot court, même si elle reste mémorisable.'),
  ('b8c36a05-9e51-5a47-b227-4ae70e55fb05', array['60650', '60 650']::text[], 'Le bon ordre de grandeur est 60650 heures. Ce chiffre montre que le brute force pur devient vite coûteux, mais qu’il reste bien plus rapide quand les attaquants disposent d’un dictionnaire ciblé ou d’un mot de passe déjà réutilisé ailleurs.'),
  ('aca45bc7-41c4-1677-3aa9-9d86f38f3716', array['11:15:42']::text[], 'Le compte sans double authentification au mot de passe le plus ancien est celui qui cumule l’âge maximal dans cette sous-population. Sa dernière connexion UTC vaut 11:15:42, ce qui oblige à croiser deux colonnes de l’inventaire avant de relever l’heure.'),
  ('33d20b6e-6ebe-4a2f-b6de-aa59cb42519a', array['b']::text[], 'Le compte à traiter en premier est jm.tchoumi. Il cumule trois facteurs de risque : privilèges élevés, absence de double authentification et secret récupérable dans le dictionnaire. C’est exactement le type de compte qu’un attaquant réutiliserait aussitôt.'),
  ('05c984c1-8cdc-2027-b99c-3014300546db', array['4']::text[], 'Un système compte comme hors support si sa date de fin de support est antérieure au 12 mars 2026. En recoupant les 12 lignes de l’inventaire avec le tableau des versions, on en trouve 4.'),
  ('99c43083-1631-fee3-1bb7-570038844d0b', array['62']::text[], 'Le retard maximal correspond à la plus vieille date de dernière mise à jour visible dans l’inventaire. Une fois comparée à la date d’audit, elle donne 62 jours de retard.'),
  ('33c2e48b-62a0-c7b6-614a-3f2d4f939e61', array['2']::text[], 'Le critère demandé ne porte que sur les portables. En filtrant ces lignes puis en regardant l’état du disque, on obtient 2 portables sans chiffrement.'),
  ('ace108e5-7e00-5bc9-8fee-bc3881ca4af1', array['8']::text[], 'Le guide fixe un seuil simple : au-delà de 7 jours, le retard devient non conforme. En recalculant cet écart poste par poste, on arrive à 8 postes trop anciens.'),
  ('05db822d-fed0-138c-9c29-6228843e167c', array['3']::text[], 'Le journal contient des jours réussis, des échecs et un test de restauration séparé. En ne comptant que les nuits sans succès et en gardant la série la plus longue, on trouve 3 jours.'),
  ('f2243281-f9d3-a780-7fea-f2ab133ea648', array['non', 'no']::text[], 'La note confirme qu’il existe bien trois copies et deux supports différents, mais aucune copie hors site. Comme une seule condition manque, la règle 3-2-1 n’est pas entièrement respectée.'),
  ('cf911d3e-3108-129a-2103-e9266393bff6', array['c']::text[], 'La condition manquante est la copie hors site. Le document la repère par une lettre unique dans la liste des trois critères, ce qui permet de répondre sans ambiguïté.'),
  ('2396bf3c-3734-a894-0c69-2371b800469a', array['2026-03-05', '05/03/2026', '05-03-2026']::text[], 'Le test de restauration réussi n’est mentionné qu’une fois dans le journal. Cette ligne porte la date 2026-03-05, preuve que l’équipe a vérifié au moins une lecture d’archive.'),
  ('c92bbd67-7663-91eb-f3f8-54b3d342b0b7', array['7']::text[], 'Le test date du 2026-03-05. Entre cette date et le 12 mars 2026, il s’est écoulé 7 jours, ce qui mesure la fraîcheur du dernier essai réel.'),
  ('4a7ca08c-94c7-fd1f-fd33-1ef5e53789b8', array['pc-compta']::text[], 'La grille du guide additionne six types de pénalités. Après calcul sur chaque ligne de l’inventaire, PC-COMPTA cumule le total le plus élevé et devient la priorité de correction.'),
  ('3fb8148f-cf2a-6ecb-9189-9a68b8dfdfa1', array['58', '58%', '58 %']::text[], 'Le guide fixe 6 contrôles par poste, donc 72 contrôles pour 12 machines. En comptant seulement ceux qui passent puis en arrondissant, on obtient 58 % de conformité globale.'),
  ('17ae1d81-5ab6-b31d-9450-f3ae4472785f', array['6']::text[], 'Le principe de moindre privilège recommande de limiter les droits d’administration. En relisant la colonne des administrateurs locaux, 6 postes dépassent ce seuil.'),
  ('3d166e85-5856-03fe-5268-6e20dd7f8783', array['b']::text[], 'Le seul fichier dont l’empreinte réelle ne correspond pas au manifeste est lettre b. Une vérification d’intégrité sérieuse part toujours des octets réellement reçus, pas d’une simple apparence ou d’un nom de fichier familier.'),
  ('a2349150-5e32-86fc-a84d-825acc075808', array['d5093f887eff']::text[], 'Le préfixe attendu est d5093f887eff. Relever seulement les premiers caractères d’une empreinte n’est pas suffisant pour une vraie vérification de sécurité, mais c’est un bon exercice pour montrer que tu sais recalculer la valeur correcte à partir du bon fichier.'),
  ('f16a5ea3-26c6-b642-c08b-68076c6e1af0', array['79']::text[], 'Le fichier altéré contient 79 octets. Même une variation minime du contenu, parfois un seul caractère, suffit à produire une nouvelle empreinte SHA-256. C’est exactement ce qu’on exploite pour vérifier l’intégrité d’un téléchargement.'),
  ('1d239708-0c5c-6961-e341-0039aade6caf', array['change le mot de passe ce soir']::text[], 'Le message Base64 se décode en « change le mot de passe ce soir ». Ce point est important : le Base64 ne chiffre rien. Il ne fait que représenter des octets en texte ASCII transportable. Toute personne qui voit la chaîne et sait la décoder retrouve immédiatement le message d’origine.'),
  ('256b969c-ef74-80c2-78d1-5fdd1e2ee76f', array['sauvegarde hors ligne ok']::text[], 'La chaîne hexadécimale correspond au texte « sauvegarde hors ligne ok ». Comme pour le Base64, il s’agit d’un encodage, pas d’un mécanisme de confidentialité. Reconnaître ce format t’évite de prendre un simple habillage pour une protection cryptographique réelle.'),
  ('13602d8b-35ce-ea18-2fbd-078371619abb', array['verifie le hash avant installation']::text[], 'Le message de César redonne « verifie le hash avant installation ». Ce type de chiffrement historique se casse facilement dès que le décalage est connu ou qu’on teste les 25 possibilités. L’exercice sert surtout à distinguer un chiffrement jouet d’un vrai chiffrement moderne.'),
  ('d951ab19-f552-e826-35b0-56988846eaa0', array['a']::text[], 'Une empreinte de 32 caractères hexadécimaux correspond classiquement à md5. Reconnaître cette longueur te permet d’identifier rapidement le type de condensat manipulé et d’éviter de confondre plusieurs familles de hachage.'),
  ('e349af93-5f97-b35c-c270-5a8a47ad1bec', array['oui', 'yes']::text[], 'La ligne empreinte_64 du carnet correspond bien au SHA-256 de la chaîne « certificat ». Cette vérification repose sur un recalcul réel puis sur une comparaison complète, pas sur une simple reconnaissance de longueur.'),
  ('4068559e-71e6-d684-629e-7ec73ae6bad6', array['2026-08-12']::text[], 'La date de fin de validité du certificat principal est 2026-08-12. Lire ce champ fait partie des vérifications élémentaires d’un site : un certificat peut être bien signé, mais rester inutilisable s’il est hors période de validité.'),
  ('6a7c9b7c-81d9-f1f3-f7db-9288bba801ca', array['149']::text[], 'En comptant les jours calendaires entiers entre le 16 mars 2026 et la date AAAA-MM-JJ d’expiration, il reste 149 jours. Cette précision évite de mélanger un calcul sur des dates et un calcul sur des horodatages complets, puis aide à anticiper un renouvellement avant panne.'),
  ('f8778da8-0688-3b7a-4d3b-c39c0c957527', array['non', 'no']::text[], 'La bonne réponse est non. Les SAN listent www.soleil.example et un autre nom, mais pas soleil.example sans préfixe. Un certificat ne couvre donc pas automatiquement la version nue du domaine si elle n’apparaît nulle part dans ces champs.'),
  ('4d8dd3c0-8899-2682-c609-85a7cff6d6fa', array['2048']::text[], 'La clé publique du certificat principal fait 2048 bits. Lire cette taille permet de vérifier que le certificat respecte encore un niveau de sécurité courant et qu’il n’utilise pas une clé trop courte pour un usage moderne.'),
  ('4025c737-8664-6256-2566-28d348271c25', array['non', 'no']::text[], 'La bonne réponse est non. Le second certificat expire avant le 16 mars 2026, il n’est donc plus valide à cette date. Vérifier la période de validité reste indispensable, même si l’algorithme de signature et la taille de clé semblent corrects.'),
  ('eacde095-4eb2-16de-9fff-57484ebc6539', array['c']::text[], 'Dans INC-01, quelqu’un lit une information qu’il ne devait pas consulter. La donnée n’est ni modifiée ni rendue indisponible : c’est donc d’abord une atteinte à la confidentialité.'),
  ('92fdec1f-6ca9-c753-6cc3-77da5c8a3deb', array['i']::text[], 'La phrase décrit un contenu altéré, puisque des montants ont été remplacés sans validation. La propriété attaquée est donc l’intégrité des données comptables.'),
  ('eb8ab581-5f86-ec40-6ee5-ac845682cd44', array['d']::text[], 'Quand la box redémarre, les personnes ne peuvent plus utiliser le service pendant un temps donné. Le dommage principal concerne donc la disponibilité.'),
  ('364a4d98-28c2-4d25-158e-9bd2f1820ab0', array['9']::text[], 'Le guide demande un produit simple. Pour SC-07, la vraisemblance et l’impact mènent à un score de 9, sans autre pondération cachée.'),
  ('c4214d6d-eec1-cac7-1e7b-933495971c22', array['sc-08']::text[], 'Une fois tous les produits calculés, un seul scénario reste au-dessus des autres. Son identifiant est SC-08, ce qui en fait la priorité brute du registre.'),
  ('033a6b9b-0b9b-536d-0aca-59ff95c5cb2b', array['3']::text[], 'Le guide borne clairement le niveau critique. En ne gardant que les scénarios dont le score tombe dans cette tranche, on en compte 3.'),
  ('85bd6f51-ad6a-e2c1-deb8-72e28ec03fb4', array['4']::text[], 'Le score résiduel se recalcule avec la même formule, mais la nouvelle vraisemblance vaut 1. Le produit redescend alors à 4, ce qui montre l’effet attendu de la mesure.'),
  ('2e89e895-f552-9953-3f86-14b03d256c04', array['act-02']::text[], 'Certains actifs portent plusieurs scénarios à la fois. Après addition des scores par actif, ACT-02 ressort avec le total le plus élevé et concentre donc le plus de risque cumulé.'),
  ('e1d2f17a-2b95-6392-14b1-5408ab2ecd87', array['6']::text[], 'La colonne « données personnelles » permet de compter sans interprétation libre. En recensant uniquement les « oui », on obtient 6 actifs concernés.'),
  ('5bed7b8c-5526-6412-348f-68846b248516', array['d']::text[], 'SC-11 se situe dans le niveau faible après calcul. Le guide associe ce niveau au traitement « accepter », car le coût d’une action lourde dépasserait ici le bénéfice attendu.'),
  ('d479db81-a794-5e5b-3d81-fde49defea8d', array['fatima.bello@soleil.example']::text[], 'Le principe du moindre privilège veut que chaque personne ne garde que les droits strictement nécessaires à son rôle. Ici, fatima.bello@soleil.example possède des droits de modification qui ne correspondent pas à sa mission.'),
  ('2d05a517-f563-948b-7047-c0d91cc3358e', array['06:18', '6:18']::text[], 'Les trois premières tentatives anormales échouent, puis un succès apparaît à 06:18 UTC. Cette heure marque l’entrée effective de l’attaquant sur le compte compromis.'),
  ('54661267-c85b-3663-7eca-605794619ada', array['198.51.100.77']::text[], 'L’adresse IP de la première authentification malveillante réussie est 198.51.100.77. C’est elle qu’il faut suivre ensuite dans le reste des traces et bloquer en priorité.'),
  ('b95e2d22-a41f-a614-a162-2f1896b40682', array['noria']::text[], 'La table de géolocalisation associe 198.51.100.77 au pays fictif noria. Le journal de connexions et la table suffisent donc à documenter l’origine déclarée.'),
  ('0d8e6be8-7bb0-271b-39dc-3282eda96d4c', array['3']::text[], 'Avant le premier succès, on observe 3 tentatives ratées depuis la même adresse. Ce motif montre une phase d’essais avant l’accès effectif.'),
  ('e329573f-81ee-18a5-c4ec-9fa63e38a930', array['non', 'no']::text[], 'Le guide indique que la double authentification est absente si la méthode affichée reste simplement « motdepasse ». C’est bien le cas ici, ce qui explique que le mot de passe volé ait suffi.'),
  ('2baef09b-13c8-0457-04a9-a58949a47102', array['archives-finance@courrier.invalid']::text[], 'Le journal d’audit mentionne explicitement la destination de la règle de transfert. Cette destination est archives-finance@courrier.invalid, preuve d’une exfiltration automatisée des messages entrants.'),
  ('d23fed39-f418-8d96-91ab-46a9aa1e3d9d', array['14']::text[], 'Le journal d’audit de la boîte porte une action « messages_supprimes » accompagnée d’une quantité. Cette quantité vaut 14, ce qui documente la volonté de masquer des traces.'),
  ('0a87dccd-f250-bd99-076b-5e14312adfbc', array['6']::text[], 'Une ligne du journal d’audit mentionne des téléchargements de pièces jointes avec une quantité chiffrée. Cette quantité est 6, ce qui renforce le risque pour les données personnelles.'),
  ('23d3e66c-e28b-3045-28da-2aed7d0850a3', array['09:47', '9:47']::text[], 'Le journal d’audit conserve l’horodatage de la réinitialisation de mot de passe initiée par l’utilisateur. Cette action intervient à 09:47 UTC.'),
  ('ef12b4d7-49d7-fb1c-a29b-e8cd9a627a38', array['211', '211 minutes', '211 min', '3h31', '3 h 31']::text[], 'La fenêtre d’exposition s’ouvre au premier succès de l’attaquant et se ferme quand la règle de transfert est supprimée. L’écart vaut environ 3 heures et 31 minutes, soit 211 minutes après arrondi à la minute la plus proche.'),
  ('4827bdbc-010f-691f-b2fd-26a953d731b2', array['2026-03-28 09:40', '2026-03-28 09:40 utc', '2026-03-28t09:40:00.000z']::text[], 'Le guide fixe la prise de connaissance au 25 mars 2026 à 09:40 UTC. En ajoutant 72 heures exactes, on obtient l’échéance 2026-03-28 09:40 UTC.'),
  ('2d218ce2-701f-e52e-d6cd-2a388d95da49', array['oui', 'yes']::text[], 'Le guide rappelle qu’une notification est nécessaire lorsqu’une violation expose des données personnelles. Comme la boîte contenait des pièces jointes d’adhérents, la réponse correcte est affirmative.'),
  ('a6a29087-fc74-32b5-52d8-2987fe17d949', array['a']::text[], 'Le confinement immédiat doit couper l’accès de l’attaquant sans détruire les preuves. La bonne réponse est la lettre a, car révoquer les sessions actives puis réinitialiser le mot de passe bloque l’usage du compte compromis tout en préservant le reste de l’environnement pour l’analyse.'),
  ('e5065804-8baf-8c0f-7f9e-1b441c9f7941', array['2']::text[], 'L’attaquant n’utilise pas une seule adresse sur toute la chronologie. En regroupant les authentifications réussies anormales par IP, on en trouve 2, ce qui montre une activité répartie sur plusieurs points d’accès.'),
  ('625ac682-d4f6-b0b8-ab0b-f3a4f64d6c4b', array['fond-incident-audit-boite-yao.log']::text[], 'Le fichier qui prouve l’accès au contenu n’est pas le journal de connexions mais celui de la boîte. Ici, fond-incident-audit-boite-yao.log montre la règle de transfert, les suppressions et les téléchargements.'),
  ('a53182be-393b-0029-290e-9c19b592aa5b', array['25', '25%', '25 %']::text[], 'Le score de domaine se calcule avec la somme des poids multipliés par les statuts, divisée par la somme des poids du domaine. Pour les sauvegardes, ce calcul donne 25 %.'),
  ('99172c3c-3696-aa99-bab3-a931464dd512', array['20', '20%', '20 %']::text[], 'Le score global reprend exactement la même formule que les domaines, mais sur toute la grille. Une fois l’arrondi appliqué, le résultat global atteint 20 %.'),
  ('356020e4-1929-7cff-9372-dd8c1c6dee92', array['a']::text[], 'Le domaine le plus faible est celui dont la part de points obtenus est la plus basse. Après calcul, authentification ressort en dernière position et mérite une attention immédiate.'),
  ('71675368-1d27-082f-9755-f070b0a22b1e', array['13']::text[], 'Le statut « non » vaut zéro point et représente la non-conformité totale. En comptant uniquement ces lignes, on en trouve 13.'),
  ('370f1c7e-e9d2-1900-0321-c050c3cd9110', array['a02']::text[], 'Le guide impose un tri déterministe sur les actions. Après calcul du risque puis comparaison des efforts, A02 arrive en tête du plan d’action.'),
  ('b0f56d80-0792-9f7f-3c74-94d4fff39bb4', array['6']::text[], 'Le guide définit précisément un gain rapide. En filtrant le fichier de risques sur effort 1 puis sur un score d’au moins 6, on obtient 6 actions.'),
  ('f83b43f4-106d-34e2-024a-1c3220c74b08', array['9']::text[], 'Dans le journal des sauvegardes du projet, la dernière ligne SUCCESS date du 2026-03-22. Les échecs qui suivent ne comptent pas. Entre cette date et le 31 mars 2026, il s’est écoulé 9 jours calendaires.'),
  ('29d11aed-2387-2f81-559e-aebf737ab0e3', array['33', '33%', '33 %']::text[], 'Dans le relevé d’accès, 2 salariés sur 6 sont marqués « oui ». Le calcul donne 33 % après arrondi, ce qui mesure la couverture réelle de la double authentification.'),
  ('324fb2ee-b5ac-884a-4464-69d432bd325f', array['4']::text[], 'Le nombre attendu ne se lit plus dans une seule note. Il faut recouper la version de chaque poste avec la table de support du projet, puis compter ceux dont la fin de support est antérieure au 31 mars 2026. On en trouve 4.'),
  ('d46772f2-ba54-cf8c-be83-b31c9b1114f1', array['12']::text[], 'Le certificat de www.soleil.example expire le 2026-04-12. À partir du 31 mars 2026, il reste 12 jours avant l’échéance.'),
  ('1cf8975c-449e-b97c-c8a2-6de260bf2dc3', array['non', 'no']::text[], 'Le journal d’intégrité montre que les archives sont vérifiées avec MD5. La grille ne retient que les algorithmes de la famille SHA-2 ou plus récents : celui-ci est trop ancien pour un contrôle d’intégrité actuel, donc la réponse est négative.'),
  ('d20bef55-1cf5-fbc0-be90-70ff7acefcbe', array['md5']::text[], 'Le journal d’intégrité des sauvegardes annonce l’algorithme MD5 pour les archives du projet. C’est cette valeur qu’il faut ensuite confronter à la règle d’acceptabilité donnée dans la grille.'),
  ('ddfd69b7-9fb3-e154-e4f8-7268a5b88049', array['non', 'no']::text[], 'L’inventaire documentaire de conformité indique l’état du registre des traitements. Ici, il est absent, donc la réponse correcte est négative. La méthode consiste à vérifier la pièce documentaire dédiée plutôt qu’à supposer depuis un simple commentaire.'),
  ('94e6ffe2-b5c5-b499-baaf-44578ab1c513', array['72']::text[], 'Le guide rappelle la règle de base issue du cadre de protection des données : une violation doit être notifiée dans un délai de 72 heures après la prise de connaissance.'),
  ('2b56ed85-51eb-d787-f2bc-1bdeb86d276d', array['3']::text[], 'Le relevé détaillé de simulation permet de compter les personnes marquées comme ayant cliqué. Comme le guide cible d’abord ces personnes, le nombre à sensibiliser en priorité est 3.')
insert into public.lab_assets (id, lab_id, kind, title, description, url, position) values
  ('6964fabb-bd7e-82e9-be23-b7a6291575a1', '0fd79772-16c1-88dd-7689-69dbf1f61367', 'log', 'Courriel brut reçu par Aïssatou (fond-tp1-courriel.log)', 'En-têtes complets, corps texte, corps HTML et métadonnées de la pièce jointe.', '/labs/fond-tp1-courriel.log', 1),
  ('2460d14c-4dbf-541f-f034-2b1ba1999bbb', '0fd79772-16c1-88dd-7689-69dbf1f61367', 'log', 'SMS et conversation mobile (fond-tp1-mobile.log)', 'Un faux SMS de livraison et le dialogue d’un prétendu agent de paiement mobile.', '/labs/fond-tp1-mobile.log', 2),
  ('aa38bcf6-f377-6775-17ff-20d97f0bf12c', '0fd79772-16c1-88dd-7689-69dbf1f61367', 'guide', 'Guide pas à pas du TP 1', 'Méthode, commandes et grille de dix signaux à vérifier un par un.', '/labs/fond-tp1-guide.md', 3),
  ('3a457caa-7691-0357-fcd3-425d2c38c78c', 'db853d51-4336-09b4-eae5-b1b058490092', 'log', 'Inventaire des comptes de messagerie (fond-tp2-inventaire-comptes.log)', 'Quatorze comptes avec rôles, privilèges, ancienneté du mot de passe, double authentification et dernière connexion.', '/labs/fond-tp2-inventaire-comptes.log', 1),
  ('fcc7e7d6-62f2-d289-6190-f61eee5b800c', 'db853d51-4336-09b4-eae5-b1b058490092', 'log', 'Extrait d’empreintes SHA-256 (fond-tp2-empreintes-sha256.log)', 'Huit comptes issus d’un ancien outil interne qui stockait des condensats sans sel.', '/labs/fond-tp2-empreintes-sha256.log', 2),
  ('b309ed75-0ee1-75cc-fd5b-2e06350cda74', 'db853d51-4336-09b4-eae5-b1b058490092', 'guide', 'Dictionnaire fictif à télécharger (fond-tp2-dictionnaire-fictif.txt)', 'Une petite liste de chaînes fictives à hacher pour retrouver quelques secrets faibles du labo.', '/labs/fond-tp2-dictionnaire-fictif.txt', 3),
  ('6528147f-4b75-d005-2082-4c97a739625b', 'db853d51-4336-09b4-eae5-b1b058490092', 'guide', 'Guide pas à pas du TP 2', 'Méthode d’audit, commandes de hachage et repères d’entropie.', '/labs/fond-tp2-guide.md', 4),
  ('b2064169-fbc6-3104-9324-53f5f70c338c', '75586b43-2547-2060-a233-aec440b878c0', 'log', 'Inventaire du parc (fond-tp3-inventaire-postes.tsv)', 'Les 12 postes, leur système, leurs dates et leurs protections locales.', '/labs/fond-tp3-inventaire-postes.tsv', 1),
  ('0e6c35c9-fbce-9acd-8baa-7e8a74fad6d0', '75586b43-2547-2060-a233-aec440b878c0', 'log', 'Fins de support (fond-tp3-support-systemes.tsv)', 'Le tableau des versions présentes et de leur date de fin de support.', '/labs/fond-tp3-support-systemes.tsv', 2),
  ('069cec86-726b-1969-268c-28ae399e62d2', '75586b43-2547-2060-a233-aec440b878c0', 'log', 'Journal des sauvegardes (fond-tp3-sauvegarde-30j.log)', 'Trente jours d’activité de sauvegarde, avec un test de restauration.', '/labs/fond-tp3-sauvegarde-30j.log', 3),
  ('65ac864e-c81a-bfc5-5043-3139b8cbeb33', '75586b43-2547-2060-a233-aec440b878c0', 'log', 'Tableau des copies 3-2-1 (fond-tp3-copies-321.txt)', 'Les copies observées, leur support et leur lieu de stockage.', '/labs/fond-tp3-copies-321.txt', 4),
  ('fa3a7da0-8541-76f5-4c60-511efeb16046', '75586b43-2547-2060-a233-aec440b878c0', 'guide', 'Guide du TP 3', 'Méthode, grille de score, formule de conformité et commandes de vérification.', '/labs/fond-tp3-guide.md', 5),
  ('cb2d691a-8459-2962-205a-c0b0189091b5', '3fddeace-1761-3450-bd81-bfb403bb73a3', 'guide', 'Fichier A à vérifier (fond-tp4-outil-a.txt)', 'Petit fichier texte de configuration à contrôler par empreinte.', '/labs/fond-tp4-outil-a.txt', 1),
  ('8df69bc8-dc5a-5abc-c5fa-90f8dd12afe3', '3fddeace-1761-3450-bd81-bfb403bb73a3', 'guide', 'Fichier B à vérifier (fond-tp4-outil-b.txt)', 'Petit fichier texte de configuration, dont un caractère a été modifié par rapport au manifeste.', '/labs/fond-tp4-outil-b.txt', 2),
  ('be2b6238-2dd9-f107-789b-c74ab8a328e3', '3fddeace-1761-3450-bd81-bfb403bb73a3', 'guide', 'Fichier C à vérifier (fond-tp4-outil-c.txt)', 'Petit fichier texte de contrôle à comparer au manifeste publié.', '/labs/fond-tp4-outil-c.txt', 3),
  ('ef57d16b-c094-be21-e294-058f97a234fa', '3fddeace-1761-3450-bd81-bfb403bb73a3', 'log', 'Manifeste des empreintes publiées (fond-tp4-manifeste-sha256.log)', 'Trois empreintes SHA-256 annoncées par l’éditeur pour les fichiers A, B et C.', '/labs/fond-tp4-manifeste-sha256.log', 4),
  ('36830642-87a0-bfb6-5836-48f4e38fee20', '3fddeace-1761-3450-bd81-bfb403bb73a3', 'log', 'Messages à décoder (fond-tp4-messages-a-decoder.log)', 'Un exemple en Base64, un en hexadécimal, un en César et deux condensats à reconnaître.', '/labs/fond-tp4-messages-a-decoder.log', 5),
  ('733d3bde-fe45-66cf-a6cb-8b4dd3ce2e70', '3fddeace-1761-3450-bd81-bfb403bb73a3', 'log', 'Sortie texte des certificats (fond-tp4-certificats.log)', 'Deux certificats X.509 fictifs au style openssl x509 -text.', '/labs/fond-tp4-certificats.log', 6),
  ('5cb90ea6-0c0d-07cd-e45f-bd230c9a762a', '3fddeace-1761-3450-bd81-bfb403bb73a3', 'guide', 'Guide pas à pas du TP 4', 'Vérification d’intégrité, décodage et lecture de certificats.', '/labs/fond-tp4-guide.md', 7),
  ('9661a814-5215-4583-c903-e73ca1849b31', 'abd6404e-6914-ba7f-6a04-a0faae4f4122', 'log', 'Inventaire des actifs (fond-tp5-actifs.tsv)', 'Les actifs à protéger, leur type et leurs besoins C I D.', '/labs/fond-tp5-actifs.tsv', 1),
  ('d5f3896d-dfde-d197-d455-c5fa37e7c16e', 'abd6404e-6914-ba7f-6a04-a0faae4f4122', 'log', 'Scénarios de risques (fond-tp5-scenarios.tsv)', 'Les menaces, vulnérabilités et cotations de l’atelier.', '/labs/fond-tp5-scenarios.tsv', 2),
  ('61966a24-7202-d624-987e-088af93b1818', 'abd6404e-6914-ba7f-6a04-a0faae4f4122', 'log', 'Incidents passés (fond-tp5-incidents.txt)', 'Six incidents résumés en une phrase chacun.', '/labs/fond-tp5-incidents.txt', 3),
  ('cdf27035-8e81-3ea4-fd7a-2586d4a0eb7b', 'abd6404e-6914-ba7f-6a04-a0faae4f4122', 'log', 'Droits sur la comptabilité (fond-tp5-acces-compta.tsv)', 'La table de lecture, d’écriture et de suppression sur le partage comptable.', '/labs/fond-tp5-acces-compta.tsv', 4),
  ('de2627dc-6ced-2a87-7df9-f954aa3818ee', 'abd6404e-6914-ba7f-6a04-a0faae4f4122', 'guide', 'Guide du TP 5', 'Méthode de cotation, niveaux, traitements et rappel du moindre privilège.', '/labs/fond-tp5-guide.md', 5),
  ('2aae8d7c-7086-e31b-6f75-be0b42882dd4', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 'log', 'Journal des connexions (fond-incident-connexions-messagerie.log)', 'Les authentifications sur environ trente-six heures, avec les succès et échecs du personnel.', '/labs/fond-incident-connexions-messagerie.log', 1),
  ('938d7241-04d2-7941-5888-c26692e3859e', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 'log', 'Table de géolocalisation (fond-incident-geoloc-ip.tsv)', 'Le pays fictif et le fournisseur associés à chaque adresse IP observée.', '/labs/fond-incident-geoloc-ip.tsv', 2),
  ('df9b2f82-a37d-51c2-17db-0ba384cf40c8', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 'log', 'Journal d’audit de la boîte de Yao (fond-incident-audit-boite-yao.log)', 'Les opérations internes à la boîte compromise.', '/labs/fond-incident-audit-boite-yao.log', 3),
  ('1e63dd3c-47c5-7ae5-552e-8bdd7aac5bc4', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 'log', 'Courriel d’hameçonnage signalé (fond-incident-courriel-phishing.eml)', 'Le message reçu la veille par Yao, avec ses en-têtes courts.', '/labs/fond-incident-courriel-phishing.eml', 4),
  ('4a84a080-c46c-7a19-770e-648de62626f8', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 'report_template', 'Modèle de chronologie d’incident', 'Un tableau vide pour reconstruire les étapes de l’incident.', '/labs/fond-incident-chronologie.md', 5),
  ('ecf035ff-5184-cb4a-dc59-99c50201d4e8', 'a4e51978-2e64-b285-a90f-7ee13bc08b82', 'guide', 'Guide de l’incident', 'Méthode d’analyse, règle des 72 heures et rappel du bon confinement.', '/labs/fond-incident-guide.md', 6),
  ('418037c0-4e2a-aef3-b9f7-61563e3fba22', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 'log', 'Notes de terrain (fond-projet-notes-terrain.md)', 'Les constats factuels relevés pendant la visite d’audit du 31 mars.', '/labs/fond-projet-notes-terrain.md', 1),
  ('1a9c59cb-0f73-ce03-c4bc-0c3534e95f7a', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 'guide', 'Grille d’audit (fond-projet-grille-audit.md)', 'Les 24 contrôles pondérés et leur statut de conformité.', '/labs/fond-projet-grille-audit.md', 2),
  ('446b7b0c-0198-f745-502b-e4bc1de9b800', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 'log', 'Risques associés (fond-projet-risques.tsv)', 'Le fichier de priorisation par vraisemblance, impact et effort.', '/labs/fond-projet-risques.tsv', 3),
  ('3ea5c6eb-f264-839b-161c-8faa1d160d1c', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 'log', 'Inventaire des postes du projet', 'Les postes utilisés pour le recoupement avec la table de support.', '/labs/fond-projet-postes.tsv', 4),
  ('376ac521-7c35-b632-5919-8b57edd4941d', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 'log', 'Table de support du projet', 'Les dates de fin de support des systèmes présents dans l’audit final.', '/labs/fond-projet-support-systemes.tsv', 5),
  ('7b6d3215-3ae4-987e-4a0a-88e1f4a3821b', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 'log', 'Journal d’intégrité des sauvegardes', 'Les archives de sauvegarde et l’algorithme de contrôle annoncé.', '/labs/fond-projet-integrite-sauvegardes.tsv', 6),
  ('999805ad-11e1-c24c-758c-297c1290b391', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 'log', 'Relevé d’accès et MFA', 'Les six salariés et l’état de la double authentification au moment de l’audit.', '/labs/fond-projet-acces-mfa.tsv', 7),
  ('84f4f36f-177a-dd85-f4af-b2946980d58d', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 'log', 'Journal des sauvegardes du projet', 'Les dernières exécutions de sauvegarde utilisées pour recalculer l’ancienneté.', '/labs/fond-projet-sauvegardes.log', 8),
  ('85901736-1530-2ed3-daf6-a3e31f871cda', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 'log', 'Inventaire documentaire de conformité', 'Les documents de protection des données disponibles ou absents.', '/labs/fond-projet-conformite-donnees.tsv', 9),
  ('cfc9fc06-1acc-780b-6a73-9a13050ecd94', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 'log', 'Relevé détaillé de simulation de phishing', 'Le détail personne par personne du dernier exercice de sensibilisation.', '/labs/fond-projet-simulation-phishing.tsv', 10),
  ('51d2894e-c1d2-6fbc-f1aa-944aa098842f', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 'report_template', 'Modèle de rapport final', 'Une structure simple pour rédiger le rapport d’audit bénévole.', '/labs/fond-projet-modele-rapport.md', 11),
  ('17375fb7-eb9e-a6d1-51d5-2c2aaeea1e24', '379b6ed7-3b5e-556d-50ef-692a3ad1c54f', 'guide', 'Guide du projet final', 'Formules de score, règle de priorité et repères pour le rendu d’audit.', '/labs/fond-projet-guide.md', 12)
insert into public.skills (id, domain_id, slug, name, description, position) values
  ('cc5a3634-3adc-8db1-f788-7d57746cf51e', 'd6aaead7-1a0b-8325-6fb7-d17ad9d4bf6a', 'principes-securite', 'Principes de sécurité', 'Classer un incident selon la confidentialité, l’intégrité et la disponibilité, et appliquer le moindre privilège et la défense en profondeur.', 410),
  ('8a975572-a93c-95dd-a517-35e51c09e2f8', 'd6aaead7-1a0b-8325-6fb7-d17ad9d4bf6a', 'ingenierie-sociale', 'Ingénierie sociale et hameçonnage', 'Repérer les leviers d’une manipulation et les signes d’un courriel, d’un SMS ou d’un appel frauduleux, puis réagir.', 420),
  ('f97f3b18-b26c-839e-1d18-187007d66ed7', 'd6aaead7-1a0b-8325-6fb7-d17ad9d4bf6a', 'authentification-forte', 'Authentification forte', 'Évaluer des mots de passe, comprendre le hachage et choisir une double authentification adaptée.', 430),
  ('85d543b9-fb56-3cc2-309b-c72dd8844a1b', 'd6aaead7-1a0b-8325-6fb7-d17ad9d4bf6a', 'hygiene-numerique', 'Hygiène numérique', 'Contrôler les mises à jour, l’antivirus, le chiffrement des disques et les sauvegardes d’un parc de postes.', 440),
  ('5a60a730-e9f2-218e-7ba7-f0566b071887', 'd6aaead7-1a0b-8325-6fb7-d17ad9d4bf6a', 'bases-cryptographie', 'Bases de la cryptographie', 'Distinguer encoder, chiffrer et hacher, vérifier l’intégrité d’un fichier et lire un certificat.', 450),
  ('ce858f2d-3b91-5245-ba03-073e9ab1fcb4', 'd6aaead7-1a0b-8325-6fb7-d17ad9d4bf6a', 'analyse-risques', 'Analyse de risques', 'Noter des scénarios par vraisemblance et impact, prioriser et choisir un traitement.', 460),
  ('02984e55-b797-a997-b9ab-1cddb4f5eba1', 'd6aaead7-1a0b-8325-6fb7-d17ad9d4bf6a', 'protection-donnees', 'Protection des données personnelles', 'Repérer les données personnelles, appliquer les principes de protection et calculer le délai de notification d’une violation.', 470),
  ('570b54c1-06fa-b54c-2d72-f5c393d63fa0', 'd6aaead7-1a0b-8325-6fb7-d17ad9d4bf6a', 'reponse-incident', 'Réponse à incident', 'Reconstituer une chronologie, confiner une compromission et préserver les preuves.', 480)
