update public.course_modules set title = 'Comprendre la cybersécurité', description = 'Tu poses ici le vocabulaire, les menaces et les principes qui servent à lire n’importe quel problème de sécurité sans paniquer ni improviser. Critères de réussite : distinguer actif, menace, vulnérabilité et risque ; classer un incident selon confidentialité, intégrité ou disponibilité ; expliquer comment le moindre privilège et la défense en profondeur réduisent l’impact.'
where id = '9eb524ae-1b27-a325-539d-bda421c0627e' and title = 'Comprendre la cybersécurité';
update public.course_modules set position = 1 where id = '9eb524ae-1b27-a325-539d-bda421c0627e';
update public.course_modules set title = 'L’écosystème de la sécurité', description = 'Ce module te montre qui agit dans la cybersécurité, comment ces rôles deviennent des métiers, et quels cadres guident une pratique sérieuse au quotidien. Critères de réussite : attribuer le bon rôle à chaque étape d’un incident ; relier un métier à ses missions et à un parcours d’apprentissage réaliste ; choisir un référentiel ou une loi pertinente selon le besoin d’une petite structure.'
where id = '31387ec3-76c8-0172-1b3a-e2409798e572' and title = 'L’écosystème de la sécurité';
update public.course_modules set position = 2 where id = '31387ec3-76c8-0172-1b3a-e2409798e572';

on conflict (id) do nothing;

update public.lessons set title = 'Qu’est-ce que la cybersécurité ?', summary = 'Définis la cybersécurité avec ses mots-clés, comprends pourquoi elle concerne aussi bien un téléphone qu’une petite structure, et apprends à raisonner en actifs, menaces, vulnérabilités et risques.', content = '{"blocks":[{"type":"callout","content":"Objectifs : définir la cybersécurité, distinguer actif, menace, vulnérabilité, risque, attaque, impact et incident, expliquer la triade confidentialité, intégrité, disponibilité, inventorier tes actifs numériques, et estimer le coût simple d’une journée d’arrêt."},{"type":"callout","content":"Prérequis : aucun."},{"type":"callout","content":"Mise en situation : Awa aide la coopérative Harmattan à gérer ses ventes sur téléphone et ordinateur. Un lundi matin, la messagerie ne répond plus et des factures ne sortent plus. Tout le monde parle de « piratage » sans préciser ce qui est touché. Pour réagir proprement, Awa doit d’abord comprendre ce que la cybersécurité protège et comment nommer le problème."},{"type":"callout","content":"Vidéo à venir : Comprendre la cybersécurité sans jargon inutile"},{"type":"text","content":"La cybersécurité protège les systèmes, les réseaux, les données et les personnes contre les usages non autorisés, les manipulations et les interruptions. La sécurité informatique vise surtout les ordinateurs et les réseaux. La sécurité de l’information est plus large : elle protège l’information sur tout support. La cybersécurité emprunte aux deux, avec un angle très concret sur les usages numériques."},{"type":"schema","content":"Mot                  Définition simple\nActif                ce qui a de la valeur\nMenace               ce qui peut causer un dommage\nVulnérabilité        faiblesse exploitable\nRisque               dommage plausible et impact estimé\nAttaque              action malveillante\nImpact               conséquence subie\nIncident             événement qui perturbe ou compromet"},{"type":"text","content":"On parle souvent de la triade C, I, D : confidentialité, intégrité, disponibilité. La confidentialité limite l’accès aux bonnes personnes. L’intégrité garantit qu’une information reste correcte. La disponibilité assure que le service reste accessible quand on en a besoin. Ces trois propriétés servent à décrire clairement ce qui est abîmé."},{"type":"schema","content":"Propriété            Exemple d’atteinte\nConfidentialité     fuite d’une liste de clients\nIntégrité           facture falsifiée avant validation\nDisponibilité       rançongiciel qui bloque les postes"},{"type":"text","content":"La cybersécurité n’est pas seulement une affaire d’experts. Ton téléphone, ta messagerie, ton argent mobile ou les dossiers d’une petite structure sont des actifs numériques. Les trois piliers sont les personnes, les processus et la technologie. Aucun système n’est sécurisé à 100 %. Le but réaliste est de réduire le risque, pas de promettre l’impossible."},{"type":"text","content":"Démonstration guidée : fais l’inventaire de tes actifs numériques avant de parler d’attaque. Sur ordinateur ou dans l’application Notes du téléphone, note ce qui existe, à quoi cela sert et ce qui ferait le plus mal en cas de perte, de fuite ou de blocage."},{"type":"code","content":"Actif                    Support         Pourquoi c’est important ?\nMessagerie principale    téléphone       réinitialisation des autres comptes\nCompte de paiement       téléphone       argent et historique des opérations\nDossiers clients         ordinateur      activité de la structure\nPhotos d’identité        cloud           données personnelles\nCarnet d’adresses        téléphone       continuité de contact","language":"text"},{"type":"example","content":"Exemple corrigé : un petit atelier réalise 8 réparations par jour et gagne 6 000 FCFA de marge par réparation. Une journée d’arrêt coûte donc environ 48 000 FCFA de marge, calcul simple : 8 x 6 000 = 48 000. Sans même compter les retards, la disponibilité a déjà une vraie valeur métier."},{"type":"callout","content":"Erreurs fréquentes : réduire la cybersécurité aux antivirus ; confondre menace et vulnérabilité, par exemple appeler « mot de passe faible » une menace ; croire qu’un incident est forcément un grand piratage ; attendre une sécurité parfaite au lieu de réduire le risque tout de suite."},{"type":"callout","content":"Sécurité : si tu fais un inventaire ou un diagnostic, reste sur tes propres comptes, appareils et données, ou travaille avec une autorisation claire. Comprendre une attaque sert à mieux se défendre, pas à tester le système d’un tiers."},{"type":"callout","content":"À retenir : la cybersécurité protège des actifs numériques qui ont une valeur réelle. La triade confidentialité, intégrité, disponibilité aide à décrire l’impact. Les personnes, les processus et la technologie travaillent ensemble, et l’objectif réaliste est de réduire le risque."},{"type":"callout","content":"Pour pratiquer : ouvre « TP 5 : construire un registre de risques ». Classe chaque incident par confidentialité, intégrité ou disponibilité, puis réutilise ton propre inventaire d’actifs pour juger ce qui compte le plus. Termine par le quiz de la leçon."},{"type":"resource","content":"Cybermalveillance.gouv.fr : prévention et assistance aux victimes","url":"https://www.cybermalveillance.gouv.fr/"},{"type":"resource","content":"CISA : Secure Our World, les gestes de base (en anglais)","url":"https://www.cisa.gov/secure-our-world"},{"type":"resource","content":"NIST : ressources de cybersécurité pour les petites entreprises (en anglais)","url":"https://www.nist.gov/itl/smallbusinesscyber"}]}'::jsonb, duration_minutes = 20, xp_reward = 40
where id = 'f224ac19-650c-93e5-75f9-1276cc02ae0a' and content = '{"blocks":[{"type":"text","content":"La cybersécurité désigne l''ensemble des pratiques, technologies et processus conçus pour protéger les systèmes informatiques, les réseaux et les données contre les attaques, les dommages ou les accès non autorisés."},{"type":"schema","content":"Confidentialité → protéger les données privées\nIntégrité → garantir que les données ne sont pas altérées\nDisponibilité → assurer l''accès aux services quand on en a besoin"},{"type":"text","content":"Ces trois piliers forment la triade CIA (Confidentiality, Integrity, Availability). Toute décision en sécurité informatique se réfère à l''un ou plusieurs de ces principes."},{"type":"example","content":"Exemple : un ransomware (rançongiciel) viole la disponibilité en chiffrant tes fichiers. Un keylogger viole la confidentialité en capturant tes frappes au clavier."}]}'::jsonb;
update public.lessons set title = 'Les types de menaces informatiques', summary = 'Apprends à reconnaître les grandes familles de menaces, leur vecteur d’attaque habituel, la propriété de sécurité la plus touchée et la parade prioritaire à mettre en place.', content = '{"blocks":[{"type":"callout","content":"Objectifs : reconnaître les principales familles de menaces, définir un vecteur d’attaque, relier une menace à la propriété C, I ou D la plus touchée, décrire un cycle d’attaque simplifié, et classer des incidents concrets."},{"type":"callout","content":"Prérequis : avoir suivi « Qu’est-ce que la cybersécurité ? » ou déjà connaître la différence entre confidentialité, intégrité et disponibilité."},{"type":"callout","content":"Mise en situation : Koffi rejoint Atlas pour trier plusieurs incidents le même jour : faux message de paiement, ordinateur chiffré, mot de passe réutilisé, Wi-Fi public douteux, téléphone oublié dans un taxi. Si tout est rangé dans la case « attaque », l’équipe répondra mal. Koffi doit donc reconnaître la famille de menace, le point d’entrée probable et la parade principale."},{"type":"callout","content":"Vidéo à venir : Panorama des menaces informatiques pour débuter"},{"type":"text","content":"Une menace informatique est une famille de situations capables d’endommager un actif. Le vecteur d’attaque est la porte d’entrée utilisée : courriel, pièce jointe, mot de passe faible, réseau non sûr, appareil perdu ou fournisseur compromis. Deux incidents proches peuvent donc demander des parades très différentes."},{"type":"schema","content":"Famille                Exemple simple\nLogiciel malveillant   virus, ver, cheval de Troie, espion,\n                       enregistreur de frappe, rançongiciel,\n                       agent de botnet\nIngénierie sociale     faux support, hameçonnage, appel urgent\nMots de passe          devinette, dictionnaire, réutilisation\nRéseau                 interception sur Wi-Fi non sûr, DoS, DDoS"},{"type":"text","content":"Les logiciels malveillants regroupent plusieurs comportements. Un virus s’attache à un fichier, un ver se propage seul, un cheval de Troie se fait passer pour légitime, un logiciel espion collecte des données, et un rançongiciel bloque ou chiffre pour extorquer. À côté de cela, l’ingénierie sociale manipule la personne, les attaques sur mots de passe visent les comptes, le déni de service surcharge un service, et une faille non corrigée ouvre parfois la porte."},{"type":"schema","content":"Menace                 C/I/D     Exemple               Parade principale\nRançongiciel           D         fichiers bloqués       sauvegardes + mises à jour\nFuite d’identifiants   C         compte réutilisé       mots de passe uniques + MFA\nFacture falsifiée      I         montant modifié        double validation\nDoS ou DDoS            D         site saturé            filtrage + capacité réseau\nVol d’appareil         C, D      téléphone perdu        chiffrement + verrouillage"},{"type":"text","content":"On peut aussi raisonner avec un cycle d’attaque simplifié : reconnaissance, accès initial, installation ou déplacement, puis action sur l’objectif. Les menaces internes comptent aussi, par erreur ou malveillance. Pense également à la chaîne d’approvisionnement, quand un fournisseur, un logiciel tiers ou un prestataire devient la porte d’entrée."},{"type":"text","content":"Démonstration guidée : lis un incident court et réponds à trois questions dans cet ordre : quel est le vecteur probable, quelle propriété C, I ou D est la plus touchée, et quelle parade principale vient d’abord ? Sur téléphone, fais le même exercice dans une note."},{"type":"code","content":"Incident : « Un comptable reçoit un message urgent,\nouvre une pièce jointe et ses documents deviennent\nillisibles. Un message réclame un paiement. »\n\nVecteur probable : pièce jointe piégée\nPropriété la plus touchée : disponibilité\nParade principale : isoler le poste, restaurer depuis\nune sauvegarde saine, vérifier les mises à jour","language":"text"},{"type":"example","content":"Exemple corrigé : 1) faux message de virement : fraude, intégrité, double validation ; 2) identifiants réutilisés : attaque sur mots de passe, confidentialité, mots de passe uniques puis MFA ; 3) serveur saturé : DoS, disponibilité, filtrage ; 4) portable volé : confidentialité, chiffrement et effacement ; 5) faille non corrigée : entrée par vulnérabilité, parade par mises à jour."},{"type":"callout","content":"Erreurs fréquentes : mélanger menace et vecteur d’attaque ; croire qu’un rançongiciel touche d’abord la confidentialité ; oublier les menaces internes ; chercher une parade compliquée alors qu’une mise à jour ou une double validation coupe déjà le scénario."},{"type":"callout","content":"Sécurité : n’essaie pas de reproduire une attaque réelle sur un système tiers pour « voir ». L’objectif d’une telle classification est défensif : reconnaître vite, contenir et orienter la bonne réponse."},{"type":"callout","content":"À retenir : les menaces se distinguent par leur mode d’action, leur vecteur d’entrée et la propriété qu’elles touchent le plus. Le bon réflexe est d’identifier la famille, le point d’entrée probable et la parade prioritaire."},{"type":"callout","content":"Pour pratiquer : ouvre « TP 5 : construire un registre de risques ». Classe les incidents par famille de menace et par propriété C, I ou D la plus touchée, puis compare avec la parade proposée. Termine par le quiz de la leçon."},{"type":"resource","content":"Cybermalveillance.gouv.fr : fiche réflexe contre les rançongiciels","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/rancongiciels-ransomwares"},{"type":"resource","content":"CISA : arrêter les rançongiciels (en anglais)","url":"https://www.cisa.gov/stopransomware"}]}'::jsonb, duration_minutes = 22, xp_reward = 45
where id = '3f531e71-da67-19ff-2426-096e0261b189' and content = '{"blocks":[{"type":"text","content":"Les cybermenaces se classifient en plusieurs catégories : malwares, phishing, attaques par déni de service (DoS/DDoS), ingénierie sociale, et exploitation de vulnérabilités logicielles."},{"type":"schema","content":"Malware : virus, vers, trojans, ransomware, spyware\nPhishing : email frauduleux imitant une entité de confiance\nDDoS : saturation d''un serveur par des millions de requêtes\nIngénierie sociale : manipulation psychologique d''un utilisateur"},{"type":"text","content":"La majorité des attaques réussies exploitent l''humain, pas la technologie. C''est pourquoi la sensibilisation est aussi importante que les outils techniques."},{"type":"example","content":"Exemple réel : le phishing représente plus de 80% des cyberattaques réussies en entreprise selon les rapports annuels de l''ANSSI."}]}'::jsonb;
update public.lessons set title = 'Les acteurs de la cybersécurité', summary = 'Découvre qui attaque, qui défend, qui coordonne, qui corrige et pourquoi l’autorisation écrite fait toute la différence entre recherche légitime et acte illicite.', content = '{"blocks":[{"type":"callout","content":"Objectifs : distinguer les grands types d’acteurs, expliquer les rôles de red team, blue team et purple team, situer SOC, CERT ou CSIRT, RSSI et DPO, et relier chaque rôle à une réponse à incident."},{"type":"callout","content":"Prérequis : avoir suivi les trois leçons du module « Comprendre la cybersécurité »."},{"type":"callout","content":"Mise en situation : Sahel Services découvre qu’un compte de messagerie a été compromis. L’équipe technique veut couper l’accès, la direction veut rassurer les clients, et personne ne sait qui appeler pour vérifier l’angle données personnelles. En parallèle, un collègue demande si un « hacker éthique » peut tester la plateforme. Pour éviter la confusion, il faut savoir qui fait quoi et dans quel cadre légal."},{"type":"callout","content":"Vidéo à venir : Qui fait quoi en cybersécurité ?"},{"type":"text","content":"Tous les attaquants n’ont pas la même motivation. Les cybercriminels cherchent souvent l’argent. Les hacktivistes visent un message politique. Les acteurs étatiques recherchent l’influence ou l’espionnage. Les menaces internes viennent de personnes déjà proches de l’organisation, par erreur ou malveillance. Il existe aussi des curieux qui testent sans droit."},{"type":"schema","content":"Motivation             Exemple de but\nFinancière            voler, extorquer, frauder\nPolitique             afficher un message, perturber\nÉtatique              espionner, préparer une influence\nInterne               abuser d’un accès déjà obtenu\nCuriosité             tester sans autorisation"},{"type":"text","content":"Les « chapeaux » aident à discuter, mais ne remplacent jamais la loi. Un white hat agit avec autorisation. Un black hat agit sans droit. Le grey hat existe dans certains discours, mais l’absence d’autorisation écrite reste un vrai problème juridique et éthique. Côté défense, la red team simule des attaques dans un cadre autorisé, la blue team détecte et répond, la purple team fait progresser les deux, et le SOC surveille les alertes au quotidien."},{"type":"schema","content":"Acteurs et relations\nUtilisateur -> signale un problème au SOC ou au support\nSOC / blue team -> analyse, contient, escalade\nCERT ou CSIRT -> coordonne la réponse à incident\nRSSI -> décide des priorités de sécurité\nDPO -> suit l’angle données personnelles\nÉditeur -> fournit correctifs et avis\nAutorité nationale -> publie guides et alertes"},{"type":"text","content":"Autour de l’incident, d’autres rôles comptent. Le CERT ou CSIRT coordonne la réponse. Le RSSI pilote la sécurité à l’échelle de la structure. Le DPO suit la protection des données personnelles. Les auditeurs évaluent, les chercheurs en vulnérabilités divulguent de façon responsable, les éditeurs publient des correctifs, et des autorités comme l’ANSSI diffusent des recommandations. L’utilisateur reste souvent le premier à voir un signe anormal."},{"type":"text","content":"Démonstration guidée : entraîne-toi à attribuer les rôles avant un vrai incident. Lis la scène, puis associe chaque action à l’acteur le plus logique. Sur téléphone, fais le même exercice dans une note. Le but n’est pas de retenir des sigles, mais de savoir qui alerter et qui décide."},{"type":"code","content":"Scène : « Une boîte mail envoie des messages suspects. »\n\nUtilisateur : signale le comportement inhabituel\nSOC ou support : confirme l’anomalie\nBlue team / admin : révoque les sessions et change l’accès\nRSSI : arbitre la priorité et la communication interne\nDPO : évalue l’impact sur les données personnelles\nÉditeur : fournit un correctif si une faille est en cause","language":"text"},{"type":"example","content":"Exemple corrigé : si une petite structure subit une compromission de messagerie, la blue team ou l’administrateur coupe les sessions, le support collecte les indices, le responsable sécurité coordonne, le DPO regarde l’impact sur les données personnelles, et la direction prépare la communication. Un pentest extérieur n’intervient que s’il est autorisé."},{"type":"callout","content":"Erreurs fréquentes : croire que tous les attaquants poursuivent le même objectif financier ; appeler « éthique » toute action non autorisée sous prétexte qu’elle révèle une faille ; réduire la réponse à incident au seul technicien alors que coordination, juridique et communication comptent aussi ; oublier que l’utilisateur est souvent le premier capteur du problème."},{"type":"callout","content":"Sécurité : ne teste jamais un système qui n’est pas le tien sans accord explicite et écrit. La frontière pratique entre recherche légitime, audit autorisé et intrusion illégale se joue d’abord sur l’autorisation et le périmètre."},{"type":"callout","content":"À retenir : l’écosystème de la cybersécurité réunit des motivations, des métiers et des responsabilités différentes. Bien réagir, c’est savoir qui détecte, qui décide, qui corrige, qui documente et dans quel cadre légal chacun agit."},{"type":"callout","content":"Pour pratiquer : ouvre « Incident : un compte de messagerie compromis ». Observe qui fait quoi dans la chronologie et note quand la technique ne suffit plus sans coordination. Termine par le quiz de la leçon."},{"type":"resource","content":"ANSSI : le portail de la cybersécurité","url":"https://cyber.gouv.fr/"},{"type":"resource","content":"NIST SP 800-61 : guide de gestion des incidents de sécurité (en anglais)","url":"https://csrc.nist.gov/pubs/sp/800/61/r2/final"}]}'::jsonb, duration_minutes = 18, xp_reward = 40
where id = '28d13e07-9a2a-461d-f792-f8e2f439127d' and content = '{"blocks":[{"type":"text","content":"On distingue plusieurs profils dans l''écosystème de la cybersécurité : les attaquants (black hat), les défenseurs (blue team), les auditeurs offensifs (red team / pentesters) et les chercheurs (white hat)."},{"type":"schema","content":"Red Team (offensif) : simule des attaques pour tester les défenses\nBlue Team (défensif) : détecte, analyse et répond aux incidents\nPurple Team : collaboration Red + Blue pour améliorer la posture globale\nSOC : Security Operations Center — surveillance 24h/24"},{"type":"text","content":"En tant qu''apprenant Cyberpingo, tu vas progressivement maîtriser les deux côtés : comprendre les techniques d''attaque pour mieux défendre."}]}'::jsonb;

