update public.quiz_questions set explanation = 'La confidentialité consiste bien à limiter l’accès aux personnes autorisées. Rendre toutes les données publiques fait exactement l’inverse, et supprimer les sauvegardes aggrave en plus le risque sur la disponibilité sans protéger l’accès.'
where id = '40d2e2f4-21e8-9d7c-7f4c-3508395a7354' and explanation = 'La confidentialité protège l’accès aux informations.';
update public.quiz_questions set explanation = 'La blue team travaille surtout sur la défense, la détection et la réponse aux incidents. Elle ne fabrique pas de publicités et elle ne supprime pas les contrôles de sécurité : ces deux options sont tentantes si on pense « équipe support », mais elles n’ont rien à voir avec sa mission principale.'
where id = 'e19b3241-f649-851a-8400-c3bc67f3ec69' and explanation = 'Elle protège les systèmes et traite les événements de sécurité.';

