where c.id = '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438' and s.course_id = c.id and c.estimated_duration < s.total;

update public.courses set short_description = 'Menaces, hameçonnage, mots de passe, sauvegardes, cryptographie, risques et réponse à incident : le parcours d’entrée pour acquérir les bons réflexes et réaliser un premier audit d’hygiène.', description = 'Ce parcours t’apprend à comprendre les menaces qui visent les personnes et les petites structures, à te protéger au quotidien et à réagir quand un incident survient. Huit modules progressifs couvrent les principes de la sécurité, l’écosystème des acteurs et des référentiels, l’ingénierie sociale et l’hameçonnage, les mots de passe et la double authentification, les mises à jour, les sauvegardes et le chiffrement des appareils, la cryptographie pour débutants, l’analyse de risques et la protection des données personnelles, puis la réponse à incident.

Chaque leçon propose un cours détaillé, des exemples corrigés et un quiz avec correction. Cinq travaux pratiques guidés, un incident à reconstituer et un projet final d’audit te font manipuler ce que tu apprends sur des fichiers réalistes, avec des critères de réussite vérifiés par la plateforme.

Compétences visées : reconnaître un message frauduleux, auditer des mots de passe et des comptes, contrôler l’hygiène d’un parc de postes, vérifier l’intégrité d’un fichier, noter et prioriser des risques, reconstituer une compromission et rédiger les recommandations d’un audit.

Aucun prérequis : un téléphone ou un ordinateur suffit, et tous les outils utilisés sont gratuits. Les vidéos sont en préparation : chaque leçon indique clairement quand la sienne n’est pas encore disponible, et le cours écrit couvre déjà l’essentiel.'
where id = '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438' and short_description = 'Les bases indispensables avant de plonger dans la sécurité informatique.' and description = 'Ce que la cybersécurité protège, les grandes familles de menaces et les acteurs qui défendent nos systèmes. Le point de départ idéal, sans prérequis.';

